(window.GIM_TS=window.GIM_TS||{})["Sanhedrin.3"]={"from":72,"a":[["\u0003והיא,\u0004 אמו של שאלתיאל, \u0003נתעברה מעומד\u0004 בצינוק שבבית הסוהר. \u0003דבר אחר: \"שלתיאל\"\u0004 נדרש כך: \u0003שנשאל על אלתו\u0004 (שבועתו) \u0003אל,\u0004 שהקדוש ברוך הוא שנשבע שלא יהיה זכר ליכניה נשאל על השבועה והפרה. \u0003\"זרובבל\"\u0004 — \u0003שנזרע\u0004 (נוצר) \u0003בבבל, ומה שמו?\u0004 — \u0003נחמיה בן חכליה שמו.\u0004","אגב הזכרת בני ר' חייא מסופר: \u0003יהודה וחזקיה בני ר' חייא הוו יתבי בסעודתא קמי\u0004 \u0005[היו יושבים בסעודה לפני]\u0006 \u0003רבי, ולא הוו קא אמרי\u0004 \u0005[היו אומרים]\u0006 \u0003ולא מידי\u0004 \u0005[דבר].\u0006 \u0003אמר להו\u0004 \u0005[להם\u0006 רבי לשמשים\u0005]:\u0006 \u0003אגברו חמרא אדרדקי, כי היכי דלימרו מילתא\u0004 \u0005[הוסיפו יין לנערים, כדי שיאמרו דבר\u0006 מה\u0005].\u0006 \u0003כיון דאיבסום\u0004 \u0005[שהשתכרו],\u0006 \u0003פתחו ואמרו: אין בן דוד\u0004 המשיח \u0003בא עד שיכלו שני בתי אבות מישראל\u0004 שהם המעכבים את הגאולה, \u0003ואלו הן: ראש גולה שבבבל ונשיא שבארץ ישראל, שנאמר: \"והיה למקדש ולאבן נגף ולצור מכשול לשני בתי ישראל\"\u0004 (ישעיה ח, יד).","\u0003אמר להם\u0004 רבי: \u0003בניי, קוצים אתם מטילין לי בעיניי?\u0004 כלומר, וכי אומרים דבר עלבון כזה בפני הנשיא עצמו? \u0003אמר לו ר' חייא: רבי, אל ירע בעיניך\u0004 כי \u0003יין ניתן בשבעים אותיות,\u0004 שזהו חשבון האותיות של המלה \"יין\", \u0003ו\u0004אף \u0003סוד ניתן בשבעים אותיות, נכנס יין\u0004 — \u0003יצא סוד.\u0004","ועוד בענין גלות וכפרה \u0003אמר רב חסדא אמר מר עוקבא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר\u0004 זאת \u0003רב חסדא, דרש מרי בר מר: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"וישקד ה' על הרעה ויביאה עלינו כי צדיק ה' אלהינו\u0004 על כל מעשיו אשר עשה\u0003\"\u0004 (דניאל ט, יד), ותמוה: וכי \u0003משום\u0004 ש\u0003\"צדיק ה' \"\u0004לכן \u0003\"וישקד\u0004 (כלומר, הזדרז והקדים) \u0003ה' על הרעה ויביאה עלינו\"?\u0004 ויש להשיב: \u0003אין\u0004 \u0005[כן],\u0006 באמת טובה יש בדבר כי \u0003צדקה עשה הקדוש ברוך הוא עם ישראל שהקדים גלות צדקיהו, ועוד גלות יכניה\u0004 שקדמה לה \u0003קיימת.\u0004","שגלות יכניה גלות של גדולי ישראל היתה, \u0003דכתיב ביה\u0004 \u0005[שנאמר בה]\u0006 \u0003בגלות יכניה: \"\u0004ואת כל אנשי החיל שבעת אלפים ו\u0003החרש והמסגר אלף\"\u0004 (מלכים ב' כד, טז), ודורשים: \u0003\"חרש\"\u0004 — הם אותם חכמים, ש\u0003כיון שפותחין\u0004 לדבר בתורה \u0003הכל נעשו כחרשין,\u0004 שאין להם מה להוסיף ולהשיב, \u0003\"מסגר\"\u0004 — \u0003כיון ש\u0004הם \u0003סוגרין\u0004 (מסכמים) \u0003בהלכה, שוב אין פותחין\u0004 לערער על דבריהם. \u0003וכמה היו? אלף.\u0004 ואם כן טוב שהוחשה גלות המון ישראל בעוד היה מרכז של תורה בבבל.","\u0003עולא אמר:\u0004 צדקה שעשה ה' היתה \u0003שהקדים שתי שנים ל\"ונושנתם\"\u0004 בארץ, שלא תתקיים כל הקללה שבתוכחה.","שנאמר: \"ונושנתם בארץ והשחתם ועשיתם פסל תמונת כל ועשיתם הרע בעיני ה' אלהיך להכעיסו. העידותי בכם היום את השמים ואת הארץ כי אבד תאבדון מהר מעל הארץ אשר אתם עוברים את הירדן שמה לרשתה לא תאריכן ימים עליה כי השמד תשמדון\" (דברים ד, כה–כו). \"ונושנתם\" בגימטריא שמונה מאות חמישים ושתים הם, וישראל גלו בשנת השמונה מאות וחמישים לבואם לארץ. \u0003אמר רב אחא בר יעקב: שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003\"מהרה\" דמרי עלמא\u0004 \u0005[של אדון העולם],\u0006 \u0003תמני מאה וחמשין ותרתין הוו\u0004 \u0005[שמונה מאות וחמישים ושתיים הם],\u0006 שהרי נאמר \"כי אבוד תאבדון מהר\", ומאחר וידוע כי משך הגלות היה שמונה מאות חמישים ושתים שנים, כמנין \"ונושנתם\", הרי ש\"מהרה\" הוא כמנין זה.","שנינו במשנה ש\u0003לפיכך\u0004 נברא אדם יחידי מפני שלום הבריות, ושלא יהיו המינים אומרים הרבה רשויות בשמים וכו'. \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בתוספתא\u0005]:\u0006 \u0003אדם\u0004 הראשון \u0003יחידי נברא, ומפני מה — שלא יהו מינים אומרים: הרבה רשויות בשמים\u0004 וכל אחד ברא אדם אחד. \u0003דבר אחר:\u0004 אדם הראשון נברא יחיד \u0003מפני הצדיקים ומפני הרשעים. שלא יהו הצדיקים אומרים: אנו בני צדיק\u0004 שאבינו הראשון צדיק היה והצדקנות ירושה לנו, ואיננו צריכים להשתדל. \u0003ורשעים אומרים: אנו בני רשע\u0004 ואיננו יכולים לשנות מדרכנו.","\u0003דבר אחר: מפני המשפחות. שלא יהו משפחות מתגרות\u0004 (רבות) \u0003זו בזו\u0004 וכל אחת מתפארת בייחוס אביה הראשון. \u0003ומה עכשיו שנברא\u0004 אדם הראשון \u0003יחיד,\u0004 והכל צאצאיו, \u0003מתגרות\u0004 המשפחות וכל אחת מתפארת בגזעה, אילו \u0003נבראו שנים\u0004 — \u0003על אחת כמה וכמה!\u0004 \u0003דבר אחר: מפני הגזלנין ומפני החמסנין. ומה עכשו שנברא יחידי\u0004 וכולם אחים זה לזה, בכל זאת \u0003גוזלין וחומסין,\u0004 אילו \u0003נבראו שנים\u0004 — \u0003על אחת כמה וכמה\u0004 שהיו מורים היתר לעצמם לגזול בניו של אדם אחר!","ועוד טעם שנינו במשנה לכך שנברא אדם יחידי: שהוא כדי \u0003להגיד גדולתו\u0004 של הקדוש ברוך הוא וכו'. וכן \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בתוספתא\u0005]:\u0006 \u0003להגיד גדולתו של מלך מלכי המלכים הקדוש ברוך הוא, שאדם טובע כמה מטבעות בחותם אחד וכולן דומין זה לזה. אבל הקדוש ברוך הוא טובע כל אדם בחותמו של אדם הראשון,\u0004 שהרי כולם מבניו. \u0003ואין אחד מהן דומה לחבירו, שנאמר: \"תתהפך כחמר חותם ויתיצבו כמו לבוש\"\u0004 (איוב לח, יד), שכולם נבראו כחותם אחד והוא מתהפך לצורות שונות.","\u0003ומפני מה אין פרצופיהן דומין זה לזה?\u0004 — \u0003שלא יראה אדם דירה נאה ואשה נאה ויאמר \"שלי היא\",\u0004 ואין מכחישים אותו שהרי דומה לאחרים, \u0003שנאמר: \"וימנע מרשעים אורם וזרוע רמה תשבר\"\u0004 (איוב לח, טו), משמע שמפני טעם זה לא נבראו שווים.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003היה ר' מאיר אומר: בשלשה דברים אדם משתנה\u0004 ונבדל \u0003מחבירו: בקול, במראה ובדעת.\u0004 השינוי \u0003בקול ובמראה\u0004 — \u0003משום ערוה,\u0004 שלא יחליפו נשיהם זו בזו. \u0003ובדעת\u0004 — \u0003מפני הגזלנין והחמסנין,\u0004 שאם כל האנשים יחשבו בדרך דומה יוכלו הגזלנים לגנוב, שידעו מה בדעת חבריהם והיכן מטמינים חפציהם.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בתוספתא\u0005]:\u0006 \u0003אדם נברא בערב שבת\u0004 בסוף היצירה, \u0003ומפני מה?\u0004 — \u0003שלא יהו מינים אומרים: שותף היה לו\u0004 אדם \u0003להקדוש ברוך הוא במעשה בראשית. דבר אחר: שאם תזוח דעתו עליו\u0004 (יתגאה) האדם, \u0003אומר לו: יתוש קדמך במעשה בראשית,\u0004 שהרי אתה נבראת אחרון. \u0003דבר אחר: כדי שיכנס למצוה\u0004 של שמירת השבת \u0003מיד.\u0004","\u0003דבר אחר: כדי שיכנס לסעודה מיד,\u0004 שכל העולם מוכן לפניו להשתמש בו. \u0003משל למלך בשר ודם שבנה פלטרין\u0004 (ארמון) \u0003ושיכללן, והתקין סעודה, ואחר כך הכניס אורחין,\u0004 כך האדם בא אחרון לעולם מתוקן. מעין זה \u0003נאמר: \"חכמות בנתה ביתה חצבה עמודיה שבעה. טבחה טבחה מסכה יינה אף ערכה שלחנה. שלחה נערתיה תקרא על גפי מרמי קרת\"\u0004 (משלי ט, א–ג), ומבארים:","\u0003\"חכמות בנתה ביתה\"\u0004 — \u0003זו מידתו של הקדוש ברוך הוא, שברא את כל העולם כולו בחכמה. \"חצבה עמודיה שבעה\"\u0004 — \u0003אלו שבעת ימי בראשית\u0004 שבהם הועמד העולם על מכונו. \u0003\"טבחה טבחה מסכה יינה אף ערכה שלחנה\"\u0004 — \u0003אלו ימים ונהרות וכל צורכי עולם\u0004 שנבראו תחילה. \u0003\"שלחה נערתיה תקרא\"\u0004 — \u0003זה אדם וחוה\u0004 שנבראו לבסוף.","נאמר שם \u0003\"על גפי מרמי קרת\". רבה בר בר חנה רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005]:\u0006 \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"על גפי\", וכתיב\u0004 \u0005[ונאמר]\u0006 אחר כך \"וישבה לפתה ביתה \u0003על כסא\u0004 מרומי קרת\" (משלי ט, יד)! אלא יש לומר כי \u0003בתחלה\u0004 — \u0003על גפי,\u0004 שהיה תחילה יחידי בגפו, על מקום גבוה, \u0003ולבסוף\u0004 — \u0003על כסא\u0004 שעורכים לחתן, שנזדווגה לו חוה.","נאמר שם \u0003\"מי פתי יסר הנה חסר לב אמרה לו\"\u0004 (משלי ט, ד). \u0003אמר הקדוש ברוך הוא: מי פתאו לזה\u0004 לאדם? — \u0003אשה אמרה לו\u0004 לחטוא. ורמז לדבר שהמפותה על ידי אשה קרוי \"חסר לב\" — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"נאף אשה חסר לב\"\u0004 (משלי ו, לב).","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003היה ר' מאיר אומר: אדם הראשון מכל העולם כולו הוצבר עפרו, שנאמר: \"\u0004אשר עושיתי בסתר רוקמתי בתחתיות ארץ. \u0003גלמי ראו עיניך\"\u0004 (תהלים קלט, טו–טז), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"כי ה' עיניו משטטות בכל הארץ\"\u0004 (דברי הימים ב' טז, ט), משמע שגולם זה, מכל הארץ, מקום ראיית עיני ה', נוצר. \u0003אמר רב אושעיא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: אדם הראשון\u0004"],["\u0003גופו מבבל, וראשו מארץ ישראל,\u0004 שהיא חשובה מכל הארצות, \u0003ואבריו\u0004 האחרים \u0003משאר ארצות\u0004 שבעולם. \u0003עגבותיו\u0004 (אחוריו) מהיכן? \u0003אמר רב אחא: מאקרא דאגמא,\u0004 מקצה בבל.","\u0003אמר ר' יוחנן בר חנינא: שתים עשרה שעות הוי\u0004 \u0005[הוא]\u0006 \u0003היום,\u0004 וכן היה מבראשית, ו\u0003שעה ראשונה\u0004 של יום — \u0003הוצבר עפרו.\u0004 ב\u0003שניה\u0004 — \u0003נעשה גולם\u0004 (דמות לא מושלמת, גולמית). ב\u0003שלישית\u0004 — \u0003נמתחו אבריו\u0004 לפרטיהם. ב\u0003רביעית\u0004 — \u0003נזרקה בו נשמה.\u0004 ב\u0003חמישית\u0004 — \u0003עמד על רגליו.\u0004 ב\u0003ששית\u0004 — \u0003קרא שמות\u0004 לחיות. ב\u0003שביעית\u0004 — \u0003נזדווגה לו חוה.\u0004 ב\u0003שמינית\u0004 — \u0003עלו למטה שנים\u0004 (אדם וחוה) \u0003וירדו ארבעה\u0004 שילדה מיד את קין והבל. בשעה \u0003תשיעית\u0004 — \u0003נצטווה שלא לאכול מן האילן\u0004 (עץ הדעת). בשעה \u0003עשירית\u0004 — \u0003סרח\u0004 (חטא). בשעה \u0003אחת עשרה\u0004 — \u0003נידון.\u0004 בשעה \u0003שתים עשרה\u0004 — \u0003נטרד והלך לו, שנאמר: \"\u0004ו\u0003אדם ביקר בל ילין\u0004 נמשל כבהמות נדמו\u0003\"\u0004 (תהלים מט, יג), כלומר, אדם הראשון לא לן אף לילה אחד בגן העדן.","\u0003אמר רמי בר חמא\u0004 בפירוש סופו של כתוב זה: \u0003אין חיה רעה שולטת באדם אלא אם כן נדמה לו כבהמה, שנאמר: \"נמשל כבהמות נדמו\".\u0004","\u0003(שעה, בסוף, ארמי\u0004 — \u0003סימן\u0004 לשמועות שנאמרו לקמן בענין האדם הראשון). \u0003אמר רב יהודה אמר רב: בשעה שבקש הקדוש ברוך הוא לבראות את האדם, ברא כת אחת של מלאכי השרת, אמר להם: רצונכם, נעשה אדם בצלמנו? אמרו לפניו: רבונו של עולם, מה מעשיו\u0004 של יצור זה שאתה רוצה לברוא? \u0003אמר להן: כך וכך מעשיו\u0004 כפי טבע האדם.","\u0003אמרו לפניו: רבונו של עולם \"מה אנוש כי תזכרנו ובן אדם כי תפקדנו\"\u0004 (תהילים ח, ה), יצור כזה אין כדאי לברוא. \u0003הושיט אצבעו קטנה ביניהן ושרפם\u0004 באש. \u0003וכן כת שניה\u0004 כך אמרו וכך עשה בהם. \u0003כת שלישית\u0004 ששאל אותם \u0003אמרו לפניו: רבונו של עולם, ראשונים שאמרו לפניך\u0004 שאין דעתם נוחה \u0003מה הועילו?\u0004 הלא \u0003כל העולם כולו שלך הוא, כל מה שאתה רוצה לעשות בעולמך\u0004 — \u0003עשה.\u0004","\u0003כיון שהגיע\u0004 זמן של \u0003אנשי דור המבול ואנשי דור הפלגה שמעשיהן מקולקלין\u0004 ביותר, \u0003אמרו לפניו: רבונו של עולם, לא יפה אמרו ראשונים לפניך\u0004 שלא כדאי היה לברוא את האדם? \u0003אמר להן: \"ועד זקנה אני הוא ועד שיבה אני אסבל\u0004 אני עשיתי ואני אשא ואני אסבול ואמלט\u0003\"\u0004(ישעיה מו, ד), כלומר, כיון שעשיתיו אף אסבול פגמיו וחסרונותיו ואדאג לישועתו.","ועוד \u0003אמר רב יהודה אמר רב:\u0004 גדלו של \u0003אדם הראשון מסוף העולם ועד סופו היה, שנאמר: \"למן היום אשר ברא אלהים אדם על הארץ ולמקצה השמים ועד קצה השמים\"\u0004 (דברים ד, לב), שביום בו נברא היה אורכו מקצה השמים עד קצהם. \u0003כיון שסרח\u0004 (חטא) \u0003הניח הקדוש ברוך הוא ידו עליו ומיעטו, שנאמר: \"אחור וקדם צרתני ותשת עלי כפכה\"\u0004 (תהלים קלט, ה), שתחילה היה ממערב (\"אחור\") עד מזרח (\"קדם\") ולבסוף שם ה' ידו עליו ומיעטו.","\u0003אמר ר' אלעזר: אדם הראשון\u0004 גבוה \u0003מן הארץ עד לרקיע היה, שנאמר: \"למן היום אשר ברא אלהים אדם על הארץ ולמקצה השמים עד קצה השמים\"\u0004 (דברים ד, לב), שהיה מן הארץ עד קצה השמים, \u0003כיון שסרח\u0004 — \u0003הניח הקדוש ברוך הוא ידו עליו ומיעטו, שנאמר: \"אחור וקדם צרתני\u0004 ותשת עלי כפכה \u0003\".\u0004 ושואלים: אם כן, \u0003קשו קראי אהדדי\u0004 \u0005[קשים הכתובים זה על זה],\u0006 שממקום אחד נראה שהיה גודלו מקצה הארץ עד קצה, וממקור שני נראה שהיה מן הארץ עד השמים! ומשיבים: \u0003אידי ואידי חדא מידה היא\u0004 \u0005[זו וזו מידה אחת היא].\u0006","\u0003ו\u0004עוד \u0003אמר רב יהודה אמר רב: אדם הראשון בלשון ארמי ספר\u0004 (דיבר), \u0003שנאמר: \"ולי מה יקרו רעיך אל\"\u0004 (תהלים קלט, יז), ולשון \"יקרו\" במובן של כובד הוא לשון ארמית.","\u0003והיינו\u0004 \u0005[וזהו]\u0006 מה ש\u0003אמר ריש לקיש: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"זה ספר תולדת אדם\u0004 ביום ברוא אלהים אדם\u0003\"\u0004 (בראשית ה, א) — \u0003מלמד שהראהו הקדוש ברוך הוא\u0004 לאדם ביום בריאתו \u0003דור דור ודורשיו, דור דור וחכמיו\u0004 העתידים לצאת ממנו, \u0003כיון שהגיע לדורו של ר' עקיבא שמח\u0004 אדם הראשון \u0003בתורתו ונתעצב במיתתו,\u0004 ואז \u0003אמר: \"ולי מה יקרו רעיך אל\",\u0004 כלומר, כבה כבדו (יקרו) עלי דברים אלה שאנשים גדולים כאלה כך יסבלו.","\u0003ואמר רב יהודה אמר רב: אדם הראשון מין היה, שנאמר: \"ויקרא ה' אלהים אל האדם ויאמר לו איכה\"\u0004 (בראשית ג, ט), כוונתו אינה שאלה של מקום אלא \u0003אן\u0004 \u0005[לאן]\u0006 \u0003נטה לבך?\u0004 שנראה שנטית מדרך האמת. \u0003ר' יצחק אמר: מושך בערלתו היה,\u0004 כדרך שהיו עושים מומרים שהיו מנסים לטשטש את העובדה שהם נימולים. ומנין אתה למד זאת — \u0003כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"והמה כאדם עברו ברית\"\u0004 (הושע ו, ז), והוא מפרשו כאדם הראשון, \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 \u0003\"\u0004וערל זכר אשר לא ימול את בשר ערלתו ונכרתה הנפש ההיא מעמיה \u0003את בריתי הפר\"\u0004 (בראשית יז, יד), ללמדנו שאף אדם הראשון עבר את ברית המילה.","\u0003רב נחמן אמר: כופר בעיקר היה.\u0004 ומנין אתה למד זאת — \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 \u0003\"\u0004והמה כאדם \u0003עברו ברית\"\u0004 \u0003וכתיב התם\u0004 \u0005[שם]\u0006 \u0003\"את בריתי הפר\", \"ואמרו על אשר עזבו את ברית ה' אלהיהם\u0004 וישתחוו לאלהים אחרים ויעבדום\u0003\"\u0004 (ירמיה כב, ט).","בהקשר למקראות אלה המעוררים בעיות של פרשנות וקשיים בויכוח עם המינים, מביאים: \u0003תנן התם\u0004 \u0005[שנינו שם,\u0006 במשנה\u0005],\u0006 \u0003ר' אליעזר אומר: הוי שקוד\u0004 (מהיר) \u0003ללמוד תורה, ודע מה שתשיב לאפיקורוס.\u0004 על כך \u0003אמר ר' יוחנן: לא שנו אלא\u0004 ל\u0003אפיקורוס גוי\u0004 שצריך לדעת לענות לו ולהתווכח עמו, \u0003אבל אפיקורוס ישראל\u0004 לא כדאי להתווכח עמו, כי \u0003כל שכן דפקר טפי\u0004 \u0005[שיתפקר יותר],\u0006 שאפיקורסותו בתורה מתוך זדון ולא מחוסר ידיעה, ולא ירצה לקבל נימוק הוגן.","\u0003אמר ר' יוחנן: כל מקום שפקרו המינים\u0004 ורצו להוכיח מן המקרא שיש שתי רשויות — \u0003תשובתן בצידן.\u0004 אמנם נאמר \u0003\"\u0004ויאמר אלהים \u0003נעשה אדם בצלמנו\"\u0004 (בראשית א, כו) בלשון רבים, \u0003ו\u0004אולם \u0003אומר\u0004 מיד \u0003\"ויברא אלהים את האדם בצלמו\"\u0004 (בראשית א, כז) בלשון יחיד. נאמר בלשון רבים \u0003\"הבה נרדה ונבלה שם שפתם\"\u0004 (בראשית יא, ז), ואולם נאמר \u0003\"וירד ה' לראת את העיר ואת המגדל\"\u0004 (בראשית יא, ה). נאמר בלשון רבים \u0003\"כי שם נגלו אליו האלהים\u0004 בברחו מפני אחיו\u0003\"\u0004 (בראשית לה, ז), ואולם כבר נתפרש \u0003\"לאל הענה אתי ביום צרתי\"\u0004 (בראשית לה ג).","ויש שהאיזון קיים בתוך אותו פסוק, וכגון מה שנאמר \u0003\"כי מי גוי גדול אשר לו אלהים קרבים אליו כה' אלהינו בכל קראנו אליו\"\u0004 (דברים ד, ז), שלשון רבים ולשון יחיד מאזנות זו את זו. וכן: \u0003\"ומי כעמך כישראל גוי אחד בארץ אשר הלכו אלהים לפדות לו לעם\"\u0004 (שמואל ב' ז, כג) לשון רבים ויחיד. וכן \u0003\"עד די כרסון רמיו ועתיק יומין יתב\"\u0004 \u0005[\"עד אשר הכסאות הורמו ועתיק ימים יושב\"]\u0006 (דניאל ז, ט), לשון רבים ויחיד.","ושואלים: \u0003הנך\u0004 \u0005[אותם]\u0006 לשונות של רבים \u0003למה לי?\u0004 ומסבירים, \u0003כ\u0004שיטת \u0003ר' יוחנן,\u0004 ש\u0003אמר ר' יוחנן: אין הקדוש ברוך הוא עושה דבר אלא אם כן נמלך בפמליא של מעלה, שנאמר: \"בגזרת עירין פתגמא ובמאמר קדישין שאלתא\"\u0004 \u0005[\"בגזירת הצירים,\u0006 המלאכים, \u0005הדבר ובמאמר הקדושים השאלה\"]\u0006 (דניאל ד, יד).","ועוד שואלים: \u0003התינח כולהי\u0004 \u0005[נניח\u0006 בהסבר \u0005זה לכל\u0006 הכתובים כולם\u0005],\u0006 אבל \u0003\"עד די כרסון רמיו\"\u0004 שנזכרים שני כסאות, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 ומשיבים: \u0003אחד לו ואחד לדוד,\u0004 הוא המשיח. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 שני כסאות אלה \u0003אחד לו ואחד לדוד,\u0004 אלו \u0003דברי ר' עקיבא, אמר לו ר' יוסי: עקיבא! עד מתי אתה עושה שכינה חול\u0004 להושיב אדם בצידה? \u0003אלא:\u0004 כסא \u0003אחד לדין ואחד לצדקה\u0004 ושניהם לשכינה.","ושואלים: האם \u0003קבלה\u0004 ר' עקיבא את התשובה הזו \u0003מיניה\u0004 \u0005[ממנו,\u0006 מר' יוסי\u0005],\u0006 \u0003או לא קבלה מיניה\u0004 \u0005[ממנו]?\u0006 \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו בברייתא אחרת, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 שני הכסאות המוזכרים בכתוב, \u0003אחד\u0004 מהם \u0003לדין ואחד לצדקה,\u0004 אלו \u0003דברי ר' עקיבא. אמר לו ר' אלעזר בן עזריא: עקיבא! מה לך אצל הגדה\u0004 שאינך בקי בה? \u0003כלך\u0004 (לך) \u0003אצל נגעים ואהלות\u0004 שאלו גופי תורה ואין כמוך בקי בהם! \u0003אלא: אחד לכסא ואחד לשרפרף, כסא\u0004 — \u0003לישב עליו, שרפרף\u0004 — \u0003להדום רגליו.\u0004","ובנושאים אלה \u0003אמר רב נחמן: האי מאן דידע לאהדורי\u0004 \u0005[מי שיודע לענות]\u0006 \u0003למינים כרב אידית\u0004 — \u0003ליהדר\u0004 \u0005[שיענה],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 הוא \u0003לא\u0004 יודע כמו כן — ש\u0003לא ליהדר\u0004 \u0005[יענה].\u0006 ודוגמה לדברי רב אידית — \u0003אמר ההוא מינא\u0004 \u0005[מין אחד]\u0006 \u0003לרב אידית: כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"ואל משה אמר עלה אל ה' \"\u0004(שמות כד, א), \u0003\"עלה אלי\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \"ה' \" שבפסוק זה \u0003זהו\u0004 המלאך \u0003מטטרון ששמו כשם רבו\u0004 (ה', שדי), \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004הנה אנכי שולח מלאך לפניך... השמר מפניו ושמע בקולו אל תמר בו כי לא ישא לפשעכם \u0003כי שמי בקרבו\"\u0004 (שמות כג, כ–כא).","אמר לו המין: \u0003אי הכי ניפלחו ליה\u0004 \u0005[אם כך שיעבדו אותו]\u0006 כמו את ה'! אמר לו רב אידית: זה ש\u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"אל תמר בו\",\u0004 כוונתו: \u0003אל תמירני\u0004 (תחליפני) \u0003בו.\u0004 אמר לו המין: \u0003אם כן,\u0004 מה שנאמר \u0003\"לא ישא לפשעכם\" למה לי?\u0004 והלא אין בכוחו לעשות כן! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אידית: \u0003הימנותא בידן\u0004 \u0005[אמונה\u0006 היא \u0005בידינו],\u0006 ש\u0003אפילו בפרוונקא נמי\u0004 \u0005[כסייר\u0006 ההולך לפנינו \u0005גם כן]\u0006 \u0003לא קבילניה\u0004 \u0005[קיבלנוהו],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויאמר אליו אם אין פניך הלכים\u0004 אל תעלנו מזה","\u0003\"\u0004(שמות לג, טו), שאם ה' עצמו לא ילך עם ישראל אינם רוצים בשום שליח ומלאך. ועוד מסופר, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ההוא מינא\u0004 \u0005[מין אחד]\u0006 \u0003לר' ישמעאל בר' יוסי: כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"וה' המטיר על סדם ועל עמרה גפרית ואש מאת ה'\u0004 מן השמים\u0003\"\u0004 (בראשית יט, כד), והרי \u0003\"מאתו\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005],\u0006 ונשמע איפוא כשתי רשויות! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ההוא\u0004 \u0005[אותו]\u0006 \u0003כובס\u0004 לר' ישמעאל: \u0003שבקיה, אנא מהדרנא ליה\u0004 \u0005[הניחנו, אני אשיב לו],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויאמר למך לנשיו עדה וצלה שמען קולי נשי למך\u0004 האזנה אמרתי \u0003\",\u0004 ואף שם תוכל לומר מדוע \"נשי למך\"? \u0003\"נשיי\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006 \u0003אלא: משתעי קרא הכי\u0004 \u0005[מדבר הכתוב כך],\u0006 שחוזר על הנושא פעמיים באותו פסוק, \u0003הכא נמי משתעי קרא הכי\u0004 \u0005[כאן,\u0006 בענין סדום, \u0005גם כן מדבר הכתוב כך].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' ישמעאל לכובס: \u0003מנא\u0004 \u0005[מנין]\u0006 \u0003לך הא\u0004 \u0005[\u0006דבר \u0005זה]\u0006 של חכמה? אמר לו: \u0003מפירקיה\u0004 \u0005[מדרשתו\u0006 הפומבית\u0005]\u0006 של \u0003ר' מאיר שמיע לי\u0004 \u0005[שמעתי].\u0006","ש\u0003אמר ר' יוחנן: כי הוה דריש\u0004 \u0005[כאשר היה דורש]\u0006 \u0003ר' מאיר בפירקיה\u0004 \u0005[בדרשה\u0006 הפומבית\u0005],\u0006 \u0003הוה דריש תילתא שמעתא, תילתא אגדתא, תילתא מתלי\u0004 \u0005[היה דורש שליש הלכה, שליש אגדה,\u0006 ו\u0005שליש משלים].\u0006 \u0003ו\u0004עוד \u0003אמר\u0004 בענין זה \u0003ר' יוחנן: שלש מאות משלות שועלים היו לו לר' מאיר, ואנו אין לנו,\u0004 איננו יודעים מהם, \u0003אלא שלש:\u0004"],["והם המשלים שהיו צמודים לפסוקים \u0003\"אבות יאכלו בסר ושני\u0004 ה\u0003בנים תקהינה\"\u0004 (יחזקאל יח, ב), \u0003\"מאזני צדק אבני צדק\"\u0004 (ויקרא יט, לו), \u0003\"צדיק מצרה נחלץ ויבא רשע תחתיו\"\u0004 (משלי יא, ח).","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ה\u0003קיסר\u0004 הרומי \u0003לרבן גמליאל: אלהיכם גנב הוא, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויפל ה' אלהים תרדמה על האדם ויישן\u0004 ויקח אחת מצלעותיו\u0003\"\u0004 (בראשית ב, כא). \u0003אמרה ליה ברתיה\u0004 \u0005[לו בתו]\u0006 של הקיסר לרבן גמליאל: \u0003שבקיה, דאנא מהדרנא ליה\u0004 \u0005[הנח לו, שאני אשיב לו].\u0006 \u0003אמרה ליה\u0004 \u0005[לו]\u0006 לאביה: \u0003תנו לי דוכוס\u0004 (שר) \u0003אחד. אמר לה: למה ליך\u0004 \u0005[לך]?\u0006 אמרה לו: \u0003ליסטין\u0004 (שודדים, גנבים) \u0003באו עלינו הלילה, ונטלו ממנו קיתון\u0004 (כלי שתיה) \u0003של כסף והניחו לנו קיתון של זהב. אמר לה:\u0004 אם כן, \u0003ולוואי שיבא\u0004 שודד כזה \u0003עלינו בכל יום.\u0004 אמרה לו: \u0003ולא יפה היה לו לאדם הראשון שנטלו ממנו צלע אחת ונתנו לו שפחה לשמשו,\u0004 כלומר, את חוה, ואין כאן גניבה אלא מתנה.","\u0003אמר לה: הכי קאמינא\u0004 \u0005[כך אני אומר],\u0006 לא היתה שאלתי על לקיחה והשבה, \u0003אלא לשקליה בהדיא\u0004 \u0005[שיקח ממנו במישרין]\u0006 ולא בסתר בזמן תרדמתו, כגניבה. \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003אייתו\u0004 \u0005[הביאו]\u0006 \u0003לי אומצא דבישרא\u0004 \u0005[חתיכת בשר חיה].\u0006 \u0003אייתו\u0004 \u0005[הביאו]\u0006 \u0003לה. אותבה תותי בחשא, אפיקתה\u0004 \u0005[הכניסה אותה תחת הרמץ, והוציאה אותה\u0006 לאחר שנצלתה\u0005],\u0006 \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003אכול מהאי\u0004 \u0005[מזו].\u0006 \u0003אמר לה: מאיסא\u0004 \u0005[מאוסה\u0006 היא\u0005]\u0006 \u0003לי,\u0004 שאף שידע שכך עושים לכל בשר, הלא אינו רואה כיצד היה מאוס לפני הצליה. \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003ואדם הראשון נמי\u0004 \u0005[גם כן],\u0006 \u0003אי הות שקילה בהדיא הוה מאיסא ליה\u0004 \u0005[אילו היה לוקח אותה\u0006 ומביא אותה \u0005במישרין היתה מאוסה עליו,\u0006 בעיניו\u0005],\u0006 ולכן עשה זאת מתוך שינה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ה\u0003קיסר לרבן גמליאל: ידענא אלהייכו האי קא עביד והיכן יתיב\u0004 \u0005[יודע אני\u0006 את \u0005אלוהיכם מה הוא עושה והיכן\u0006 הוא \u0005יושב],\u0006 בינתיים \u0003איתנגד ואיתנח\u0004 \u0005[נאנק ונאנח]\u0006 הקיסר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבן גמליאל: \u0003מאי האי\u0004 \u0005[מה זה],\u0006 על מה אתה נאנח? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בן אחד יש לי בכרכי הים ויש לי גיעגועים עליו.\u0004 אמר לו רבן גמליאל: \u0003בעינא דמחוית ליה ניהלי\u0004 \u0005[רוצה אני שתראה אותו לי].\u0006 \u0003אמר: מי ידענא היכא ניהו\u0004 \u0005[וכי יודע אני היכן הוא\u0006 נמצא\u0005]?!\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבן גמליאל: \u0003דאיכא בארעא לא ידעת, דאיכא בשמיא ידעת\u0004 \u0005[\u0006מה \u0005שיש בארץ אינך יודע,\u0006 ומה \u0005שיש בשמים אתה יודע]?\u0006","ועוד מסופר, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003קיסר לרבן גמליאל: כתיב\u0004 \u0005[נאמר]\u0006 בשבחי ה' \u0003\"מונה מספר לכוכבים\u0004 לכולם שמות יקרא\u0003\"\u0004 (תהלים קמז, ד), \u0003מאי רבותיה\u0004 \u0005[מה גדולתו]?\u0006 \u0003אנא מצינא למימנא כוכבי\u0004 \u0005[אני יכול למנות\u0006 את \u0005הכוכבים]!\u0006 \u0003אייתי חבושי, שדינהו בארבילא, וקא מהדר להו\u0004 \u0005[הביא\u0006 רבן גמליאל \u0005חבושים, שם אותם בנפה, ובחש בהם],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 לקיסר \u0003מנינהו\u0004 \u0005[מנה אותם]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אוקמינהו\u0004 \u0005[העמד אותם]\u0006 ואוכל למנותם, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 ה\u0003רקיע נמי הכי הדרא\u0004 \u0005[גם כן כך\u0006 הוא \u0005מסתובב],\u0006 ולכן אין אתה יכול למנות את הכוכבים שבו.","\u0003איכא דאמרי הכי אמר ליה\u0004 \u0005[יש אומרים\u0006 ש\u0005כך אמר לו\u0006 הקיסר\u0005]:\u0006 \u0003מני לי כוכבי\u0004 \u0005[מנויים אצלי הכוכבים]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 \u0003לי ככיך ושיניך\u0004 \u0005[שיניך וניבך]\u0006 \u0003כמה הוה\u0004 \u0005[הם]!\u0006 \u0003שדא ידיה לפומיה וקא מני להו\u0004 \u0005[הכניס ידו לפיו והיה מונה אותם].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003דאיכא בפומיך לא ידעת, דאיכא ברקיעא ידעת\u0004 \u0005[\u0006מה \u0005שיש בפיך אינך יודע,\u0006 מה \u0005שיש ברקיע יודע אתה]?!\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003קיסר לרבן גמליאל: מי שברא הרים לא ברא רוח\u0004 אלא שני אלים הם, \u0003שנאמר: \"כי הנה יוצר הרים וברא רוח\"\u0004 (עמוס ד, יג), שהיוצר הוא לחוד והבורא הוא לחוד. אמד לו רבן גמליאל: \u0003אלא מעתה גבי\u0004 \u0005[אצל]\u0006 \u0003אדם, דכתיב\u0004 \u0005[שנאמר\u0006 בו\u0005]\u0006 גם \u0003\"ויברא\"\u0004 וגם \u0003\"וייצר\", הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר כי \u0003מי שברא זה לא ברא זה?\u0004","הלא \u0003טפח על טפח\u0004 של פרצוף הפנים \u0003יש בו באדם, ושני נקבים יש בו,\u0004 עין ואוזן, האם תאמר ש\u0003מי שברא זה לא ברא זה? שנאמר: \"הנטע אזן הלא ישמע אם יצר עין הלא יביט\"\u0004 (תהלים צד, ט)? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן]\u0006 כך הוא באמת. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ובשעת מיתה כולן נתפייסו,\u0004 שכל האלים הללו מסכימים כולם כאחד שימות ואין אחד מעכב על חבירו?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ההוא אמגושא\u0004 \u0005[כומר פרסי]\u0006 \u0003לאמימר: מפלגך לעילאי\u0004 \u0005[מחצייך ולמעלה]\u0006 של \u0003הורמיז,\u0004 אל הטוב, שברא חלקים המעולים והחשובים, \u0003מפלגך לתתאי\u0004 \u0005[מחצייך ולמטה]\u0006 של \u0003אהורמיז,\u0004 אל הרע. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אם כן היכי שביק ליה\u0004 \u0005[איך מניח לו]\u0006 \u0003אהורמיז להורמיז לעבורי מיא בארעיה\u0004 \u0005[להעביר מים\u0006 שהוא שותה \u0005בארצו]?\u0006 שהרי אדם שותה בפיו שהוא בחלקו העליון, ומוציא מי רגלים מלמטה!","ועוד בענייני ויכוחים \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003קיסר לר' תנחום: תא ליהוו כולן לעמא חד\u0004 \u0005[בוא נהיה כולנו לעם אחד].\u0006 \u0003אמר\u0004 ר' תנחום: \u0003לחיי\u0004 \u0005[טוב],\u0006 \u0003אנן דמהלינן לא מצינן מיהוי כוותייכו, אתון מהליתו והוו כוותן\u0004 \u0005[אנחנו שאנו נימולים אין אנו יכולים להיות\u0006 ערלים \u0005כמותכם, אתם מולו והיו כמונו]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 הקיסר לר' תנחום: \u0003מימר\u0004 \u0005[\u0006לענין \u0005אמירה]\u0006 — \u0003שפיר קאמרת\u0004 \u0005[יפה אמרת],\u0006 \u0003מיהו\u0004 \u0005[ואולם]\u0006 \u0003כל\u0004 מי \u0003דזכי למלכא\u0004 \u0005[שמנצח את המלך\u0006 בויכוח\u0005]\u0006 \u0003לשדיוה\u0004 \u0005[זורקים אותו]\u0006 \u0003לביבר,\u0004 שהוא מקום חיות רעות. \u0003שדיוה\u0004 \u0005[זרקוהו]\u0006 \u0003לביבר ולא אכלוה\u0004 \u0005[אכלו אותו\u0006 החיות\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ההוא מינא\u0004 \u0005[מין אחד]:\u0006 \u0003האי\u0004 \u0005[זה]\u0006 ש\u0003לא אכלוה\u0004 \u0005[אכלו אותו]\u0006 — \u0003משום\u0004 ש\u0003לא כפין הוא\u0004 \u0005[שאינם רעבים],\u0006 \u0003שדיוה ליה לדידיה ואכלוה\u0004 \u0005[זרקו אותו עצמו\u0006 את אותו מין לשם \u0005ואכלוהו\u0006 החיות\u0005].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003קיסר לרבן גמליאל: אמריתו, כל בי עשרה שכינתא שריא\u0004 \u0005[אומרים אתם\u0006 כי \u0005בכל מקום עשרה\u0006 מישראל \u0005השכינה שורה],\u0006 ואם כן \u0003כמה שכינתא איכא\u0004 \u0005[שכינות יש]?\u0006 \u0003קרייה לשמעיה מחא ביה באפתקא\u0004 \u0005[קראו\u0006 רבן גמליאל \u0005לשמשו\u0006 של הקיסר ו\u0005הכהו על צווארו],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אמאי על שמשא בביתיה\u0004 \u0005[מדוע אתה מניח שתיכנס השמש לביתו של]\u0006 ה\u0003קיסר?\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 הקיסר: \u0003שמשא אכולי עלמא ניחא\u0004 \u0005[השמש על כל העולם מצויה]\u0006 ובין השאר מאירה גם אצלי. אמר לו: \u0003ומה שמשא\u0004 \u0005[השמש],\u0006 \u0003דחד\u0004 \u0005[ש\u0006היא \u0005אחד]\u0006 \u0003מן אלף אלפי רבוא\u0004 (עשרת אלפים) \u0003שמשי דקמי קודשא בריך הוא\u0004 \u0005[שמשים שלפני הקדוש ברוך הוא]\u0006 \u0003ניחא לכולי עלמא\u0004 \u0005[שורה בכל העולם],\u0006 \u0003שכינתא דקודשא בריך הוא\u0004 \u0005[שכינתו של הקדוש ברוך הוא]\u0006 \u0003על אחת כמה וכמה\u0004 שהיא שורה בכל מקום בעולם.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ההוא מינא\u0004 \u0005[מין אחד]\u0006 \u0003לר' אבהו: אלהיכם גחכן\u0004 (עושה מעשה צחוק) \u0003הוא, דקאמר ליה\u0004 \u0005[שאמר לו]\u0006 \u0003ליחזקאל\u0004 הנביא: \u0003\"שכב על צדך השמאלי\"\u0004 (יחזקאל ד, ד), \u0003וכתיב\u0004 \u0005[ו\u0006כן \u0005נאמר]:\u0006 \u0003\"ושכבת על צדך הימני\"\u0004 (יחזקאל ד ו). בינתיים \u0003אתא ההוא תלמידא\u0004 \u0005[בא תלמיד אחד]\u0006 לפני ר' אבהו ו\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי טעמא דשביעתא\u0004 \u0005[מה טעם השביעית,\u0006 שנת השמיטה\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003השתא אמינא לכו מילתא דשויא לתרוייהו\u0004 \u0005[עכשיו אומר לכם דבר שיהיה שוה\u0006 וראוי \u0005לשניכם].\u0006","\u0003אמר הקדוש ברוך הוא לישראל: זרעו שש\u0004 שנים \u0003והשמיטו\u0004 שנת ה\u0003שבע, כדי שתדעו שהארץ שלי היא,\u0004 ואין אתם בה אלא כשכירים. \u0003והן לא עשו כן אלא חטאו ו\u0004משום כך \u0003גלו. מנהגו של עולם, מלך בשר ודם שסרחה\u0004 (חטאה) \u0003עליו מדינה, אם אכזרי הוא\u0004 — \u0003הורג את כולן, אם רחמן הוא\u0004 — \u0003הורג\u0004 רק \u0003חצים, אם רחמן מלא רחמים הוא\u0004 — \u0003מייסר הגדולים שבהן ביסורין. אף כך, הקדוש ברוך הוא מייסר את יחזקאל כדי למרק עונותיהם של ישראל,\u0004 ואמר לו לשכב ולהתייסר ימים כמספר השנים בהן לא שמרו בני ישראל את השמיטה (\"ואתה שכב על צדך השמאלי ושמת את עוון בית ישראל עליו מספר הימים אשר תשכב עליו תשא את עוונם\").","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ההוא מינא\u0004 \u0005[אותו מין]\u0006 \u0003לר' אבהו, אלהיכם\u0004 הלא \u0003כהן הוא, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ויקחו לי תרומה\"\u0004 (שמות כה, ב), ותרומה ניתנת לכהנים, \u0003כי קבריה\u0004 \u0005[כאשר קברו]\u0006 את \u0003משה במאי טביל\u0004 \u0005[במה טבל]?\u0006 שהרי כהן שנטמא צריך לטבול כדי שיוכל לאכול בתרומה. \u0003וכי תימא במיא\u0004 \u0005[ואם תאמר\u0006 ש\u0005במים\u0006 טבל\u0005],\u0006 \u0003והכתיב\u0004 \u0005[והלא נאמר]:\u0006 \u0003\"מי מדד בשעלו מים\"\u0004 (ישעיה מ, יב), שכל מי העולם הם כשעל של הקדוש ברוך הוא, ואינו יכול איפוא לטבול בהם!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אבהו: \u0003בנורא טביל\u0004 \u0005[באש טבל],\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"כי הנה ה' באש יבוא\"\u0004 (ישעיה סו, טו). אמר לו: \u0003ומי סלקא טבילותא בנורא\u0004 \u0005[והאם עולה,\u0006 מטהרת, \u0005טבילה באש]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אבהו: \u0003אדרבה, עיקר טבילותא בנורא\u0004 \u0005[הטבילה באש]\u0006 \u0003הוא,\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004כל דבר אשר יבא באש תעבירו באש וטהר... \u0003וכל אשר לא יבא באש תעבירו במים\"\u0004 (במדבר לא, כג).","ועוד מסופר, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ההוא מינא\u0004 \u0005[מין אחד]\u0006 \u0003לר' אבינא: כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"ומי כעמך כישראל גוי אחד בארץ\"\u0004 (שמואל ב' ז, כג), \u0003מאי רבותייהו\u0004 \u0005[מה גדולתכם]?\u0006 \u0003אתון נמי ערביתו בהדן\u0004 \u0005[אתם גם כן מעורבים יחד איתנו],\u0006 שגם עליכם \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"כל הגוים כאין נגדו\u0004 מאפס ותוהו נחשבו לו\u0003\"\u0004 (ישעיה מ, יז)! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מדידכו אסהידו עלן\u0004 \u0005[משלכם\u0006 נביא גוי, בלעם, כבר \u0005העיד עלינו],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006"],["\u0003\"\u0004הן עם לבדד ישכון \u0003ובגוים לא יתחשב\"\u0004 (במדבר כג, ט), לומר שבכל מקום שנזכרים \"גויים\" — אין עם ישראל בכללם. באופן קצת דומה \u0003ר' אלעזר רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005]:\u0006 \u0003כתיב\u0004 \u0005[נאמר\u0006 במקום אחד\u0005]\u0006 \u0003\"טוב ה' לכל\u0004 ורחמיו על כל מעשיו\u0003\"\u0004 (תהלים קמה, ט), \u0003וכתיב\u0004 \u0005[ונאמר\u0006 במקום אחר\u0005]\u0006 \u0003\"טוב ה' לקוו\u0004 לנפש תדרשנו\u0003\"\u0004 (איכה ג, כה). וכך יש ליישב סתירה זו: \u0003משל לאדם שיש לו פרדס, כשהוא משקה\u0004 — \u0003משקה את כולו,\u0004 שהמים זורמים בתעלות לכל חלקי הפרדס בבת אחת, ואינו יכול להבחין, הוא שנאמר \"טוב ה' לכל\", \u0003כשהוא עודר\u0004 ודואג לכל צמח לעצמו — \u0003אינו עודר אלא\u0004 ל\u0003טובים שבהם\u0004 ולא לכולם.","","שנינו במשנה כי \u0003לפיכך,\u0004 כיון שכל העולם נברא מאדם אחד, \u0003כל אחד ואחד\u0004 חייב לומר לעצמו שבשבילו נברא העולם וכל מעשה שלו משפיע על העולם, אם לטוב או לרע. ואם יאמר אדם מה לי ולצרה זו, להעיד נגד החוטאים? יש לומר כי אין הדבר כן, וודאי חייב הוא להעיד, שכן ראוי לאבד את הרשעים, שנאמר: \"ובאבוד רשעים רינה\" (משלי יא, י). נאמר לאחר מות אחאב \u0003\"ויעבר הרנה במחנה\"\u0004 (מלכים א' כב, לו), \u0003אמר ר' אחא בר חנינא:\u0004 הוא שנאמר \u0003\"\u0004ו\u0003באבד רשעים רנה\"\u0004 (משלי יא, י), כלומר, \u0003באבוד אחאב בן עמרי\u0004 — \u0003רנה.\u0004","ושואלים: \u0003ומי חדי קודשא בריך הוא\u0004 \u0005[והאם שמח הקדוש ברוך הוא]\u0006 \u0003במפלתן של רשעים? הכתיב\u0004 \u0005[הרי נאמר]:\u0006 \u0003\"בצאת לפני החלוץ ואמרים הודו לה' כי לעולם חסדו\"\u0004 (דברי הימים ב' כ, כא). \u0003ואמר ר' יונתן: מפני מה לא נאמר בהודאה זו \"כי טוב\"\u0004 כדרך שהפסוק נאמר כמה פעמים \"הודו לה' כי טוב\"? — \u0003לפי שאין הקדוש ברוך הוא שמח במפלתן של רשעים,\u0004 ובכל מקום שיש מיתה לבני אדם, אין הדבר טוב לגמרי בעיניו. וכפי ש\u0003אמר ר' שמואל בר נחמן אמר ר' יונתן: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 לפני קריעת ים סוף \u0003\"ולא קרב זה אל זה כל הלילה\"\u0004 (שמות יד, כ)? — \u0003באותה שעה\u0004 שטבעו המצרים \u0003בקשו מלאכי השרת לומר שירה לפני הקדוש ברוך הוא, אמר להן הקדוש ברוך הוא: מעשי ידי,\u0004 המצרים, שהרי אף הם מעשי ידי ה', \u0003טובעין בים, ואתם אומרים שירה לפני?!\u0004 משמע שה' מצטער גם במיתתם של רשעים, וכיצד אפשר לומר שיש רינה באיבוד רשעים?","","\u0003אמר ר' יוסי בר חנינא:\u0004 אמנם \u0003הוא\u0004 עצמו \u0003אינו שש\u0004 במפלתם, \u0003אבל אחרים משיש\u0004 (משמח) בכך. ומעירים: \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 הדבר ממה \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \"והיה כאשר שש ה' עליכם להיטיב אתכם ולהרבות אתכם כן \u0003ישיש\u0004 ה' עליכם להאביד אתכם\" (דברים כח, סג), \u0003ולא כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"ישוש\",\u0004 כלומר, \"ישיש\" במובן של פועל יוצא, שלאחרים הוא גורם ששון, אבל הוא עצמו אינו שש. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכך הוא. על הנאמר שם בענין מותו של אחאב \"וישטוף את הרכב על ברכת שומרון וילוקו הכלבים את דמו \u0003והזנות רחצו\u0004 כדבר ה' אשר דבר\" (מלכים א' כב, לח), \u0003אמר ר' אליעזר:\u0004 \"והזונות\" יש לקרוא כמו \"חזונות\", וכוונתו: \u0003למרק\u0004 (להשלים) \u0003שתי חזיונות, אחת של מיכיהו ואחת של אליהו. במיכיהו כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"אם שוב תשוב בשלום לא דבר ה' בי\"\u0004 (מלכים א' כב, כח). \u0003ו\u0004אילו \u0003באליהו כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"במקום אשר לקקו הכלבים את דם נבות\u0004 ילוקו הכלבים את דמך גם אתה\u0003\"\u0004(מלכים א' כא, יט).","","\u0003רבא אמר:\u0004 שם מדובר בצורת \u0003זונות ממש.\u0004 כיצד? — \u0003אחאב איש מצונן היה\u0004 ולא היה מתאווה לנשים, \u0003ועשתה לו איזבל שתי צורי\u0004 (צורות) \u0003זונות במרכבתו, כדי שיראה אותן\u0004 במשך נסיעתו \u0003ויתחמם\u0004 (יתאווה).","על הנאמר שם \u0003\"ואיש משך בקשת לתמו ויכה\u0004 את מלך ישראל\u0003\"\u0004 (מלכים א' כב, לד), \u0003ר' אלעזר אמר\u0004 כי \"לתומו\" פירושו — \u0003לפי תומו,\u0004 בלא כוונה. \u0003רבא אמר:\u0004 הכוונה היא \u0003לתמם\u0004 (להשלים) \u0003שתי חזיונות, אחת של מיכיהו ואחת של אליהו.\u0004","(כיון שדובר באחאב מביאים עוד דברים בעניינו, ו\u0003סימנ\u0004ם: \u0003קרא וזכה דבאדום. כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ויקרא אחאב אל עבדיהו אשר על הבית ועבדיהו היה ירא\u0004 את \u0003ה' מאד\"\u0004 (מלכים א' יח, ג). ושואלים: \u0003מאי קאמר קרא\u0004 \u0005[מה אומר הכתוב]?\u0006 מה הקשר בין הערה זו על יראת ה' של עובדיה עם קריאת אחאב? \u0003אמר ר' יצחק:\u0004 כך \u0003אמר ליה\u0004 \u0005[לו]\u0006 אחאב: \u0003ביעקב כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"\u0004ויאמר אליו לבן אם נא מצאתי חן בעיניך \u0003נחשתי ויברכני ה' בגללך\"\u0004 (בראשית ל, כז). \u0003ביוסף כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"ויברך ה' את בית המצרי בגלל יוסף\"\u0004 (בראשית לט, ה), \u0003ביתא דההוא גברא\u0004 \u0005[ביתו של אותו אדם],\u0006 בית אחאב, \u0003לא הוה מיבריך\u0004 \u0005[היה מבורך],\u0006 \u0003שמא לא ירא אלהים אתה?\u0004 שהרי עבד ירא ה' גורם שיתברך בית האדון! על כן \u0003יצתה בת קול ואמרה: \"ועבדיהו היה ירא את ה' מאד\", אבל ביתו של אחאב אינו מזומן\u0004 (מוכן) \u0003לברכה\u0004 כביתם של אותם אדונים. \u0003אמר ר' אבא: גדול\u0004 השבח \u0003שנאמר בעובדיהו יותר ממה שנאמר באברהם,\u0004 ש\u0003אילו באברהם לא כתיב\u0004 \u0005[נאמר]\u0006 בו לשון \u0003\"מאד\"\u0004 רק שירא אלהים הוא (\"כי עתה ידעתי כי ירא אלהים אתה\". בראשית כב, יב), \u0003ובעובדיהו כתיב\u0004 \u0005[נאמר]\u0006 הלשון \u0003\"מאד\".\u0004 \u0003אמר ר' יצחק: מפני מה זכה עובדיהו לנביאות,\u0004 שמסורת היתה שהוא עובדיה הנביא שבתרי עשר? — \u0003מפני שהחביא מאה נביאים במערה, שנאמר: \"ויהי בהכרית איזבל את נביאי ה' ויקח עבדיהו מאה נביאים ויחביאם חמשים איש במערה\"\u0004 (מלכים א', יח, ד). ושואלים: \u0003מאי שנא\u0004 \u0005[מה שונה,\u0006 מדוע דווקא\u0005]\u0006 \u0003חמשים איש\u0004 בכל מערה ולא החביאם יחד? \u0003אמר ר' אלעזר: מיעקב למד\u0004 שאין עושים כן, \u0003שנאמר: \"\u0004ויאמר אם יבוא עשו אל המחנה האחת והכהו \u0003והיה המחנה הנשאר לפליטה\"\u0004 (בראשית לב, ח), ומכאן למד לחלק אותם ובכך למעט את הסיכון. \u0003ר' אבהו אמר: לפי שאין מערה\u0004 גדולה ש\u0003מחזקת יותר מחמשים\u0004 איש. ועוד לענין עובדיה, נאמר: \u0003\"חזון עבדיה כה אמר ה' אלהים לאדום\"\u0004 (עובדיה א, א). ושואלים: \u0003מאי שנא\u0004 \u0005[במה שונה,\u0006 מדוע דווקא\u0005]\u0006 נתייחדה נבואת \u0003עובדיה לאדום?\u0004 \u0003אמר ר' יצחק: אמר הקדוש ברוך הוא: יבא עובדיהו הדר בין שני רשעים,\u0004 אחאב ואיזבל, \u0003ולא למד ממעשיהם,\u0004 שהיה ירא ה' מאד, \u0003וינבא על עשו הרשע\u0004 (אדום) \u0003שדר בין שני צדיקים,\u0004 יצחק ורבקה, \u0003ולא למד ממעשיהם.\u0004 הסבר אחר, \u0003אמר אפרים מקשאה תלמידו של ר' מאיר משום\u0004 (בשם) \u0003ר' מאיר: עובדיה גר אדומי היה,\u0004 ולכן ניבא על אדום, \u0003והיינו דאמרי אינשי\u0004 \u0005[והוא שאומרים אנשים]\u0006 בפתגם עממי: \u0003\"מניה וביה אבא ניזיל ביה נרגא\"\u0004 \u0005[\"ממנו ובו\u0006 של \u0005היער יבוא בו הגרזן\"],\u0006 שמתוך היער לוקחים את העץ המשמש לקת הגרזן הגודע אותו.","","","","","","על הנאמר בדוד: \u0003\"ויך את מואב וימדדם בחבל השכב אותם ארצה\u0004 וימדד שני חבלים להמית\u0003\"\u0004 (שמואל ב' ח, ב), \u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' שמעון בן יוחי: היינו דאמרי אינשי\u0004 \u0005[זהו שאומרים אנשים]\u0006 בפתגם עממי: \u0003\"מיניה וביה אבא ליזיל ביה נרגא\"\u0004 \u0005[\"ממנו ובו\u0006 של \u0005היער יבוא בו הגרזן\"],\u0006 שהרי דוד המלך שציוה לעשות כן מצאצאי רות המואביה היה. \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל \u0003אמר\u0004 פתגם דומה לזה: \u0003ירך מתוכה מסרחת,\u0004 שעיקר הסרחון מתחיל ממנה עצמה, אף כאן העונש מתחיל מתוך בני אותו עם.","אגב הדיון בחטאי האומות מביאים את מה שנאמר במלך מואב: \u0003\"ויקח את בנו הבכור אשר ימלך תחתיו ויעלהו עלה על החמה\u0004 ויהי קצף גדול על ישראל\u0003\"\u0004 (מלכים ב' ג, כז). \u0003רב ושמואל\u0004 נחלקו בכך, \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: לשם שמים\u0004 הקריבו, \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: לשם עבודה זרה\u0004 שלו הקריבו.","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי \u0003לשם שמים\u0004 הקריבו, \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 \u0003\"ויהי קצף גדול על ישראל\",\u0004 שהגוי מכבד כפי הבנתו שלו את אלוהי ישראל, בעוד ישראל סרים מעליו. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי \u0003לשם עבודה זרה\u0004 הקריבו, \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003\"ויהי קצף\"?\u0004 ומשיבים: יש להבין זאת \u0003כד\u0004ברי \u0003ר' יהושע בן לוי.\u0004 ש\u0003ר' יהושע בן לוי רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005]:\u0006 \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"וכמשפטי הגוים אשר סביבותיכם לא עשיתם\"\u0004 (יחזקאל ה, ז), \u0003וכתיב\u0004 \u0005[ו\u0006מאידך \u0005נאמר]:\u0006 \u0003\"וכמשפטי הגוים אשר סביבותיכם עשיתם\"\u0004 (יחזקאל יא, יב), ויש להסביר: \u0003כמתוקנין שבהם לא עשיתם,\u0004 ואולם \u0003כמקולקלין שבהם עשיתם.\u0004 ואף כאן, ישראל למדו מן העמים והקריבו קרבנות אדם כמותם, ועל ידי קרבן זה הזכירו את חטאיהם של ישראל. על מה שנאמר שם \u0003\"ויסעו מעליו וישבו לארץ\"\u0004 (מלכים ב' ג, כז), \u0003אמר ר' חנינא בר פפא: באותה שעה ירדו שונאיהן של ישראל\u0004 (כלומר, ישראל) \u0003למדריגה התחתונה,\u0004 שירדו עד עפר הארץ.","","","אגב הזכרת ההדגשה של \"מאד\" האמורה בעובדיה מביאים פירוש לכתוב שנאמר באבישג: \u0003\"והנערה יפה עד מאד\"\u0004 (מלכים א' א, ד), \u0003אמר ר' חנינא בר פפא: עדיין לא הגיעה לחצי יופי של שרה,\u0004 שנאמר בשרה \"כי יפה היא מאד\" (בראשית יב, יד). ומהיכן אתה למד זאת? — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"עד מאד\",\u0004 שמשמעו — \u0003ולא מאד בכלל,\u0004",""],["\u0003היו בודקין אותן\u0004 את העדים \u0003בשבע חקירות,\u0004 והן: \u0003באיזו שבוע,\u0004 כלומר, באיזה מחזור של שנות שמיטה היה הדבר (שכן בתוך חמישים שנות יובל יש שבעה מחזורים כאלה), \u0003באיזו שנה\u0004 ממחזור שנות השמיטה (שהוא בן שבע שנים), \u0003באיזו חודש, בכמה בחדש, באיזה יום\u0004 בשבוע, \u0003באיזה שעה, באיזה מקום. ר' יוסי אומר\u0004 היו שואלים אותו רק: \u0003באיזה יום, באיזה שעה, באיזה מקום.\u0004","ועוד היו שואלים: \u0003מכירין אתם אותו\u0004 שהוא האיש שעשה אותה עבירה? האם \u0003התרתם בו?\u0004 ואחר כך חוקרים בגוף הענין. אם האשימו אותו שהיה \u0003עובד עבודה זרה,\u0004 שואלים את העדים המעידים על כך \u0003את מי עבד, ובמה עבד\u0004 וכיוצא בו.","\u0003כל המרבה בבדיקות,\u0004 כלומר, שאלות לגבי פרטים, \u0003הרי זה משובח,\u0004 שמא על ידי כך יתברר שהעדים משקרים. \u0003מעשה ובדק בן זכאי בעוקצי תאנים,\u0004 בצבע או בצורה של קצות התאנים כדי למצוא אם יש סתירה בעדויות.","ומסבירים: \u0003מה בין חקירות לבדיקות?\u0004 — ב\u0003חקירות,\u0004 אם \u0003אחד\u0004 מהעדים \u0003אומר \"איני יודע\u0004 באיזה יום ובאיזו שעה \u0003\"\u0004— הרי \u0003עדותן בטילה\u0004 מיד. ב\u0003בדיקות,\u0004 אם \u0003אחד אומר \"איני יודע\", ואפילו\u0004 אם \u0003שנים אומרים \"אין אנו יודעין\"\u0004 — עדיין \u0003עדותן קיימת\u0004 ואינה בטילה. \u0003אחד חקירות ואחד בדיקות, בזמן שמכחישין\u0004 העדים \u0003זה את זה\u0004 — \u0003עדותן בטילה.\u0004","אם \u0003אחד\u0004 מהם \u0003אומר\u0004 שהיה הדבר \u0003בשנים בחדש ואחד אומר\u0004 שהיה הדבר \u0003בשלשה בחדש\u0004 — \u0003עדותן קיימת\u0004 ואין זו סתירה מחוייבת, שאפשר לומר \u0003שזה יודע בעיבורו של חדש,\u0004 שיודע שהחודש הקודם היה חודש מלא, בן שלושים יום, ולפי חשבונו אותו יום היה רק שני בחודש, \u0003וזה\u0004 השני \u0003אינו יודע בעיבורו של חדש\u0004 וסבר שהחודש הקודם היה רק בן עשרים ותשעה ימים, ולפי חשבונו היה זה כבר בשלישי בחודש.","אמנם אם \u0003זה אומר בשלשה\u0004 בחודש \u0003ואחד אומר בחמשה\u0004 — \u0003עדותן בטילה,\u0004 לפי שהבדל זמנים כזה אינו נובע מטעות.","וכן אם \u0003אחד אומר בשתי שעות,\u0004 שבשעה השניה ביום היה הדבר, \u0003ואחד אומר בשלש שעות\u0004 — \u0003עדותן קיימת,\u0004 שאדם יכול לטעות בהערכת שעות היום. ואולם אם \u0003אחד אומר בשלש ואחד אומר בחמש\u0004 — \u0003עדותן בטילה.\u0004","\u0003ר' יהודה אומר:\u0004 אף כאן עדותן \u0003קיימת,\u0004 משום שאפשר לטעות גם בשתי שעות. ואולם אם \u0003אחד אומר בחמש,\u0004 כלומר, בשעה החמישית משעות היום היה הדבר, \u0003ואחד אומר בשבע\u0004 — \u0003עדותן בטילה,\u0004 כי כאן ההבדל ניכר לכל, \u0003שבחמש\u0004 שעות ה\u0003חמה\u0004 עדיין \u0003ב\u0004צד \u0003מזרח ובשבע\u0004 ה\u0003חמה\u0004 כבר \u0003במערב,\u0004 ואי אפשר לטעות.","\u0003ואחר כך,\u0004 כלומר, לאחר ששאלו את העד הראשון לעצמו, \u0003מכניסין את\u0004 העד \u0003השני ובודקין אותו, אם נמצאו דבריהם\u0004 של העדים \u0003מכוונים\u0004 שמתאימים זה לזה, מתחילים לשאת ולתת בדבר, ומתחילה \u0003פותחין בזכות,\u0004 שתחילה אומרים דברים שהם לזכותו של הנאשם. אם \u0003אמר אחד מן העדים: יש לי\u0004 דברים לומר עליו ואשר עשויים \u0003ללמד עליו זכות, או\u0004 אמר \u0003אחד מן התלמידים\u0004 היושבים לפני החכמים: \u0003יש לי\u0004 דברים לומר עליו ואשר עלולים \u0003ללמד עליו חובה\u0004 — \u0003משתקין אותו,\u0004 שאין רשאים לעשות כן. ואולם אם \u0003אמר אחד מן התלמידים: יש לי ללמד עליו זכות\u0004 — \u0003מעלין אותו\u0004 למושב הסנהדרין \u0003ומושיבין אותו ביניהם, ולא היה יורד משם כל היום כולו,\u0004 אלא יושב ונושא ונותן עמם.","\u0003אם יש ממש בדבריו\u0004 של אותו תלמיד — \u0003שומעין לו. ואפילו הוא,\u0004 הנאשם, \u0003אומר: יש לי ללמד על עצמי זכות\u0004 — \u0003שומעין לו, ובלבד שיש ממש בדבריו,\u0004 כלומר, טענה שיש בה טעם.","\u0003ואם מצאו לו זכות\u0004 תוך כדי הדיון, שהסכימו כולם או רובם לזכות זו — \u0003פטרוהו, ואם לאו\u0004 \u0005[לא],\u0006 שרובם אינם מסכימים לזכותו — \u0003מעבירין אותו\u0004 הדין \u0003למחר, ו\u0004אז \u0003מזדווגין זוגות זוגות,\u0004 כלומר, דנים בדבר שנים שנים. \u0003היו ממעטין ממאכל, ולא היו שותין יין כל היום, ונושאין ונותנין כל הלילה, ולמחרת משכימין ובאין לבית\u0004 ה\u0003דין,\u0004 ואז דנים שוב בדעות הדיינים.","\u0003המזכה אומר: אני מזכה\u0004 הייתי, \u0003ומזכה אני במקומי,\u0004 כלומר, עומד אני בדברי לזכות. \u0003והמחייב אומר: אני מחייב, ומחייב אני במקומי. המלמד חובה\u0004 יכול אחר כך לחזור בו ויהיה \u0003מלמד זכות, אבל המלמד זכות אינו יכול לחזור וללמד חובה. טעו בדבר,\u0004 שאחד הדיינים שינה דעתו ושכח מה שאמר, \u0003שני סופרי הדיינין\u0004 שרשמו דבריהם תחילה \u0003מזכירין אותו. אם מצאו לו זכות\u0004 על דעת כולם — \u0003פטרוהו, ואם לאו\u0004 \u0005[לא]\u0006 היתה דעת הכל לזכות — \u0003עומדין למנין\u0004 (הצבעה). אם היו \u0003שנים עשר\u0004 דיינים \u0003מזכין ואחד עשר מחייבין\u0004 — הרי הוא \u0003זכאי.\u0004","\u0003שנים עשר מחייבין ואחד עשר מזכין, ואפילו אחד עשר מזכין ואחד עשר מחייבין, ואחד אומר \"איני יודע\", ואפילו\u0004 יתר על כן \u0003עשרים ושנים מזכין או מחייבין ואחד אומר \"איני יודע\",\u0004 הרי זה שאמר שאינו יודע כאילו לא היה בבית הדין, ו\u0003יוסיפו הדיינין\u0004 למניינם דיינים נוספים וכן הלאה עד שיגיעו להכרעה גמורה. \u0003וכמה מוסיפין?\u0004 — \u0003שנים שנים\u0004 בכל פעם שלא הגיעו להכרעה, \u0003עד\u0004 שמגיעים ל\u0003שבעים ואחד\u0004 דיינים, ויותר אין מוסיפים, ואז אם","\u0003שלשים וששה מזכין ושלשים וחמשה מחייבין\u0004 — \u0003זכאי. שלשים וששה מחייבין ושלשים וחמשה מזכין\u0004 — \u0003דנין\u0004 עדיין \u0003אלו כנגד אלו, עד שיראה\u0004 (יקבל) \u0003אחד מן המחייבין דברי המזכין,\u0004 שהרי אין דנים למיתה ברוב של קול אחד.","על האמור במשנה שואלים: \u0003מנא הני מילי\u0004 \u0005[מנין דברים אלה]\u0006 שעושים שבע חקירות? \u0003אמר רב יהודה:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בענין עיר הנדחת: \u0003\"ודרשת וחקרת ושאלת היטב\u0004 והנה אמת נכון הדבר נעשתה התועבה הזאת בקרבך\u0003\"\u0004 (דברים יג, טו), \u0003ואומר\u0004 בענין עובד עבודה זרה: \u0003\"והגד לך ושמעת ודרשת היטב\u0004 והנה אמת נכון הדבר נעשתה התועבה הזאת בישראל\u0003\"\u0004 (דברים יז, ד), \u0003ואומר\u0004 בדין עדים זוממים: \u0003\"ודרשו השופטים היטב\u0004 והנה עד שקר העד, שקר ענה באחיו\u0003\"\u0004 (דברים יט, יח), הרי שבע חקירות (ודרשת וחקרת היטב, ודרשת היטב, ודרשו היטב) רמוזות במקראות אלה."],["ומקשים: \u0003ואימא חדא חדא כדכתיבא\u0004 \u0005[ואמור אחת אחת כפי ש\u0006היא \u0005כתובה],\u0006 כלומר, שבאותו דין שנאמר בו \"ודרשת וחקרת היטב\" יהיו שלוש חקירות, וכן כיוצא בו באחרים, ש\u0003אם\u0004 לא \u0003כן\u0004 וצריכים שבע חקירות \u0003ליכתבינהו רחמנא בחדא\u0004 \u0005[שתכתוב התורה ב\u0006מקום \u0005אחד],\u0006 וילמדו השאר מדין זה! ומשיבים: \u0003כיון דכולהו בהדי הדדי כתיבא\u0004 \u0005[שכולם זה עם זה כתובים,\u0006 בלשון דומה\u0005]\u0006 — \u0003מהדדי ילפי\u0004 \u0005[למדים זה מזה],\u0006 \u0003וכיון דילפי מהדדי\u0004 \u0005[שלמדים זה מזה]\u0006 — הרי \u0003כמאן דכתיב בחדא דמי\u0004 \u0005[כמי שכתובים ב\u0006מקום \u0005אחד\u0006 הם \u0005נחשבים].\u0006","ומקשים: \u0003והא לא דמיא להדדי\u0004 \u0005[והרי אין\u0006 שלושת המקרים \u0005דומים זה לזה]!\u0006 \u0003(סימן\u0004 להבדלים: \u0003פלט, סייף, התראה).\u0004 כיצד?","\u0003עיר הנדחת להנך תרתי לא דמיא\u0004 \u0005[לאלה השתיים,\u0006 לעבודה זרה ועדים זוממים, \u0005אינה דומה],\u0006 \u0003שכן\u0004 האחרים \u0003ממונן פלט,\u0004 שאמנם ממיתים אותם אך אין מחרימים את ממונם, אבל אנשי עיר הנדחת לא זו בלבד שהם נענשים, אלא גם שורפים את כל רכושם. \u0003עבודה זרה להנך תרתי לא דמיא\u0004 \u0005[לאלה השתיים אינה דומה],\u0006 \u0003שכן\u0004 על העבירות האחרות נידונים \u0003בסייף,\u0004 ועל זו בסקילה. ודין \u0003עדים זוממין להנך תרתי לא דמיא\u0004 \u0005[לאלה השתיים אינו דומה],\u0006 \u0003שכן\u0004 העוברים בשתי העבירות האחרות \u0003צריכים התראה\u0004 לפני המעשה, ואילו בעדים זוממים אין מתרים לפני שהם מעידים.","ומשיבים: אין זו השוואה של דמיון מושגים בלבד, אלא \u0003ב\u0004גזירה שווה מן המילים \u0003\"היטב\" \"היטב\" ילפינן מהדדי\u0004 \u0005[למדים זה מזה].\u0006 ומעירים: \u0003וגזירה שוה\u0004 חייבת להיות \u0003מופנה,\u0004 שאותן מילים שמהן למדים גזירה שווה חייבות להיות מיותרות בעניינן, שבמקרה כזה אין מערערים על תוקף הגזירה השווה! \u0003דאי\u0004 \u0005[שאם]\u0006 היא \u0003לא מופנה\u0004 \u0003איכא למיפרך\u0004 \u0005[יש\u0006 מקום \u0005לפרוך,\u0006 לשבור ולהקשות\u0005]\u0006 על השוואה זו, \u0003לאיי אפנויי מופני\u0004 \u0005[על כן, בוודאי מופנים\u0006 הכתובים\u0005].\u0006 ומסבירים: \u0003מדהוה ליה למיכתב\u0004 \u0005[מכיון שהיה לו לכתוב]\u0006 רק \u0003\"ודרשו וחקרו\", ושני קרא בדיבוריה\u0004 \u0005[ושינה הכתוב בדיבורו]\u0006 וכתב \u0003\"\u0004ודרשו \u0003היטב\", שמע מינה\u0004 \u0005[למד מכאן]\u0006 שמילה זו \u0003לאפנויי\u0004 \u0005[להפנות],\u0006 כדי לשמש אחיזה לגזירה השווה.","ומקשים: \u0003ואכתי\u0004 \u0005[ועדיין]\u0006 הרי \u0003מופנה מצד אחד הוא,\u0004 שרק בפסוק אחד המלה מיותרת אבל לא בשניהם וצריך שיהיה מופנה משני הצדדים! \u0003בשלמא הנך תרתי\u0004 \u0005[נניח שני אלה]\u0006 שנאמר בהם גם דרישה וגם חקירה \u0003מופנה הוא, משום דהוה ליה למכתב\u0004 \u0005[שהיה לו לכתוב]\u0006 באופן אחד \"ודרשו וחקרו\", וכתב במקום זה \"היטב\", \u0003אלא עיר הנדחת מאי הוה ליה למכתב\u0004 \u0005[מה היה לו לכתוב\u0006 אחרת\u0005]?\u0006 \u0003הא כתיבא כולהו\u0004 \u0005[הרי כתובות כולן]!\u0006","ומשיבים: \u0003התם נמי אפנויי\u0004 \u0005[שם גם כן מופנית]\u0006 \u0003מופנה\u0004 המלה, \u0003מדהוה ליה למכתב\u0004 \u0005[מכיון שהיה לו לכתוב]\u0006 \u0003\"דרוש תדרש\" או \"חקור תחקר\", ושני קרא בדיבוריה\u0004 \u0005[ושינה הכתוב בדיבורו]\u0006 וכתב \u0003\"\u0004ודרשת וחקרת \u0003היטב\"\u0004 — \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שבא הדבר \u0003לאפנויי\u0004 \u0005[להפנות]\u0006 מילה זו לגזירה שווה. למדנו איפוא חובת דרישה וחקירה בעבירות שעונשן סקילה, ובעבירות שעונשן הריגה בסייף.","\u0003ואתו\u0004 \u0005[ובאו,\u0006 נלמדו\u0005]\u0006 לענין עבריינים שעונשם שהם \u0003נחנקין בקל וחומר מנסקלין ומנהרגין,\u0004 שמה אלה שעבירתם חמורה (שהרי עונשם חמור) דורשים חקירות כל כך, אלה שעבירתם קלה יותר, על אחת כמה וכמה. \u0003ואתו\u0004 \u0005[ובאו,\u0006 נלמדו\u0005]\u0006 \u0003נשרפין בקל וחומר מנסקלין.\u0004","ומקשים: \u0003הניחא\u0004 \u0005[\u0006דבר \u0005זה נוח]\u0006 \u0003ל\u0004שיטת \u0003רבנן דאמרי\u0004 \u0005[שאומרים]\u0006 ש\u0003סקילה חמורה\u0004 משריפה, ולכן אפשר ללמוד לגבי חטא שעונשו שריפה מחטא שעונשו סקילה בקל וחומר. \u0003אלא לר' שמעון\u0004 ש\u0003אמר\u0004 ש\u0003שריפה חמורה\u0004 מסקילה, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006","\u0003אלא אמר רב יהודה:\u0004 לא כך למדים, ויש להוסיף עוד למספר החקירות את מה שנאמר \"ודרשת וחקרת ושאלת היטב \u0003והנה אמת נכון\u0004 הדבר\" (דברים יג, טו) האמור בעיר הנדחת, וכן \"ודרשת היטב \u0003והנה אמת נכון\u0004 הדבר\" (דברים יז, ד) האמור בעובד עבודה זרה. שאם נצרף עוד את הביטוי \"אמת נכון\" לביטויים המדגישים את החקירה, \u0003הא\u0004 \u0005[הרי]\u0006 בסך הכל ישנן \u0003חד סרי\u0004 \u0005[אחת עשרה]\u0006 הדגשות, \u0003שבע\u0004 — \u0003לשבע חקירות,\u0004 ומתוך הארבע שנשארו \u0003דל תלת\u0004 \u0005[הוצא שלוש]\u0006 בכל מקרה \u0003ל\u0004צורך \u0003גזירה שוה\u0004 — \u0003פשא להו חדא\u0004 \u0005[נשאר לו\u0006 איפוא \u0005אחד].\u0006","\u0003לר' שמעון\u0004 בא ביטוי נוסף זה \u0003לאתויי\u0004 \u0005[להביא,\u0006 ללמד\u0005]\u0006 גם על \u0003נשרפין, ו\u0004אף \u0003ל\u0004דעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 הלומדים דבר זה בקל וחומר אין זה קושי, כי כלל בידינו: \u0003מילתא דאתיא\u0004 \u0005[דבר הבא,\u0006 נלמד\u0005]\u0006 \u0003בקל וחומר\u0004 פעמים ש\u0003טרח וכתב לה קרא\u0004 \u0005[אותו הכתוב\u0006 במפורש\u0005].\u0006","\u0003מגדף בה\u0004 \u0005[מקשה עליה]\u0006 בלשון קשה \u0003ר' אבהו: אימא לאתויי\u0004 \u0005[אמור\u0006 שבא הדבר \u0005להביא,\u0006 ללמד\u0005]\u0006 שצריך \u0003שמנה חקירות!\u0004 ושואלים: \u0003ושמנה חקירות מי איכא\u0004 \u0005[האם יש]?\u0006 והרי כבר מיצינו את כל החקירות האפשריות! ומשיבים: \u0003אלמה\u0004 \u0005[מדוע]\u0006 \u0003לא? והאיכא לאתויי\u0004 \u0005[והרי יש להוסיף]\u0006 שאלה \u0003בכמה בשעה,\u0004 כלומר, באיזה זמן בתוך השעה! \u0003ותניא נמי הכי\u0004 \u0005[ושנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003היו בודקין אותו בשמנה חקירות!\u0004","ומעירים: \u0003הניחא\u0004 \u0005[זה נוח]\u0006 \u0003ל\u0004שיטת \u0003אביי אליבא\u0004 \u0005[לפי שיטתו]\u0006 של \u0003ר' מאיר,\u0004 ש\u0003אמר: אין אדם טועה ולא כלום,\u0004 כלומר, אנו חוקרים את העדים מתוך הנחה שיכול אדם לדעת את השעה בדיוק. \u0003ולהך לישנא נמי\u0004 \u0005[ולאותה לשון גם כן]\u0006 ש\u0003אמר\u0004 אביי ש\u0003אדם טועה משהו\u0004 גם כן \u0003שפיר\u0004 \u0005[יפה],\u0006 יש מקום לשאול בכמה בשעה היה הדבר. \u0003אלא ל\u0004דעת \u0003אביי אליבא\u0004 \u0005[לפי שיטתו]\u0006 של \u0003ר' יהודה,\u0004 ש\u0003אמר: אדם טועה חצי שעה, ולרבא\u0004 ש\u0003אמר: טעו אינשי טובא\u0004 \u0005[אנשים טועים הרבה]\u0006 אפילו יותר משעה, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 שלפי זה אין מקום לחקירה של כמה בשעה!","ומשיבים: \u0003אלא\u0004 עדיין יש אפשרות של חקירה שמינית \u0003לאתויי\u0004 \u0005[להביא\u0006 שאלה\u0005]\u0006 \u0003בכמה ביובל,\u0004 כלומר, באיזה שנה משנות היובל היה מאורע זה.","ומקשים: \u0003היינו\u0004 \u0005[הרי זוהי]\u0006 בדיוק השאלה \u0003באיזה שבוע\u0004 ביובל היה הדבר! ומשיבים: \u0003אלא לאתויי\u0004 \u0005[להביא]\u0006 את השאלה \u0003באיזה יובל\u0004 היה הדבר. \u0003ואידך\u0004 \u0005[והאחר]\u0006 שאינו מתחשב באפשרות זאת סבור: \u0003כיון\u0004 ש\u0003אמר באיזה שבוע,\u0004 שוב \u0003לא בעי\u0004 \u0005[נצרך\u0006 לומר\u0005]\u0006 \u0003באיזה יובל,\u0004 שאין להעלות על הדעת שהוא מעיד על מאורע שמלפני חמישים שנה.","שנינו במשנה ש\u0003ר' יוסי אומר\u0004 ששואלים רק באיזה יום, באיזה שעה, באיזה מקום, ולא יותר. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 המפרטת יותר את המחלוקת. \u0003אמר להם ר' יוסי לחכמים: לדבריכם, מי שבא ואמר: אמש הרגו,\u0004 וכי \u0003אומר לו\u0004 הדיין בחקירתו: \u0003באיזו שבוע, באיזו שנה, באיזו חדש, בכמה בחדש\u0004 היה הדבר? שכן מה מקום לשאלות אלה? אלא די שישאלו לגבי היום, השעה והמקום.","\u0003אמרו לו: לדבריך, מי שבא ואמר: עכשו הרגו,\u0004 וכי \u0003אומר לו: באיזה יום, באיזה שעה, באיזה מקום\u0004 הרגו? הלא בכגון זה אין מקום אף לשאלות הללו!","\u0003אלא\u0004 אף לשיטתך, \u0003אף על גב דלא\u0004 \u0005[אף על פי שאין]\u0006 \u0003צריך,\u0004 מכל מקום \u0003רמינן עליה\u0004 \u0005[מטילים עליו]\u0006 את החובה לענות על כל השאלות, \u0003כ\u0004טעמו של \u0003ר' שמעון בן אלעזר,\u0004 שמטריחים את העדים בשאלות, שמא מתוך כך יתבלבלו ויודו שהם משקרים. \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 לשיטתנו, \u0003אף על גב דלא\u0004 \u0005[אף על פי שאינו]\u0006 \u0003צריך,\u0004 מכל מקום \u0003רמינן עליה\u0004 \u0005[מטילים עליו]\u0006 לענות על שאלות רבות, \u0003כ\u0004שיטת \u0003ר' שמעון בן אלעזר.\u0004","ושואלים: \u0003ור' יוסי\u0004 מה עונה הוא על טענה זו? ומסבירים: לדעתו, \u0003אמש הרגו\u0004 — \u0003שכיח\u0004 (מצוי) \u0003ברוב עדיות,\u0004 ויש להתחשב בכך בקביעת נוסח השאלות, אבל \u0003עכשיו הרגו\u0004 — \u0003לא שכיח ברוב עדיות,\u0004 ואין להתחשב באפשרות זו.","שנינו במשנה כי לאחר החקירות שואלים כמה שאלות יסודיות לגוף העדות, כגון: האם \u0003מכירים אתם אותו,\u0004 האם התריתם בו וכו'. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא את השאלות ששואלים את העדים בפירוט: האם \u0003מכירים אתם אותו,\u0004 את הנאשם האם יודעים אתם אם \u0003גוי הרג\u0004 או \u0003ישראל הרג\u0004 האם \u0003התריתם בו\u0004 האם \u0003קיבל עליו התראה,\u0004 שאמר שהוא שומע ויודע האם \u0003התיר עצמו למיתה,\u0004 כלומר, שאמר שהוא יודע שהעונש הוא מיתה ואף על פי כן עובר האם \u0003המית בתוך כדי דיבור\u0004 להתראה, שאם לא כן אין ההתראה צמודה למעשה ויכול לטעון ששכח.","או לענין \u0003העובד עבודה זרה\u0004 — \u0003את מי\u0004 מעבודות זרות \u0003עבד, לפעור עבד, למרקוליס עבד? ובמה עבד,\u0004 באיזה סוג עבודה: האם \u0003בזיבוח,\u0004 או \u0003בקיטור\u0004 קטורת, \u0003בניסוך\u0004 יין, \u0003בהשתחואה\u0004 לפניו?","\u0003אמר עולא: מניין ל\u0004חובת \u0003התראה מן התורה?\u0004 — \u0003שנאמר: \"ואיש אשר יקח את אחתו בת אביו או בת אמו וראה את ערותה\u0004 והיא תראה את ערותו חסד הוא ונכרתו לעיני בני עמם\u0003\"\u0004 (ויקרא כ, יז), ובמשמעות המילים יש לתהות: \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003בראיה תליא מילתא\u0004 \u0005[תלוי הדבר]?\u0006 הרי נענש על הביאה ולא על הראיה. \u0003אלא\u0004 ודאי הביטוי \"לראות\" סמלי הוא, ומשמעו: \u0003עד שיראוהו טעמו של דבר,\u0004 שצריך שיהיה מחוור לו שהוא עובר עבירה, ו\u0003אם אינו ענין לכרת,\u0004 שהרי לענין עונש כרת שמדובר בו שם אין צורך בהתראה שכן עונשו בידי שמים, וכלפי שמים גלוי אם עשה בזדון או בשגגה,"],["\u0003תנהו ענין ל\u0004דין \u0003מלקות,\u0004 שכדי שילקו או יענישו אותו שאר עונשי גוף חייב שיודיעוהו, ויהא ברור לו מה הוא עושה.","\u0003דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003חזקיה תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 הוכחה מכתוב זה, שנאמר: \u0003\"וכי יזד איש על רעהו להרגו בערמה\"\u0004 (שמות כא, יד), כיצד יודעים שהזיד? — \u0003שהתרו בו, ועדיין הוא מזיד.\u0004","\u0003דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003רבי ישמעאל תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 הוכחה מכתוב זה, שנאמר: \u0003\"\u0004ויקריבו אותו \u0003המצאים אתו מקשש עצים\"\u0004 (במדבר טו, לג), שכתוב בלשון הווה ללמד \u0003שהתרו בו\u0004 שלא יעשה, \u0003ועדיין הוא מקושש.\u0004","\u0003דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003רבי תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 ראיה מהפסוק: \u0003\"על דבר אשר ענה\u0004 את אשת רעהו\u0003\"\u0004 (דברים כב, כד) — \u0003על עסקי דיבור,\u0004 כלומר, שדיברו עמו מדוע עושה כן.","ומעירים: \u0003וצריכא\u0004 \u0005[וצריכים]\u0006 כל אותם מקראות, משום שמאחד מהם בלבד אי אפשר היה ללמוד. \u0003דאי כתב רחמנא\u0004 \u0005[שאילו היתה התורה כותבת]\u0006 דבר זה ב\u0003\"אחתו\"\u0004 בלבד, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003חייבי מלקות\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 צריכים התראה, אבל \u0003חייבי מיתות\u0004 שעבירתם חמורה — \u0003לא\u0004 יצטרכו התראה, לכן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"\u0004ו\u0003כי יזד\"\u0004 לענין רוצח.","\u0003ואי כתב רחמנא\u0004 \u0005[ואילו כתבה התורה]\u0006 רק \u0003\"וכי יזד\", הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא במיתת \u0003סייף דקיל\u0004 \u0005[ש\u0006היא \u0005קלה],\u0006 \u0003אבל סקילה\u0004 שהיא \u0003חמורה,\u0004 שמא על עבירה חמורה \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 צריכה התראה, על כן \u0003צריכא\u0004 \u0005[נצרכה לומר]\u0006 גם במחלל השבת.","ושואלים: \u0003ותרתי\u0004 \u0005[ושתי\u0006 פעמים\u0005]\u0006 \u0003ב\u0004דין \u0003ה\u0004\u0003נסקלין למה לי?\u0004 שהרי נאמר פעם במחלל שבת ופעם באונס נערה המאורסה שהוא בסקילה! ומשיבים: \u0003ל\u0004דעת \u0003ר' שמעון\u0004 בא הדבר \u0003לאתויי\u0004 \u0005[להביא,\u0006 ללמד\u0005]\u0006 גם \u0003נשרפין,\u0004 שלשיטתו נשרפים חמורים מנסקלים, והוא לומד זאת ב\"אם אינו ענין לנסקלים תנהו ענין לנשרפים\",","\u0003לרבנן\u0004 \u0005[ל\u0006דעת \u0005חכמים]\u0006 אין זה קשה כי \u0003מילתא דאתיא\u0004 \u0005[דבר שבא,\u0006 נלמד\u0005]\u0006 \u0003בקל וחומר\u0004 פעמים ש\u0003טרח וכתב לה קרא\u0004 \u0005[אותו הכתוב]\u0006 במפורש. ושואלים: \u0003ולכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 דין התראה רק \u0003בנסקלין, וליתו הנך וליגמרו מיניה\u0004 \u0005[ושיבואו\u0006 כל \u0005אלו וילמדו ממנו]!\u0006 ומשיבים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003מילתא דאתיא\u0004 \u0005[דבר שבא,\u0006 נלמד\u0005]\u0006 \u0003בקל וחומר\u0004 פעמים ש\u0003טרח וכתב לה קרא\u0004 \u0005[אותו הכתוב]\u0006 במפורש.","שנינו בברייתא כי בין החקירות בעדות על ההורג נפש שואלים את העדים גם האם \u0003התיר עצמו\u0004 הנאשם לאחר ההתראה \u0003למיתה,\u0004 שצריך שיאמר שהוא מקבל עליו את העונש. ושואלים: \u0003מנא לן\u0004 \u0005[מנין לנו]\u0006 דבר זה? \u0003אמר רבא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003חזקיה, אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"\u0004על פי שנים עדים או שלושה עדים \u0003יומת המת\"\u0004 (דברים, יז, ו), וכוונתו: \u0003עד שיתיר עצמו למיתה.\u0004","\u0003אמר רב חנן: עדי נערה המאורסה ש\u0004באו והעידו ששכבה עם מישהו מרצונה, אם \u0003הוזמו\u0004 — \u0003אין נהרגין.\u0004 וטעם הדבר \u0003—\u0004 \u0003מתוך שיכולים לומר\u0004 שלא להעיד להורגה באנו אלא \u0003לאוסרה על בעלה באנו,\u0004 שהרי אשת איש שנבעלה מרצונה לאיש אחר אסורה לבעלה, ולשם כך העדנו.","ומקשים: \u0003והא אתרו\u0004 \u0005[והרי התרו]\u0006 \u0003בה\u0004 ואמרו לה: דעי לך שענשך מיתה, וכיצד יכולים הם לומר שלא להרגה באו? ומשיבים: מדובר כאן באופן \u0003ש\u0004\u0003לא אתרו\u0004 \u0005[התרו]\u0006 \u0003בה.\u0004 ומקשים: \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא אתרו\u0004 \u0005[התרו]\u0006 \u0003בה היכי מיקטלא\u0004 \u0005[כיצד\u0006 היא עצמה \u0005נהרגת]?\u0006 ואם אכן אינה נידונה למיתה, ודאי שאין העדים נהרגים!","ומשיבים: מדובר שם \u0003באשה חבירה\u0004 היודעת תורה, \u0003ואליבא\u0004 \u0005[ולפי שיטתו]\u0006 של \u0003ר' יוסי בר' יהודה. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יוסי בר' יהודה אומר: חבר\u0004 (תלמיד חכם) \u0003אין צריך התראה\u0004 כדי להיענש, \u0003לפי שלא נתנה התראה אלא להבחין בין שוגג למזיד\u0004 וזה הלא יודע שאסור.","ומקשים עוד: \u0003וכיון דאינהו לא מיקטלי\u0004 \u0005[שהם אינם נהרגים]\u0006 על עדותם הזוממת, \u0003איהי היכי מיקטלא\u0004 \u0005[היא כיצד נהרגת]\u0006 על כך? והלא \u0003הויא לה\u0004 \u0005[הרי היא]\u0006 \u0003עדות שאי\u0004 (אין) \u0003אתה יכול להזימה, וכל עדות שאי אתה יכול להזימה\u0004 ולענוש את הזוממים \u0003לא שמה,\u0004 אינה קרויה כלל \u0003עדות!\u0004","ומשיבים: \u0003הכי נמי קאמר\u0004 \u0005[כך גם כן אמר],\u0006 וזו היתה כוונתו: \u0003מתוך שאין נהרגין, ש\u0004הרי \u0003יכולין\u0004 הם \u0003לומר \"לאוסרה על בעלה באנו\", אף היא אינה נהרגת, דהויא לה\u0004 \u0005[שהרי היא]\u0006 \u0003עדות שאי אתה יכול להזימה.\u0004","ומקשים: \u0003אלא\u0004 דין הזמה \u0003באשה חבירה, דקיימא לן דמיקטלא\u0004 \u0005[שמוחזק לנו ש\u0006היא \u0005נהרגת],\u0006 \u0003אליבא\u0004 \u0005[על פי שיטתו]\u0006 של \u0003ר' יוסי בר' יהודה, היכי משכחת לה\u0004 \u0005[כיצד מוצא אתה אותה]\u0006 שאפשר שיעשו כן, שהרי אם לא התרו בה אי אפשר להרגה? ומשיבים: שמעידים \u0003שזינתה וחזרה וזינתה,\u0004 ועל הזנות השניה אין העדים יכולים לומר שבאו לאוסרה על בעלה, שהרי כבר אסורה היא משעת ביאה ראשונה.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003יכולין לומר: \"לאוסרה על בועלה\u0004 ה\u0003שני באנו\"!\u0004 שכשם שאשה שזנתה אסורה לבעלה, כך אסורה היא גם לזה שבא עליה גם לכשתתגרש מבעלה. ואומרים העדים שבאו להעיד רק שאסורה לבועל השני! ומשיבים: מדובר כאן \u0003שזינתה מבועל ראשון,\u0004 כלומר, זינתה פעם שניה עם אותו אדם וכבר היא אסורה עליו, ואז אין מקום לטענה זו. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 במקרה \u0003שזינתה מקרוביה,\u0004 שגם בלי העדות הריהי אסורה להינשא להם, ואין יכולים העדים לומר שבאו לאוסרה עליהם.","ושואלים: אם כן, \u0003מאי שנא\u0004 \u0005[מה שונה]\u0006 דוגמה של \u0003נערה מאורסה דנקט\u0004 \u0005[שתפס]?\u0006 \u0003אפילו נשואה נמי\u0004 \u0005[גם כן]\u0006 אפשר שיהא בה דין זה! ומשיבים: \u0003אין\u0004 \u0005[כן]\u0006 הוא, \u0003אלא אפילו האי דלא יתבא תותיה\u0004 \u0005[זו שאינה יושבת תחתיו],\u0006 כלומר, שאינה עוד אשתו, \u0003יכולין\u0004 העדים \u0003לומר: \"לאוסרה על בעלה באנו\u0004 וכלל לא היתה כוונתנו להעיד עליה להורגה \u0003\".\u0004","\u0003אמר רב חסדא: אחד\u0004 העדים \u0003אומר \"בסייף הרגו\", ואחד אומר \"בארירן\u0004 (כעין גרזן) \u0003הרגו\"\u0004 — \u0003אין זה \"נכון\"\u0004 (\"והנה אמת נכון הדבר\". דברים יז, י), שברור שיש סתירה בעדות. ואולם אם \u0003אחד\u0004 מהעדים \u0003אומר \"כליו\u0004 (בגדיו) של ההורג היו \u0003שחורין\", ואחד אומר \"כליו לבנים\"\u0004 — \u0003הרי זה נכון,\u0004 ואין לומר שיש כאן הכחשה מהותית בעדות.","\u0003מיתיבי\u0004 \u0005[מקשים],\u0006 נאמר: \"והנה אמת נכון הדבר\" ו\u0003\"נכון\"\u0004 כוונתו \u0003שיהא נכון\u0004 — מכוון, ששני העדים מסכימים בעדותם. אם עד \u0003אחד אומר \"בסייף הרגו\", ואחד אומר \"בארירן הרגו\", אחד אומר \"כליו שחורין\", ואחד אומר \"כליו לבנים\"\u0004 — \u0003אין זה נכון.\u0004 וקשה איפוא לדברי רב חסדא. \u0003תרגמה\u0004 \u0005[הסבירה]\u0006 \u0003רב חסדא\u0004 לאותה ברייתא: מדובר בה \u0003בסודר שחנקו בו,\u0004 שדנים בכלים שהרג בהם, וצבע הסודר הוא איפוא עדות הנוגעת לגוף המעשה, \u0003דהיינו\u0004 \u0005[שזהו]\u0006 כמו בעדויות שניים על \u0003סייף וארירן.\u0004","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו במקום אחר: עד \u0003אחד אומר \"סנדליו שחורין\", ואחד אומר \"סנדליו לבנים\"\u0004 — \u0003אין זה \"נכון\"!\u0004 ומשיבים: לשיטת רב חסדא \u0003התם נמי\u0004 \u0005[שם גם כן]\u0006 מדובר \u0003כגון שבעט בו בסנדלו והרגו,\u0004 שהיא עדות על עצם ההריגה.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו במשנתנו: \u0003מעשה ובדק בן זכאי בעוקצי תאנה,\u0004 משמע שאפשר למצוא סתירה אפילו בדברים שאינם בגוף המעשה! ומשיבים: \u0003אמר רמי בר חמא:\u0004 מדובר כאן \u0003כגון שעקץ\u0004 (קטף) \u0003תאנה בשבת, דעלה קא מיקטיל\u0004 \u0005[שעליה הוא נהרג],\u0006 ועדותם בתאנה היא מגוף העדות.","ומקשים: \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 האומרת: \u0003אמרו לו \"תחת תאנה הרגו\",\u0004 משמע שמדובר בדיני רוצח! \u0003אלא אמר רמי בר חמא: כגון ששפדו בייחור של תאנה,\u0004 שלקח ענף תאנה והרגו בו, ואף כאן הדבר הוא מגוף העדות.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 שבאותה חקירה של בן זכאי \u0003אמר להן: \"תאנה זו\u0004 שאתם מעידים אודותיה ביחס לנאשם, האם \u0003עוקציה דקין,\u0004 או ש\u0003עוקציה גסין,\u0004 האם היו ה\u0003תאנים\u0004 שעליה \u0003שחורות,\u0004 או היו ה\u0003תאנים לבנות\"?\u0004 וענין שחורות ולבנות בוודאי מתייחס לפרי התאנה ולא לענף של התאנה, משמע שלא בגוף העדות חקר! \u0003אלא\u0004 יש לדחות את ההסברים הקודמים, \u0003אמר רב יוסף:\u0004 וכי \u0003מבן זכאי לותיב איניש\u0004 \u0005[יקשה אדם]\u0006 לדיני חקירות? \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003בן זכאי\u0004 ש\u0003בדיקות כחקירות משוי ליה\u0004 \u0005[עושה\u0006 הוא \u0005אותן],\u0006 שלדעת בן זכאי סתירה בבדיקות הריהי כסתירה בחקירות, ופוטרים את הנאשם.","כיון שדנו בחקירה שערך בן זכאי שואלים: \u0003מאן\u0004 \u0005[מיהו]\u0006 \u0003בן זכאי\u0004 זה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהיה זה \u0003ר' יוחנן בן זכאי, מי הוה\u0004 \u0005[האם\u0006 אמנם \u0005היה]\u0006 חבר \u0003בסנהדרי\u0004 שדנה בדיני נפשות? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כל שנותיו של ר' יוחנן בן זכאי\u0004 היו \u0003מאה ועשרים שנה. ארבעים שנה\u0004 מהן \u0003עסק בפרקמטיא\u0004 (במסחר), \u0003ארבעים שנה למד,\u0004 ו\u0003ארבעים שנה לימד\u0004 והנהיג את ישראל.","\u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003ארבעים שנה קודם חורבן הבית גלתה סנהדרי\u0004 מלשכת הגזית \u0003וישבה לה בחנות. ואמר ר' יצחק בר אבודימי:\u0004 כוונת הביטוי \u0003לומר שלא דנו\u0004 עוד בסנהדרי \u0003דיני קנסות.\u0004 ותוהים: \u0003דיני קנסות סלקא דעתך\u0004 \u0005[עולה על דעתך\u0006 לומר\u0005]?\u0006 והלא דיני קנסות המשיכו לדון בארץ ישראל מאות שנים לאחר חורבן הבית! \u0003אלא\u0004 יש לתקן ולומר: \u0003שלא דנו דיני נפשות.\u0004 שכאשר אין סנהדרי גדולה יושבת עוד במקומה בלשכת הגזית, בטל תוקף בתי הדין לדון דיני נפשות.","\u0003ותנן\u0004 \u0005[ו\u0006כיון ש\u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003משחרב בית המקדש התקין רבן יוחנן בן זכאי,\u0004 הרי יודעים מכאן שהאריך ימים גם לאחר החורבן, ולפי זה נמצא שבארבעים השנים שלימד היה זה כבר לאחר הזמן שבטלה הסנהדרין מתפקידה (שכן כבר ארבעים שנה קודם החורבן לא דנו דיני נפשות)!","\u0003אלא\u0004 יש לומר שהיה זה \u0003בן זכאי דעלמא\u0004 \u0005[סתם],\u0006 אדם אחר שנקרא \"בן זכאי\". ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר\u0006 לומר\u0005],\u0006 \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 שהיה זה \u0003רבן יוחנן בן זכאי, קרי ליה\u0004 \u0005[קורא לו]\u0006 \u0003רבי\u0004 (ר' יהודה הנשיא) במשנה בלשון זלזול \u0003\"בן זכאי\"\u0004 סתם? אלא ודאי איש אחר היה.","ומקשים: \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 מפורשת: \u0003מעשה ובדק רבן יוחנן בן זכאי בעוקצי תאנים!\u0004 אלא יש לומר כך: באותה שעה שעשה כן לא היה מחברי הסנהדרין \u0003אלא תלמיד היושב לפני רבו הוה\u0004 \u0005[היה],\u0006 ובאותן שנים סנהדרין במקומה היתה ודנה דיני נפשות, \u0003ואמר מילתא\u0004 \u0005[דבר]\u0006 בתוך כדי חקירת העדים, \u0003ומסתבר להו טעמיה\u0004 \u0005[והיה מסתבר להם\u0006 לסנהדרין \u0005טעמו]\u0006 וקיבלו את דבריו,"],["\u0003וקבעוה\u0004 להלכה זו \u0003בשמיה\u0004 \u0005[בשמו\u0006\u0005].\u0006 \u0003כי הוה למד\u0004 \u0005[\u0006ו\u0005כאשר היה לומד\u0006 לעצמו\u0005],\u0006 \u0003\"בן זכאי\" הוה קרי ליה\u0004 \u0005[היו קוראים לו\u0006\u0005]\u0006 \u0003כ\u0004פי שקוראים ל\u0003תלמיד היושב לפני רבו, כי הוה לימד הוה קרי ליה\u0004 \u0005[\u0006ו\u0005כאשר היה מלמד\u0006 לאחרים \u0005היו קוראים לו\u0006\u0005]\u0006 \u0003\"רבן יוחנן בן זכאי\".\u0004 וההבדל בין שני המקורות, \u0003כי קרי ליה\u0004 \u0005[כאשר קרא לו]\u0006 במקור אחד \u0003\"בן זכאי\"\u0004 — \u0003על שם דמעיקרא\u0004 \u0005[ש\u0006היה \u0005מתחילה]\u0006 שכך קראו לו אז, \u0003וכי קרי ליה\u0004 \u0005[כאשר קרא לו\u0006\u0005]\u0006 \u0003\"רבן יוחנן בן זכאי\"\u0004 — \u0003על שם דהשתא\u0004 \u0005[של עכשיו\u0006\u0005].\u0006","שנינו במשנה: \u0003מעשה ובדק כו' מה בין חקירות\u0004 ובדיקות, שאפילו שנים אומרים \"אין אנו יודעים\" לא בטלה עדותם. ושואלים: \u0003מאי\u0004 \u0005[מה\u0006\u0005]\u0006 המשמעות \u0003\"אפילו שנים אומרים\", פשיטא\u0004 \u0005[פשוט,\u0006 ברור\u0005]\u0006 \u0003כי\u0004 כאשר \u0003אמר אחד \"איני יודע\"\u0004 — \u0003עדותן קיימת,\u0004 ומשמע אם כן שאין ידיעה זו חלק הכרחי מן העדות, ואשר על כן גם \u0003כי אמרי בי תרי נמי\u0004 \u0005[כאשר אומרים שנים גם כן\u0006\u0005]\u0006 שאינם יודעים — \u0003עדותם קיימת!\u0004","\u0003אמר רב ששת: ארישא קאי,\u0004 \u0003והכי קאמר\u0004 \u0005[על תחילת\u0006 המשנה \u0005מוסב\u0006 הדבר\u0005, וכך אמר\u0006\u0005]:\u0006 \u0003בחקירות\u0004 היסודיות \u0003אפילו שנים אומרים \"ידענו\", ואחד אומר \"איני יודע\"\u0004 — \u0003עדותן בטילה. כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי\u0006\u0005]\u0006 משנתנו — כשיטת \u0003ר' עקיבא, דמקיש\u0004 \u0005[שמשווה\u0006\u0005]\u0006 לכל פרטי הדינים \u0003שלשה\u0004 עדים \u0003לשנים,\u0004 שכשם ששני עדים צריכים להעיד עדות שלמה, אף שלושה כן.","\u0003אמר רבא: והא\u0004 \u0005[והרי]\u0006 \u0003\"עדותן קיימת\" קתני\u0004 \u0005[שונה\u0006\u0005]\u0006 במשנה ולא \"עדותן בטילה\"! \u0003אלא אמר רבא: הכי קאמר\u0004 \u0005[כך אמר\u0006\u0005]:\u0006 \u0003אפילו בחקירות, שנים אומרים \"ידענו\" ואחד אומר \"איני יודע\"\u0004 — \u0003עדותן קיימת,\u0004 שסומכים על עדות השנים. \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי\u0006\u0005]\u0006 תהא משנתנו — ש\u0003לא כ\u0004שיטת \u0003ר' עקיבא\u0004 המשוה שלושה לשנים.","מסופר: \u0003רב\u0004 \u0003כהנא ורב ספרא תנו\u0004 \u0005[שנו]\u0006 מסכת \u0003סנהדרין בי\u0004 \u0005[\u0006ב\u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003רבה.\u0004 \u0003פגע בהו\u0004 \u0005[פגש בהם\u0006\u0005]\u0006 \u0003רמי בר חמא. אמר להו\u0004 \u0005[להם]:\u0006 \u0003מאי אמריתו\u0004 \u0005[מה\u0006 דבר חידוש \u0005אומרים אתם]\u0006 \u0003בה ב\u0004מסכת \u0003סנהדרין\u0004 שאתם לומדים \u0003דבי\u0004 \u0005[בבית\u0006 מדרשו\u0005]\u0006 של \u0003רבה?\u0004 \u0003אמרי ליה\u0004 \u0005[אמרו לו]:\u0006 \u0003ומאי אמרינן\u0004 \u0005[ומה אומרים אנו]\u0006 \u0003בה ב\u0004מסכת \u0003סנהדרין גרידתא\u0004 \u0005[סתם]\u0006 שאין למדים בבית רבה, \u0003ומאי קשיא\u0004 \u0005[ומה קשה]\u0006 \u0003לך?\u0004 שנראה שאתה רוצה לשמוע תשובה לקושי מסויים במסכת זו על פי דברי רבה.","\u0003אמר להו\u0004 \u0005[להם]:\u0006 קשה לי \u0003מהא דקתני\u0004 \u0005[מזו ששנינו\u0006\u0005],\u0006 \u0003מה בין חקירות לבדיקות,\u0004 אם ב\u0003חקירות\u0004 עד \u0003אחד אומר \"איני יודע\"\u0004 — \u0003עדותן בטילה,\u0004 ואילו ב\u0003בדיקות\u0004 אם \u0003אמר\u0004 עד \u0003אחד \"איני יודע\", ואפילו שנים אומרים \"אין אנו יודעים\"\u0004 — \u0003עדותן\u0004 \u0003קיימת. מכדי אידי ואידי דאורייתא\u0004 \u0005[הרי זו וזו מן התורה]\u0006 \u0003היא,\u0004 שגם חקירות וגם בדיקות מחוייבות על פי דיני התורה, שהכל נכלל במצוה לחקור היטב את העדים, ואם כן \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003חקירות, ומאי שנא\u0004 \u0005[ובמה שונה]\u0006 \u0003בדיקות?\u0004","\u0003אמרי ליה\u0004 \u0005[אמרו לו]:\u0006 \u0003הכי השתא\u0004 \u0005[כיצד אתה משווה]?!\u0006 \u0003בחקירות,\u0004 אם \u0003אמר\u0004 עד \u0003אחד \"איני יודע\"\u0004 — \u0003עדותן בטילה\u0004 מן הטעם \u0003דהויא לה\u0004 \u0005[שהרי היא\u0006\u0005]\u0006 \u0003עדות שאי\u0004 (אין) \u0003אתה יכול להזימה,\u0004 שאם הזמן והמקום אינם מדוייקים בדברי העדים שוב אי אפשר להזים עדות זו ולומר לעדים שהיו באותה שעה במקום אחר. אבל ב\u0003בדיקות\u0004 — אם \u0003אמר אחד מהן \"איני יודע\"\u0004 — \u0003עדותן קיימת,\u0004 שהרי עדיין \u0003עדות שאתה יכול להזימה הוא.\u0004","\u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אי הכי אמריתו\u0004 \u0005[אם כך אומרים,\u0006 מחדשים \u0005אתם]\u0006 \u0003בה,\u0004 במסכת זו — \u0003טובא אמריתו\u0004 \u0005[הרבה אומרים אתם]\u0006 \u0003בה,\u0004 והרבה חדשתם לי בכך. \u0003אמרי ליה\u0004 \u0005[אמרו לו]:\u0006 \u0003מטיבותיה דמר\u0004 \u0005[מפני טובתו של אדוני],\u0006 כלומר, מפני רצונך הטוב לקבל דברינו, נחשב הדבר כאילו \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 \u0003בה טובא\u0004 \u0005[הרבה\u0006\u0005].\u0006 ואולם \u0003מנזיהותיה דמר\u0004 \u0005[מנזיפתו\u0006 וקושייתו \u0005של אדוני]\u0006 \u0003לא אמרינן\u0004 \u0005[היינו אומרים]\u0006 \u0003בה ו\u0004אפילו \u0003לא חדא\u0004 \u0005[\u0006דבר \u0005אחד\u0006 \u0005],\u0006 משום שאילו רצית לנזוף בנו ולדחות דברינו יכולת למצוא פרכה וקושיה בהם, וכאילו לא אמרנו בה דבר.","שנינו במשנה שאם היה עד \u0003אחד אומר\u0004 שהיה הדבר בשני בחודש, והאחד אומר בשלישי בו — עדותן קיימת, שמא לא ידע אחד מהם בעיבורו של החודש הקודם, וממילא לא ידע גם מתי חל ראש חודש זה. ושואלים: \u0003עד כמה\u0004 ימים בחודש אפשר לומר שאחד העדים אינו יודע מתי היה ראש החודש? \u0003אמר ר' אחא בר חנינא אמר ר' אסי אמר ר' יוחנן: עד רובו של חודש,\u0004 וכשעבר רובו של החודש אין לומר שהעד אינו יודע בימי החודש.","\u0003אמר רבא: אף אנן נמי תנינא\u0004 \u0005[אנחנו גם כן שנינו\u0006\u0005]\u0006 במשנה סיוע לכך שכאשר \u0003אחד אומר\u0004 שהיה הדבר \u0003בשלשה\u0004 בחודש \u0003ואחד אומר\u0004 שהיה הדבר \u0003בחמשה\u0004 בחודש — \u0003עדותן בטילה. ואמאי\u0004 \u0005[ומדוע\u0006\u0005]\u0006 אומרים אנו כן? \u0003נימא\u0004 \u0005[נאמר\u0006\u0005]\u0006 שאף כאן נגרם הדבר מחמת חוסר ידיעה בלבד, \u0003שזה יודע בשני עיבורין,\u0004 שיודע שעיברו את שני החדשים הקודמים ולכן יודע הוא שהיה רק בשלושה בחודש, \u0003וזה\u0004 שאמר בחמישה \u0003אינו יודע בשני עיבורין. אלא לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דברובה ידע\u0004 \u0005[שברובו\u0006 של \u0005החודש הוא יודע\u0006\u0005]\u0006 ולכן לא יתכן שיטעה אדם בשני ראשי חדשים.","את הראיה דוחים: \u0003לעולם אימא\u0004 \u0005[\u0006יכול \u0005אני לומר]\u0006 \u0003לך\u0004 שאפילו \u0003ברובה\u0004 של חודש \u0003נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 \u0003לא ידע,\u0004 אלא \u0003בשיפורא\u0004 \u0005[\u0006על ידי \u0005שופר]\u0006 שנהגו לתקוע בו בראש החודש \u0003ידע.\u0004 אלא שעדיין \u0003בחד שיפורא אמר דטעי\u0004 \u0005[ב\u0006תקיעת \u0005שופר אחת אמור שטעה\u0006 ולא שמע\u0005]\u0006 \u0003בתרי שיפורא\u0004 \u0005[בשתי\u0006 תקיעות \u0005שופר]\u0006 \u0003לא\u0004 יתכן ש\u0003אמר דטעי\u0004 \u0005[וטעה\u0006\u0005].\u0006","כיון שהוזכרו דברי ר' אחא בר חנינא, מביאים דבר אחר בשם מסורת זו, \u0003אמר ר' אחא בר חנינא אמר רב אסי אמר ר' יוחנן: עד כמה מברכין על החדש\u0004 את הברכה על חידוש הלבנה — \u0003עד שתתמלא פגימתה\u0004 של הלבנה, כאשר אינה נראית עוד פגומה כקשת קטנה. \u0003וכמה\u0004 הוא זמן זה? \u0003אמר ר' יעקב בר אידי אמר רב יהודה: עד שבעה\u0004 ימים בחודש. \u0003נהרדעי אמרי\u0004 \u0005[\u0006חכמי \u0005נהרדעא אומרים\u0006\u0005]\u0006 \u0003עד ששה עשר\u0004 יום בו."],["\u0003ותרוייהו\u0004 \u0005[ושניהם]\u0006 \u0003כר' יוחנן סבירא להו\u0004 \u0005[סבורים\u0006 \u0005הם],\u0006 ולא נחלקו אלא בפירוש דבריו, מהו מילוי פגימתה. כי \u0003הא\u0004 \u0005[זו\u0006 עד שבעה\u0005]\u0006 — \u0003למיהוי כי יתרא\u0004 \u0005[\u0006\u0005כדי שתהיה כמו יתר\u0006 של קשת \u0005]\u0006 שקודם לכן הירח נראה רק כקשת, ולאחר שבעה ימים כבר נראה כחצי עיגול, כקשת שיש לה יתר, וזוהי לדעתם מילוי הפגימה. \u0003הא\u0004 \u0005[זו]\u0006 — \u0003למיהוי כי נפיא\u0004 \u0005[כדי שתהיה כמו כברה\u0006\u0005],\u0006 כלומר, עיגול שלם, והוא נקרא לדעתם מילוי הפגימה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא מדיפתי לרבינא: וליבריך\u0004 \u0005[ושיברכו\u0006\u0005]\u0006 ברכת \u0003\"הטוב והמטיב\"\u0004 בשעת קידוש הלבנה, על ההנאה שיש לבני אדם ממאור הירח! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אטו כי\u0004 \u0005[וכי כאשר]\u0006 \u0003חסר\u0004 אור הירח \u0003מי מברכינן\u0004 \u0005[האם מברכים אנו]\u0006 כמו על שאר אסונות \u0003\"\u0004ברוך... \u0003דיין האמת\" דלבריך\u0004 \u0005[כדי שיברכו]\u0006 במילואה \u0003\"הטוב והמטיב\"?\u0004 אמר לו: אמנם אין נוהגים כן, אבל היא היא השאלה: \u0003וליברכינהו לתרוייהו\u0004 \u0005[ויברכו את שתיהן\u0006\u0005]\u0006 \"דיין האמת\" בחסרונה ו\"הטוב והמטיב\" במילואה! וענה לו: \u0003כיון דהיינו אורחיה, לא מברכינן\u0004 \u0005[כיון שזו דרכו, אין אנו מברכים\u0006\u0005],\u0006 שדרך העולם היא שתהא הלבנה פוחתת, ומוספת. \u0003ואמר ר' אחא בר חנינא אמר ר' אסי אמר ר' יוחנן: כל המברך על החדש בזמנו\u0004 — \u0003כאילו מקבל פני שכינה.\u0004 ורמז לדבר — \u0003כתיב הכא\u0004 \u0005[נאמר כאן\u0006\u0005]\u0006 בענין קידוש חדשים \u0003\"החדש הזה\u0004 לכם ראש חדשים ראשון הוא לכם לחדשי השנה\u0003\"\u0004 (שמות יב, ב), \u0003וכתיב התם\u0004 \u0005[ונאמר שם\u0006\u0005]:\u0006 \u0003\"זה אלי ואנוהו\"\u0004 (שמות טו, ב), שהוא כתוב המדבר בגילוי השכינה בשעת קריעת ים סוף. \u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל:\u0004 \u0003אילמלא לא זכו ישראל אלא להקביל פני אביהן שבשמים כל חדש וחדש\u0004 פעם אחת \u0003דיים,\u0004 כיון שיש בברכת הלבנה כעין הקבלת פני שכינה. \u0003אמר אביי: הלכך נימרינהו\u0004 \u0005[על כן נאמר אותה,\u0006 את הברכה] \u0003מעומד\u0004 מפני השכינה.","","מסופר: \u0003מרימר ומר זוטרא מכתפי אהדדי ומברכי\u0004 \u0005[היו נשענים זה על כתפי זה ומברכים\u0006\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא לרב אשי: במערבא מברכי\u0004 \u0005[במערב,\u0006 בארץ ישראל, \u0005מברכים\u0006\u0005]\u0006 על הירח: \u0003\"ברוך מחדש חדשים\". אמר ליה\u0004 \u0005[לו]:\u0006 ברכה זו \u0003האי, נשי דידן נמי מברכי\u0004 \u0005[\u0006את הברכה \u0005הזו, הנשים שלנו גם כן מברכות\u0006\u0005],\u0006 כלומר, נוסח זה ידוע לכל, שאף אלה שלא למדו יודעים אותו.","\u0003אלא\u0004 הנוסח השלם הוא \u0003כ\u0004דברי \u0003רב יהודה.\u0004 ש\u0003אמר רב יהודה,\u0004 מברך: \u0003\"ברוך... אשר במאמרו ברא שחקים, וברוח פיו כל צבאם\u0004 (צבא השמים), \u0003חק וזמן נתן להם שלא ישנו את תפקידם, ששים ושמחים\u0004 גרמי השמים \u0003לעשות רצון קונם,\u0004 והם \u0003פועלי אמת שפעולתן אמת,\u0004 שהרי ממלאים תפקידם ואינם משנים ממנהגם, \u0003וללבנה אמר שתתחדש,\u0004 והיא \u0003עטרת תפארת\u0004 (סימן ורמז תפארה) \u0003לעמוסי בטן\u0004 הם ישראל הקרויים העמוסים על ידי ה', \u0003שהן עתידין להתחדש כמותה,\u0004 שלמרות שהם לעתים יורדים, יגיעו לדרגה גבוהה ויגיעו \u0003לפאר ליוצרם על שם כבוד מלכותו, ברוך אתה ה' מחדש חדשים\".\u0004 ועוד בשם אותה מסורת על הכתוב \u0003\"כי בתחבלות תעשה לך מלחמה\"\u0004 (משלי כד, ו) \u0003אמר ר' אחא בר חנינא אמר ר' אסי אמר ר' יוחנן: במי אתה מוצא מלחמתה של תורה\u0004 ועיקר כוחה \u0003במי שיש בידו חבילות של משנה,\u0004 כלומר, שאי אפשר להגיע לדרגה גבוהה בלימוד התורה בלי ידיעת חומר בסיסי רב. \u0003קרי\u0004 \u0005[היה קורא\u0006\u0005]\u0006 \u0003רב יוסף אנפשיה\u0004 \u0005[על עצמו\u0006\u0005]\u0006 \u0003\"ורב תבואות בכח שור\"\u0004 (משלי יד, ד), כלומר, מי שכוחו רב יכול להביא יבול הרבה, שהוא היה מפורסם כאחד מגדולי הבקיאים.","","שנינו במשנה שאם עד \u0003אחד אומר בשתי שעות\u0004 היה המעשה ואחד אומר בשלוש — עדותם קיימת. \u0003אמר רב שימי בר אשי: לא שנו אלא\u0004 שהיה הבדל ב\u0003שעות,\u0004 \u0003אבל\u0004 אם היה עד \u0003אחד אומר\u0004 שאירע הדבר \u0003קודם הנץ החמה\u0004 (שנראתה השמש) \u0003ואחד אומר לאחר הנץ החמה,\u0004 שבכך אי אפשר לטעות, למרות שאין הבדל זמן גדול — \u0003עדותן בטילה.\u0004","ותוהים: \u0003פשיטא\u0004 \u0005[פשוט\u0006 הדבר\u0005]!\u0006 הרי ודאי יש הבדל בין חושך לאור! \u0003אלא\u0004 יש לפרש כך: \u0003אחד אומר קודם הנץ\u0004 החמה היה, \u0003ואחד אומר בתוך הנץ\u0004 — אף כאן עדותם בטילה. ומקשים: \u0003הא נמי פשיטא\u0004 \u0005[\u0006דבר \u0005זה גם כן פשוט\u0006\u0005]!\u0006 ומשיבים, \u0003מהו דתימא\u0004 \u0005[שתאמר\u0006\u0005]:\u0006 \u0003הא בגילויא קאי וזהרורי בעלמא\u0004 \u0005[זה\u0006 שאמר בתוך הנץ \u0005ב\u0006מקום \u0005גלוי עמד וזוהר בלבד]\u0006 \u0003הוא דחזא\u0004 \u0005[שראה\u0006\u0005],\u0006 ונדמה לו שרואה את הנץ החמה. על כך \u0003קא משמע לן\u0004 \u0005[השמיע לנו\u0006\u0005]\u0006 שאין להניח שאנשים טועים בכך. שנינו במשנה ש\u0003אחר כך,\u0004 כלומר, לאחר ששאלו את העד הראשון לעצמו, \u0003מכניסין\u0004 את העד השני ובודקים אותו, ואם נמצאו דברי העדים מכוונים מתחילים לשאת ולתת בדבר, ואם אמר אחד מן התלמידים דבר לזכות, לא היו מורידים אותו מן הסנהדרין כל אותו היום. ומקשים: \u0003אותו היום ותו לא\u0004 \u0005[ולא עוד],\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אם יש ממש בדבריו לא היה יורד משם לעולם,\u0004 שהרי הוכיח שגדול כוחו כאחד החכמים, \u0003ואם אין ממש בדבריו אין יורד כל היום כולו, כדי שלא תהא עלייתו ירידה לו,\u0004 שאם יורידוהו מיד — יתבייש, כאילו הורידוהו בנזיפה, על כן תיקנו שלא ירד מיד, שלא יתביישו התלמידים מלומר דבר לזכות. \u0003אמר אביי: תרגומה\u0004 \u0005[תרגם,\u0006 פרש\u0005]\u0006 את האמור במשנתנו לענין המקרה של \u0003אם אין ממש בדבריו\u0004.","","עוד שנינו במשנה שאם \u0003מצאו לו זכות\u0004 תוך כדי הדיון, שהסכימו כולם או רובם לזכות זו — פטרוהו, ואם רובם אינם מסכימים לזכותו — מעבירים את הדיון ליום המחרת ודנים בדבר שנים שנים והיו ממעטים באכילה ובשתיית יין כל אותו היום. ושואלים: \u0003יין מאי טעמא\u0004 \u0005[מה הטעם]\u0006 \u0003לא\u0004 ישתו? \u0003אמר ר' אחא בר חנינא, אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"\u0004אל למלכים שתו יין \u0003ולרוזנים אי שכר\"\u0004 (משלי לא, ד), ומפרש: \u0003העוסקין ברזו\u0004 (ה\"רוזנים\") \u0003של עולם,\u0004 בדברים חמורים אלה \u0003אל ישתכרו.\u0004 \u0003מצאו לו זכות כו',\u0004 במשנה שנינו שכאשר אין בית הדין מגיע להסכמה ונמצא שקול מוסיפים דיינים עד לשבעים ואחד והם דנים בדבר עד שיראה אחד המחייבים דבר המזכים. ושואלים: אם \u0003לא ראו\u0004 ועדיין נשאר בית הדין שקול בדעות המחייבים והמזכים, \u0003מאי\u0004 \u0005[מה]\u0006 יהא דינו? \u0003אמר ר' אחא: פוטרין אותו,\u0004 שהרי לא נתחייב לגמרי. \u0003וכן אמר ר' יוחנן: פוטרין אותו. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי:\u0004 אם לא הגיע בית הדין המורחב לכלל הסכמה, מדוע ממתינים עוד, \u0003וליפטריה מעיקרא\u0004 \u0005[ושיפטרו אותו מתחילה],\u0006 כשרואים שההרכב הגדול ביותר אינו יכול להכריע! \u0003אמר ליה\u0004 \u0005[לו]\u0006 : \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' יוחנן:\u0004 הטעם הוא \u0003כדי שלא יצאו מבית דין מעורבבין\u0004 ומבולבלים, שגנאי לבית דין שלא הגיע להחלטה. ולכן משתדלים שיגיעו למסקנה מסויימת.","","","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 כי כך \u0003אמר ליה רב פפא לאביי: ולמה לי\u0004 \u0003יוסיפו\u0004 דיינים כלל, \u0003ליפטריה מבי דינא קמא\u0004 \u0005[יפטרו\u0006 אותו \u0005מבית הדין הראשון],\u0006 שאם לא יכלו להחליט להרשיעו — יצא זכאי, ומדוע מרחיבים את בית הדין? \u0003אמר ליה\u0004 \u0005[לו]\u0006 : \u0003ר' יוסי קאי כוותך\u0004 \u0005[עומד כמוך\u0006 בשיטתך\u0005],\u0006 שכיוונת לדעתו, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יוסי אומר: כשם שאין מוסיפין על בית דין של שבעים ואחד, כך אין מוסיפין על בית דין של עשרים ושלשה.\u0004 ואם לא נגמר הדין הרי זה כמחלוקת בבית דין הגדול ואין מוסיפים. \u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 \u0003אומר\u0004 הדיין בשעה שעוסק \u0003בדיני ממונות: \"נזדקן הדין\",\u0004 כלומר, דין זה הוא קשה וצריך עיון, \u0003ואין אומר\u0004 בשעת עיסוק \u0003בדיני נפשות \"נזדקן הדין\".\u0004","","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"נזדקן הדין\"? אילימא\u0004 \u0005[אם תאמר]\u0006 שהכוונה היא \u0003\"קש דינא\"\u0004 \u0005[נזדקן\u0006 והאריך זמנו של \u0005דין\u0006 זה\u0005]\u0006 ועדיין לא עמדנו עליו ויש עוד לעיין בו, ואולם אם כן \u0003איפכא מיבעיא ליה\u0004 \u0005[ההיפך צריך היה לו]\u0006 לומר, שבדיני נפשות יאמרו כן, ויוסיפו לברר, ולא בדיני ממונות! \u0003אמר רב הונא בר מנוח משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא: איפוך\u0004 \u0005[הפוך]\u0006 את הגרסה, ואמור שבדיני ממונות — אין אומרים, בדיני נפשות — אומרים. \u0003רב אשי אמר: לעולם לא תיפוך\u0004 \u0005[אל תהפוך],\u0006 \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"נזדקן הדין\"\u0004 — \u0003חכם דינא\u0004 \u0005[החכים,\u0006 כזקן שקנה חכמה, \u0005הדין]\u0006 והגיע הדין לסוף בירורו ומיצויו ושוב אין לדון בכך אלא רק להצביע.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על ההסבר הראשון ממה ששנינו: \u0003גדול שבדיינין אמר\u0004 במקרה שלא הגיע להכרעה \u0003\"נזדקן הדין\".\u0004 ומעתה \u0003אי אמרת בשלמא חכם דינא\u0004 \u0005[נניח אם אומר אתה\u0006 שכוונתו הוא ש\u0005החכים הדין]\u0006 והגענו למיצויו, \u0003היינו\u0004 \u0005[זהו]\u0006 אם כן מה \u0003דאמר\u0004 \u0005[שאומר]\u0006 ה\u0003גדול\u0004 שיש בכך משום כבוד לבית הדין, \u0003אלא אי אמרת קש דינא\u0004 \u0005[אם אומר אתה\u0006 שכוונתו הוא ש\u0005הזדקן הדין]\u0006 ואיננו יודעים עדיין, וכי \u0003לא סגיא\u0004 \u0005[אינו די]\u0006 ש\u0003לא אמר\u0004 \u0005[יאמר]\u0006 זאת דווקא ה\u0003גדול?\u0004 וכי \u0003כסופי\u0004 \u0005[לבייש]\u0006 \u0003הוא דקא מיכסיף נפשיה\u0004 \u0005[מבייש\u0006 את \u0005עצמו]?\u0006","ומשיבים: \u0003אין\u0004 \u0005[כן\u0006 הוא\u0005],\u0006 וכך יפה לו שאמנם יש בדבר בושה, אך \u0003אינו דומה מתבייש מעצמו\u0004 (שמבייש עצמו) \u0003למתבייש מאחרים,\u0004 ומוטב שהוא יגיד ולא אחר.","\u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 שהקשו בדרך שונה: \u0003אי אמרת בשלמא קש דינא\u0004 \u0005[נניח אם אמרת\u0006 שכוונתו היא \u0005נזדקן הדין],\u0006 \u0003היינו\u0004 \u0005[זהו]\u0006 הטעם שהדיין הגדול מכריז, לפי ש\u0003אינו דומה מתבייש מעצמו למתבייש מאחרים, אלא אי אמרת חכם דינא\u0004 \u0005[אם אומר אתה\u0006 שהכוונה היא \u0005החכים הדין]\u0006 וכי \u0003גדול אשבוחי משבח נפשיה\u0004 \u0005[משבח את עצמו]?\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"יהללך זר ולא פיך,\u0004 נכרי ואל שפתיך \u0003\"\u0004(משלי כז, ב)! ומשיבים: \u0003שאני מילתא דבי דינא\u0004 \u0005[שונה דבר בית הדין]\u0006 שעל ה\u0003גדול רמיא\u0004 \u0005[\u0006הוא \u0005מוטל],\u0006 שהגדול בדיינים הוא המשמש להם דובר לכל ענין וענין. \u0003כדתנן\u0004 \u0005[כפי ששנינו\u0006 במשנה\u0005]:\u0006 \u0003גמרו את הדבר, היו מכניסין אותן, גדול שבדיינין אומר: \"איש פלוני אתה זכאי, איש פלוני אתה חייב\".\u0004","",""],["\u0003נגמר הדין\u0004 לחובה ודנו אותו לסקילה, \u0003מוציאין אותו לסוקלו. בית הסקילה היה חוץ לבית דין\u0004 ורחוק ממנו קצת, \u0003שנאמר: \"הוצא את המקלל\u0004 אל מחוץ למחנה...","ורגמו אותו כל העדה\u0003\"\u0004 (ויקרא כד, יד). איש \u0003אחד\u0004 היה \u0003עומד על פתח בית דין והסודרין בידו, וסוס רחוק ממנו\u0004 כמרחק \u0003כדי שיהא רואהו.\u0004 אם \u0003אומר אחד\u0004 מחברי בית הדין: \u0003\"יש ללמד עליו זכות\", הלה,\u0004 בעל הסודרין, \u0003מניף בסודרין, והסוס רץ\u0004 אחרי שליחי בית הדין \u0003ומעמידן,\u0004 וממתינים עד שיברר בית הדין אם אמנם זכות זו יש בה ממש. \u0003ואפילו הוא,\u0004 הנידון עצמו, \u0003אומר: יש לי ללמד על עצמי זכות\u0004 — \u0003מחזירין אותו,\u0004 ו\u0003אפילו ארבע וחמש פעמים, ובלבד שיש ממש בדבריו\u0004 שטוען.","ותוהים: \u0003ובית הסקילה חוץ לבית דין הוה\u0004 \u0005[היה\u0006\u0005]\u0006 \u0003ותו לא\u0004 \u0005[ולא עוד\u0006\u0005]?\u0006 כלומר, האם די רק שמרחיקים אותו מעט מבית דין ולא יותר? \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003בית הסקילה היה חוץ לשלש מחנות,\u0004 לאמור — מחוץ לתחום העיר וחומותיה, כאמור במקרא!","ומשיבים: \u0003אין כדקאמרת\u0004 \u0005[כן\u0006 הוא, \u0005כמו שאמרת\u0006\u0005]\u0006 שהיה מקומו חוץ לשלוש מחנות, \u0003והא דקתני הכי\u0004 \u0005[וזה ששנינו כך\u0006\u0005]\u0006 במשנה, \u0003נפקא מינה\u0004 \u0005[יוצא,\u0006 נלמד, \u0005מכאן\u0006\u0005]\u0006 לענין זה: \u0003דאי נפיק בי דינא ויתיב\u0004 \u0005[שאם\u0006 מזדמן \u0005שיוצא בית הדין ויושב\u0006\u0005]\u0006 \u0003חוץ לשלש מחנות\u0004 גם אז \u0003עבדינן\u0004 \u0005[עושים אנו\u0006\u0005]\u0006 את \u0003בית הסקילה חוץ לבית דין\u0004 במקום רחוק ולא בסמוך לבית הדין, \u0003כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003לא מיתחזי\u0004 \u0005[יהיו נראים\u0006\u0005]\u0006 \u0003בית דין\u0004 כ\u0003רוצחין. אי נמי\u0004 \u0005[או גם כן\u0006\u0005]\u0006 מפני הטעם \u0003כי היכי דתיהוי ליה\u0004 \u0005[כדי שתהא לו,\u0006 לנידון\u0005]\u0006 אפשרות \u0003הצלה,\u0004 שבתוך הזמן שיוליכוהו מבית הדין לבית הסקילה, ימצא מישהו זכות לו.","לגופה של ההלכה שואלים: \u0003מנהני מילי\u0004 \u0005[מנין דברים אלה\u0006\u0005]\u0006 שהסקילה נעשית חוץ לשלוש מחנות? \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: מה שנאמר \u0003\"הוצא את המקלל אל מחוץ למחנה\u0004 (ויקרא כד, יד) הכוונה היא: מ\u0003חוץ לשלש מחנות,\u0004 כלומר, אף מחוץ למחנה ישראל. \u0003אתה אומר\u0004 שמשמעו \u0003חוץ לשלש מחנות, או אינו אלא חוץ למחנה אחת\u0004 בלבד. על כן יש להביא ראיה: \u0003נאמר כאן \"מחוץ למחנה\"\u0004 (ויקרא ד, יב) , \u0003ונאמר בפרים הנשרפין\u0004 שצריכים לשרפם \u0003\"חוץ למחנה\", מה להלן חוץ לשלש מחנות, אף כאן חוץ\u0004 \u0003לשלש מחנות,\u0004 ושואלים:","\u0003והתם\u0004 \u0005[ושם\u0006\u0005]\u0006 בפרים הנשרפים \u0003מנלן\u0004 \u0005[מנין לנו\u0006\u0005]\u0006 שכך הדין? ומשיבים: \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]\u0006 בברייתא: מה שנאמר \u0003\"והוציא את כל הפר אל מחוץ למחנה\u0004 אל מקום טהור אל שפך הדשן ושרף אותו על עצים באש על שפך הדשן ישרף\u0003\"\u0004 (ויקרא ד, יב) הכוונה \u0003חוץ לשלש מחנות. אתה אומר\u0004 שהוא \u0003חוץ לשלש מחנות, או אינו אלא חוץ למחנה אחת?\u0004","\u0003כשהוא אומר\u0004 \"והוציא את הפר \u0003אל מחוץ למחנה\u0004 ושרף אותו כאשר שרף את הפר הראשון חטאת הקהל הוא\" (ויקרא ד, כא) שנאמר \u0003ב\u0004שריפת \u0003פר העדה\u0004 (\"הקהל\") שמביאים על שגגת בית הדין הגדול. \u0003שאין תלמוד לומר,\u0004 שלכאורה אין צורך בכך — \u0003שהרי כבר נאמר \"ושרף אתו כאשר שרף את הפר הראשון\"\u0004 (ויקרא ד, כא) ואין צורך לומר שנית היכן שורפים אותו, אלא יש לומר שבא כתוב נוסף זה \u0003ליתן לו מחנה שניה,\u0004 שמוציאים אותו לא רק ממחנה שכינה (המקדש) אלא אף ממחנה לויה (הר הבית בירושלים),","\u0003וכשהוא אומר\u0004 \"והוציא את הדשן \u0003אל מחוץ למחנה\u0004 אל מקום טהור\" (ויקרא ו, ד)\u0003 ב\u0004שפיכת ה\u0003דשן\u0004 (אפר המזבח), \u0003שאין תלמוד לומר,\u0004 שלכאורה אין צורך בפסוק זה, \u0003שהרי כבר נאמר\u0004 בפר \u0003\"על שפך הדשן ישרף\"\u0004 (ויקרא ד, יב), ומשם למדנו ששריפת הפר היא במקום שפיכת הדשן, ונאמר שם שהיא מחוץ למחנה — הרי פסוק נוסף זה בא \u0003ליתן לו מחנה שלישית,\u0004 להוציאו אף ממחנה ישראל (או מכל ירושלים).","על הלימוד בנסקלים משריפת הפר מקשים: אמנם נאמר \"חוץ למחנה\" אך שמא \u0003לילף\u0004 \u0005[ילמד\u0006\u0005]\u0006 דין המקלל \u0003משחוטי חוץ,\u0004 מן האיסור להקריב קרבן חוץ למקדש שאף שם נאמר \"חוץ למחנה\", \u0003מה להלן\u0004 בשחוטי חוץ הכוונה \u0003חוץ למחנה אחת\u0004 (מחנה שכינה, המקדש) \u0003אף כאן חוץ למחנה אחת!\u0004","ומשיבים: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 כי \u0003מ\u0004דין \u0003פרים הנשרפין הוה ליה למילף\u0004 \u0005[היה לו ללמוד\u0006\u0005],\u0006","\u0003שכן\u0004 נאמר בהם באותה לשון עצמה \u0003\"הוצא אל מחוץ למחנה\"\u0004 ולא רק \"מחוץ למחנה\". ועוד דמיון מהותי: שהוא \u0003מכשיר\u0004 שגם שריפת הפרים וגם סקילה הן מצוות הנעשות בהכשר, מה שאין כן שחוטי חוץ שעבירה היא. \u0003ו\u0004עוד ששניהם הם \u0003מכפר,\u0004 ששריפת הפרים קשורה לכפרה, וכן המתת הנידון כפרה היא לו.","ודוחים: \u0003אדרבה\u0004 (להיפך) \u0003משחוטי חוץ הוה ליה למילף\u0004 \u0005[היה לו ללמוד\u0006\u0005],\u0006","\u0003שכן\u0004 כאן יש צדדים של דמיון, ששניהם דנים \u0003אדם\u0004 ולא בפרים, \u0003חוטא\u0004 (ולא כמצוותו), שהמקלל חוטא וגם השוחט בחוץ חוטא הוא, ובשניהם דיני נפשות, שאף השוחט בחוץ חייב מיתה, ויש פה ענין של יציאת \u0003נשמה,\u0004 וצד \u0003פיגול\u0004 ששייך בפרים ולא במקלל ושחוטי חוץ.","ומשיבים: בכל זאת \u0003מכשיר ממכשיר עדיף ליה\u0004 \u0005[לו\u0006\u0005]\u0006 להשוות, שמשווים שתי מצוות זו לזו, ולא מצוה ועבירה.","\u0003רב פפא אמר:\u0004 מגופי המקראות אפשר ללמוד את הדבר: \u0003משה היכא הוה יתיב\u0004 \u0005[היכן היה יושב\u0006\u0005]\u0006 — \u0003במחנה לוייה,\u0004 שהרי לוי היה, ולשם הביאו אליו את המקלל לדין. \u0003ואמר ליה רחמנא\u0004 \u0005[לו ה'\u0006\u0005]:\u0006 \u0003\"הוצא את המקלל אל מחוץ למחנה\"\u0004 (ויקרא כד, יד), משמע שיוציאוהו \u0003חוץ למחנה לוייה\u0004, ממחנה לוייה למחנה ישראל, ונאמר הלאה: \u0003\"\u0004וידבר משה אל בני ישראל \u0003ויוציאו את המקלל אל מחוץ למחנה\"\u0004 (ויקרא כד, כג), הרי שהוציאוהו אף מחוץ למחנה ישראל.","על הוכחה זו מקשים: \u0003האי\u0004 \u0005[זה\u0006\u0005]\u0006 הפסוק הנוסף \u0003מיבעי ליה\u0004 \u0005[נצרך לו\u0006\u0005]\u0006 ללמד \u0003ל\u0004ענין \u0003עשייה,\u0004 שכך אכן קיימו בני ישראל! ומשיבים: \u0003עשייה\u0004 \u0003בהדיא כתיבא\u0004 \u0005[במפורש\u0006 היא \u0005כתובה],\u0006 שהרי נאמר:"],["\u0003\"ובני ישראל עשו כאשר צוה ה' את משה\"\u0004 (ויקרא כד, כג).","ומקשים: אם דברים אלה לכך נאמרו, \u0003אלא מעתה\u0004 מה שנאמר קודם \u0003\"\u0004ויוציאו את המקלל אל מחוץ למחנה \u0003וירגמו אתו באבן\"\u0004 (ויקרא כד, כג) \u0003מאי עבדי ליה\u0004 \u0005[מה עושים\u0006 הם \u0005בו,\u0006 מה למדים מכאן\u0005]?\u0006 ומשיבים: הפסוק \u0003ההוא מבעי ליה\u0004 \u0005[נצרך לו]\u0006 לדרשה אחרת, \u0003לכדתניא\u0004 \u0005[לכפי ששנינו\u0006 בברייתא\u0005]:\u0006 מה שנאמר \u0003\"וירגמו אתו באבן\"\u0004 למדים מכאן: רק \u0003אתו,\u0004 כלומר, הוא עצמו, כשהוא ערום \u0003ולא בכסותו. \"אבן\"\u0004 ולא אבנים, ללמד \u0003שאם מת באבן אחת\u0004 — \u0003יצא. ו\u0004מעירים כי","\u0003אצטריך למיכתב\u0004 \u0005[הוצרך לכתוב\u0006] בדיני סקילה \u0003\"אבן\"\u0004 \u0003ואצטריך למיכתב\u0004 \u0005[והוצרך לכתוב]\u0006 במקושש \u0003\"אבנים\"\u0004 \"מות יומת האיש רגום אותו באבנים כל העדה מחוץ למחנה\" (במדבר טו, לה). \u0003דאי כתב רחמנא\u0004 \u0005[שאם היתה כותבת התורה]\u0006 רק \u0003\"אבן\" הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי \u0003היכא\u0004 \u0005[היכן]\u0006 ש\u0003לא מת בחדא\u0004 \u0005[באחת]\u0006 \u0003לא ניתי אחריתי ומקטליה\u0004 \u0005[יביאו אחרות ויהרגוהו\u0006\u0005],\u0006 על כן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה\u0006\u0005]\u0006 \u0003\"אבנים\". ואי כתב רחמנא\u0004 \u0005[ואם היתה כותבת התורה]\u0006 רק \u0003\"אבנים\" הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי \u0003מעיקרא נייתי תרתי\u0004 \u0005[מתחילה יביאו שתים],\u0006 על כן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"אבן\"\u0004.","על הראיה שהביא רב פפא מקשים: \u0003והא האי תנא\u0004 \u0005[והרי תנא זה]\u0006 שדן בדבר \u0003\"נאמר\" קאמר\u0004 \u0005[אמר]\u0006 וסמך על גזירה שווה, וכיצד חולק עליו רב פפא? ומשיבים: \u0003\"אילו לא נאמר\" קאמר\u0004 \u0005[אמר]\u0006, וכך יש להבין את דבריו: \u0003אילו לא נאמר קרא\u0004 \u0005[מקרא\u0006] במשה אף אז \u0003הייתי אומר גזירה שוה\u0004 ויודע זאת מגזירה שווה, \u0003עכשיו שנאמר קרא\u0004 \u0005[המקרא]\u0006 \u0003גזירה שוה לא צריך.\u0004","\u0003רב אשי אמר:\u0004 יש הוכחה אחרת לדבר מלשון הכתובים, \u0003משה היכא הוה יתיב\u0004 \u0005[היכן היה יושב\u0006\u0005]\u0006 — \u0003במחנה לוייה ואמר ליה רחמנא\u0004 \u0005[לו ה'\u0006\u0005]\u0006 \u0003\"הוצא את המקלל\"\u0004 (ויקרא כד, יד), ומשמעו שיוציאו \u0003חוץ למחנה לוייה,\u0004 וכיון שנאמר הלאה \u0003\"אל מחוץ למחנה\"\u0004 (ויקרא כד, כג), הרי הוא ציווי נוסף שיוציאוהו \u0003חוץ למחנה ישראל\u0004 ומה שנאמר \u0003\"ויוציאו את המקלל\"\u0004 (ויקרא כד, כג) בא ללמד \u0003לעשייה,\u0004 שכן עשו בני ישראל.","ומקשים: \u0003עשייה בהדיא כתיב בהו\u0004 \u0005[במפורש נאמר בהם\u0006\u0005]\u0006 \u0003\"ובני ישראל עשו כאשר צוה ה' את משה\"\u0004 (ויקרא כד, כג)! ומשיבים: הפסוק \u0003ההוא מיבעי ליה\u0004 \u0005[\u0006\u0005נצרך לו\u0006\u0005]\u0006 ללמוד לעשיית שאר דברים שבמיתת סקילה, שלא רק הוציאוהו אלא אף קיימו כדבר משה, \u0003חד\u0004 \u0005[אחד\u0006\u0005]\u0006 לענין \u0003סמיכה,\u0004 שהעדים צריכים לסמוך ידיהם על ראש הנאשם (כאמור: \"וסמכו כל השומעים את ידיהם על ראשו\". ויקרא כד, יד) \u0003וחד\u0004 \u0005[אחד\u0006\u0005]\u0006 \u0003לדחייה,\u0004 שצריכים העדים לדחות (לדחוף) אותו מגובה בית הסקילה למטה.","\u0003אמרו ליה רבנן\u0004 \u0005[לו חכמים\u0006\u0005]\u0006 \u0003לרב אשי: לדידך\u0004 \u0005[לשיטתך\u0006\u0005]\u0006 \u0003כל הני\u0004 \u0005[אותם]\u0006 \u0003\"הוצא\" דכתיבי\u0004 \u0005[הכתובים\u0006\u0005]\u0006 \u0003בפרים הנשרפים מאי דרשת בהו\u0004 \u0005[מה דורש אתה בהם\u0006\u0005]?\u0006 שהרי לשיטתך, שהמלה \"הוצא\" בלבד משמעה הוצאה מחוץ למחנה, נמצאו איפוא הרבה כתובים מיותרים! ומשיבים: אכן \u0003קשיא\u0004 \u0005[קשה\u0006\u0005]\u0006 ולא פירש.","שנינו במשנה שהיה \u0003אחד עומד\u0004 וסודרין בידו כדי לאותת לשליחי בית הדין המוליכים את הנאשם למקום ההריגה אם יתגלה ספק בחובת הנאשם. \u0003אמר רב הונא: פשיטא\u0004 \u0005[פשוט]\u0006 \u0003לי\u0004 כי \u0003אחד אבן שנסקל בה ואחד עץ שנתלה בו ואחד סייף שנהרג בו ואחד סודר שנחנק בו\u0004 במיתות השונות — \u0003כולן\u0004 ניתנים \u0003משל צבור. מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — \u0003דמדידיה לא אמרינן ליה זיל וליתיה וליקטול נפשיה\u0004 \u0005[שמשלו אין אנו אומרים לו שילך ויביא ויהרוג את עצמו\u0006\u0005]\u0006 באלה.","ואולם, \u0003בעי\u0004 \u0005[שאל\u0006\u0005]\u0006 \u0003רב הונא: סודר שמניפין בו, וסוס שרץ ומעמידן, משל מי הוא?\u0004 האם נוטלין את ההוצאות משל הנאשם או משל הציבור? וצדדי השאלה: \u0003כיון\u0004 שלשם \u0003הצלה דידיה\u0004 \u0005[שלו]\u0006 הם, אם כן \u0003מדידיה\u0004 \u0005[משלו]\u0006 \u0003הוא\u0004 שנוטלים, \u0003או דילמא\u0004 \u0005[שמא\u0006\u0005]\u0006 \u0003כיון דבי דינא מחייבין למעבד בה\u0004 \u0005[שבית הדין מחוייבים לעשות בו]\u0006 \u0003הצלה\u0004 — \u0003מדידהו\u0004 \u0005[משלהם הוא\u0006 בא\u0005]?\u0006","\u0003ותו\u0004 \u0005[ועוד\u0006\u0005]\u0006 שאלה כיוצא בה, \u0003הא\u0004 \u0005[זו\u0006\u0005]\u0006 ש\u0003אמר רב חייא בר אשי אמר רב חסדא: היוצא ליהרג משקין אותו קורט\u0004 (מעט) \u0003לבונה בכוס של יין כדי שתטרף דעתו\u0004 ותתבלבל מעט ולא יסבול כל כך מאימת המוות הממשמש ובא, \u0003שנאמר:\u0004 \u0003\"תנו שכר לאובד ויין למרי נפש\"\u0004 (משלי לא, ו), \u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003נשים יקרות\u0004 (חשובות) \u0003שבירושלים היו מתנדבות ומביאות אותן,\u0004 את משקה זה. והשאלה היא: אם \u0003לא התנדבו נשים יקרות, משל מי\u0004 הוא בא? ומשיבים: \u0003הא\u0004 \u0005[\u0006בשאלה \u0005זו\u0006\u0005]\u0006 \u0003ודאי מסתברא\u0004 \u0005[מסתבר\u0006\u0005]\u0006 שנותנים \u0003של צבור, כיון דכתיב\u0004 \u0005[שנאמר\u0006\u0005]\u0006 במקרא: \u0003\"תנו\"\u0004 בלשון רבים, הרי הוא ודאי \u0003מדידהו\u0004 \u0005[משלהם].\u0006","\u0003בעא מיניה\u0004 \u0005[שאל אותו\u0006\u0005]\u0006 \u0003רב אחא בר הונא מרב ששת:\u0004 אם \u0003אמר אחד מן התלמידים \"יש לי ללמד עליו זכות\", ונשתתק\u0004 (נעשה אלם) ולא יכול לומר טעמו, \u0003מהו\u0004 הדין בכגון זה? האם מתחשבים אף בדעתו, או אין מביאים אותה בחשבון? \u0003מנפח\u0004 \u0005[מנפנף]\u0006 היה \u0003רב ששת\u0004 בתנועת זלזול \u0003בידיה\u0004 \u0005[בידיו],\u0006 ואמר: \u0003נשתתק\u0004 ודאי שאין שמים לב אליו, שאם תחשוש לכך \u0003אפילו אחד בסוף העולם נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 תצטרך לחשוש שמא יש מישהו שיודע לו זכות. ודוחים: אינו דומה, שכן \u0003התם לא קאמר\u0004 \u0005[אמר\u0006\u0005]\u0006 מישהו שיש לו טעם לזכות הנאשם, ואולם \u0003הכא קאמר\u0004 \u0005[כאן אמר]\u0006 במפורש, ויש איפוא מקום לשאלה, \u0003מאי\u0004 \u0005[מה\u0006 הדין \u0005]?\u0006","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע\u0006\u0005]\u0006 פתרון לדבר ממה ש\u0003אמר ר' יוסי בר חנינא: אחד מן התלמידים שזיכה ומת\u0004 — \u0003רואין אותו כאילו חי ועומד במקומו.\u0004 ומשמע: אם \u0003זיכה,\u0004 כלומר, נתן נימוק אשר בעטיו עשוי הוא לזכות בדין — \u0003אין\u0004 \u0005[כן\u0006\u0005],\u0006 אם \u0003לא זיכה\u0004 — \u0003לא!\u0004","ענה לו רב אחא בר הונא מכאן אין לפתור, שכן \u0003זיכה פשיטא\u0004 \u0005[פשוט]\u0006 \u0003לי\u0004 שהוא נמנה בין המזכים, ואולם \u0003אמר\u0004 ולא פירש את הזכות עדיין \u0003תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך,\u0004 שיש להסתפק האם ייחשב בין המזכים. ולא נפתרה איפוא השאלה.","שנינו במשנה ש\u0003אפילו\u0004 אם \u0003הוא,\u0004 הנאשם, אומר שיש לו ללמד על עצמו זכות מחזירים אותו ובלבד שיהא ממש בדבריו. ושואלים האם דרישה זו היא \u0003אפילו פעם ראשונה ושניה? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003פעם ראשונה ושניה\u0004 שטען שיש לו צד זכות, \u0003בין שיש ממש בדבריו בין שאין ממש בדבריו\u0004 — \u0003מחזירין אותו, מכאן ואילך, אם יש ממש בדבריו\u0004 — \u0003מחזירין אותו, אין ממש בדבריו\u0004 — \u0003אין מחזירין אותו,\u0004 ולכאורה הדבר סותר את משנתנו!","\u0003אמר רב פפא: תרגומה\u0004 \u0005[פרש\u0006 את \u0005המשנה\u0006\u0005]\u0006 \u0003מפעם שניה ואילך,\u0004 שמאז בודקים אם יש ממש בדבריו.","ושואלים: \u0003מנא ידעי\u0004 \u0005[מנין יודעים\u0006\u0005]\u0006 אם יש ממש בדבריו? \u0003אמר אביי: דמסרינן ליה זוגא דרבנן\u0004 \u0005[שמוסרים עמו זוג חכמים\u0006\u0005]\u0006 היכולים לדון בדבר, \u0003אי איכא\u0004 \u0005[אם יש]\u0006 \u0003ממש בדבריו\u0004 — \u0003אין\u0004 \u0005[כן\u0006\u0005],\u0006 \u0003אי\u0004 \u0005[אם\u0006\u0005]\u0006 \u0003לא\u0004 — \u0003לא.\u0004","ושואלים: \u0003ולימסר ליה מעיקרא\u0004 \u0005[ושימסרו לו מתחילה\u0006\u0005]\u0006 אפילו בפעם הראשונה זוג תלמידי חכמים לבדוק דבר זה! ומשיבים: \u0003אגב דבעית\u0004 \u0005[כיון ש\u0006הוא \u0005מבוהל\u0006\u0005]\u0006 \u0003לא מצי אמר\u0004 \u0005[אינו יכול לומר]\u0006 \u0003כל מאי דאית ליה\u0004 \u0005[מה שיש לו\u0006\u0005],\u0006 ושמא מחמת אימה התבלבל ולא אמר דבר של ממש. אבל אם חזר פעם ראשונה ושניה — אין מעכבים את הדבר עוד, אלא בודקים אותו במקומו.","\u0003מצאו לו זכות\u0004 לנאשם — \u0003פטרוהו. ואם לאו\u0004 \u0005[לא]\u0006 מצאו לו זכות — \u0003יצא ליסקל. וכרוז יוצא לפניו\u0004 ואומר: \u0003\"איש פלוני בן פלוני יוצא ליסקל על שעבר עבירה פלונית, ופלוני ופלוני עדיו, כל מי שיודע לו זכות יבא וילמד עליו\".\u0004","על האמור במשנה שהיו מכריזים \u0003אמר אביי: וצריך למימר\u0004 \u0005[לומר\u0006\u0005]\u0006 באותה הכרזה, שהיה הדבר \u0003ביום פלוני ובשעה פלונית ובמקום פלוני, דילמא איכא דידעי ואתו ומזים להו\u0004 \u0005[שמא יש שיודעים\u0006 שהנאשם או העדים לא היו שם באותה שעה \u0005ובאים ומזימים אותם\u0006\u0005].\u0006","שנינו במשנה ש\u0003כרוז יוצא לפניו.\u0004 ומדייקים: \u0003לפניו,\u0004 כלומר, בשעת הוצאה להורג — \u0003אין\u0004 \u0005[כן],\u0006 ואולם \u0003מעיקרא\u0004 \u0005[מתחילה]\u0006 לפני גמר דין — \u0003לא.\u0004 ומקשים: \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003בערב הפסח תלאוהו לישו הנוצרי, וכרוז יוצא לפניו ארבעים יום,\u0004 ומכריז: \u0003\"ישו הנוצרי יוצא ליסקל על שכישף והסית והדיח את ישראל, כל מי שיודע לו זכות יבוא וילמד עליו\". ולא מצאו לו זכות, ותלאוהו בערב הפסח.\u0004","\u0003אמר עולא: ותסברא\u0004 \u0005[וכי סבור אתה]\u0006 שיש להביא מכאן ראיה? וכי \u0003ישו הנוצרי בר הפוכי זכות הוא\u0004 \u0005[ראוי הוא להפוך בזכותו]?\u0006 והרי \u0003מסית הוא, ורחמנא אמר\u0004 \u0005[והתורה אמרה]\u0006 לגבי מסית \u0003\"\u0004ו\u0003לא תחמל ולא תכסה עליו\"\u0004 (דברים יג, ט)! \u0003אלא שאני ישו\u0004 ש\u0003קרוב למלכות הוה\u0004 \u0005[היה]\u0006","והיו השלטונות מעוניינים בזכותו, ולפיכך נתנו לו את כל האפשרויות, שלא יאמרו שהעלילו עליו לשווא. כיון שהוזכר ישו מביאים ברייתא אחרת בנושא דומה: \u0003תנו רבנן, חמשה תלמידים היו לו לישו: מתאי, נקאי, נצר, ובוני, ותודה. אתיוה למתי\u0004 \u0005[הביאוהו את מתאי]\u0006 ליהרג, \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003מתאי יהרג? הכתיב\u0004 \u0005[\u0006ו\u0005הרי נאמר]:\u0006 \u0003\"מתי אבוא ואראה פני אלהים\"\u0004 (תהלים מב, ג)! \u0003אמרו לו:\u0004 \u0003אין\u0004 \u0005[כן],\u0006 \u0003מתי יהרג, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"מתי ימות ואבד שמו\"\u0004 (תהלים מא, ו).","\u0003אתיוה\u0004 \u0005[הביאוהו]\u0006 את \u0003נקאי\u0004 ליהרג, \u0003אמר: נקאי יהרג? הכתיב\u0004 \u0005[\u0006ו\u0005הרי נאמר]:\u0006 \u0003\"ונקי וצדיק אל תהרג\"\u0004 (שמות כג, ז)! \u0003אמרו לו: אין\u0004 \u0005[כן],\u0006 \u0003נקאי יהרג,\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"במסתרים יהרג נקי\"\u0004 (תהלים י, ח).","\u0003אתיוה\u0004 \u0005[הביאוהו]\u0006 את \u0003נצר\u0004 ליהרג, \u0003אמר: נצר יהרג? הכתיב\u0004 \u0005[\u0006ו\u0005הרי נאמר]:\u0006 \u0003\"ונצר משרשיו יפרה\"\u0004 (ישעיה יא, א)! \u0003אמרו לו: אין\u0004 \u0005[כן],\u0006 \u0003נצר יהרג,\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואתה השלכת מקברך כנצר נתעב\"\u0004 (ישעיה יד, יט).","\u0003אתיוה\u0004 \u0005[הביאוהו]\u0006 את \u0003בוני\u0004 ליהרג, \u0003אמר\u0004 להם: \u0003בוני יהרג? הכתיב \"בני בכרי ישראל\"\u0004 (שמות ד, כב) \u0003אמרו לו: אין\u0004 \u0005[כן]\u0006 \u0003בוני יהרג, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"הנה אנכי הורג את בנך בכרך\"\u0004 (שמות ד, כג).","\u0003אתיוה\u0004 \u0005[הביאוהו]\u0006 את \u0003תודה,\u0004 ליהרג, \u0003אמר: תודה יהרג? הכתיב\u0004 \u0005[\u0006ו\u0005הרי נאמר]:\u0006 \u0003\"מזמור לתודה\"\u0004 (תהלים ק, א)! \u0003אמרו לו: אין\u0004 \u0005[כן],\u0006 \u0003תודה יהרג, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"זבח תודה יכבדנני\"\u0004 (תהלים נ, כג)."],["אגב הפסוק האחרון שנזכר, מביאים את מה ש\u0003אמר ר' יהושע בן לוי: כל הזובח את יצרו\u0004 לאחר שהסיתו לחטוא, ושב בתשובה, \u0003ומתודה עליו, מעלה עליו הכתוב כאילו כיבדו להקדוש ברוך הוא בשני עולמים, העולם הזה והעולם הבא, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"זבח תודה יכבדנני\"\u0004 (תהלים נ, כג) ושתי הנו\"ן מכוונים כנגד שני עולמות.","\u0003ו\u0004עוד \u0003אמר ר' יהושע בן לוי: בזמן שבית המקדש קיים\u0004 אם \u0003אדם מקריב עולה\u0004 — \u0003שכר עולה בידו,\u0004 אם מקריב \u0003מנחה\u0004 — \u0003שכר מנחה בידו,\u0004 ולא עוד. \u0003אבל מי שדעתו שפלה,\u0004 שהוא עניו בעיני עצמו, \u0003מעלה עליו הכתוב כאילו הקריב כל הקרבנות כולן, שנאמר: \"זבחי אלהים רוח נשברה\"\u0004 (תהלים נא, יט), \"זבחי\" לשון רבים. \u0003ולא עוד אלא שאין תפלתו נמאסת, שנאמר: \"לב נשבר ונדכה אלהים לא תבזה\"\u0004 (תהלים נא, יט).","\u0003היה\u0004 הנאשם \u0003רחוק מבית הסקילה כעשר אמות, אומרים לו: התודה\u0004 על פשעך, \u0003שכן דרך כל המומתין\u0004 שהם \u0003מתודין, שכל המתודה\u0004 ומתחרט \u0003יש לו חלק לעולם הבא. שכן מצינו בעכן שאמר לו יהושע: \"בני שים נא כבוד לה' אלהי ישראל ותן לו תודה\"\u0004 (יהושע ז, יט), כלומר, התוודה לפניו. ואכן מיד לאחר מכן נאמר: \u0003\"ויען עכן את יהושע ויאמר אמנה אנכי חטאתי וכזאת וכזאת\u0004 עשיתי\u0003\"\u0004 (יהושע ז, כ). \u0003ומנין שכיפר לו וידויו\u0004 לעכן — \u0003שנאמר: \"ויאמר יהושע מה עכרתנו יעכרך ה' ביום הזה\"\u0004 יהושע ז, כה), ויש לדייק משם: \u0003ביום הזה\u0004 שדנים אותך \u0003אתה עכור, ואי\u0004 (אין) \u0003אתה עכור לעולם הבא.\u0004","\u0003ואם אינו יודע להתוודות\u0004 מחמת בורותו או מחמת בלבול הדעת, \u0003אומרים לו: אמור\u0004 סתם: \u0003\"תהא מיתתי כפרה על כל עונותי\". ר' יהודה אומר: אם היה\u0004 הנאשם \u0003יודע שהוא מזומם,\u0004 כלומר, שעדים זוממים גרמו לו למות שלא כדין \u0003אומר: \"תהא מיתתי כפרה על כל עונותי חוץ מעון זה\".\u0004 \u0003אמרו לו: אם כן יהו כל אדם אומר כן כדי לנקות\u0004 את \u0003עצמו,\u0004 אלא מי שאינו אומר כן מעצמו אין מלמדים אותו לומר כך.","כיון שהוזכר חטאו של עכן מביאים כמה דרשות באותו ענין. \u0003תנו רבנן\u0004, יהושע אמר לו \"שים \u0003נא\u0004 כבוד\" (יהושע ז יט), ומסבירים: \u0003אין \"נא\" אלא לשון בקשה.\u0004","וטעם הדבר — \u0003בשעה שאמר הקדוש ברוך הוא ליהושע \"חטא ישראל\"\u0004 (יהושע ז יא), \u0003אמר לפניו\u0004 יהושע: \u0003רבונו של עולם, מי\u0004 הוא זה ש\u0003חטא? אמר ליה\u0004 \u0005[לו\u0006\u0005]:\u0006 \u0003וכי דילטור\u0004 (מלשין) \u0003אני? לך הפל גורלות\u0004 ותמצא. \u0003הלך והפיל גורלות ונפל הגורל על עכן. אמר לו\u0004 עכן: \u0003יהושע, בגורל אתה בא עלי?\u0004 וכי אפשר להביא ממנו ראיה? והרי \u0003אתה ואלעזר הכהן שני גדולי הדור אתם, אם אני מפיל עליכם גורל\u0004 בעל כרחכם \u0003על אחד מכם הוא נופל\u0004 ומה אתה מוכיח מן הגורל? \u0003אמר לו: בבקשה ממך אל תוציא לעז על הגורלות, ש\u0004כן \u0003עתידה ארץ ישראל שתתחלק בגורל, שנאמר: \"אך בגורל יחלק את הארץ\"\u0004 (במדבר כו, נה), ובגללך עלולים לערער על הגורל, ולכן \"שים נא\", בלשון בקשה,","\u0003\"\u0004ו\u0003תן\u0004 לו \u0003תודה\"\u0004 (יהושע ז, יט) \u0003אמר רבינא שחודי שחדיה במילי\u0004 \u0005[שיחד אותו בדברים\u0006\u0005],\u0006 שאמר: \u0003כלום נבקש ממך אלא הודאה\u0004 בלבד, \u0003תן לו תודה והיפטר. מיד \"ויען עכן את יהשע ויאמר אמנה אנכי חטאתי לה' אלהי ישראל וכזאת וכזאת עשיתי\u0004 (יהושע ז, כ).","על הלשון \"כזאת וכזאת\" \u0003אמר רב אסי אמר ר' חנינא:\u0004 \u0003מלמד שמעל עכן בשלשה חרמים, שנים בימי משה ואחד בימי יהושע, שנאמר: \"\u0004ו\u0003כזאת וכזאת עשיתי\",\u0004 הרי שעשה גם קודם פעמיים כחטא זה. \u0003ר' יוחנן אמר משום\u0004 (בשם) \u0003ר' אלעזר בר' שמעון:\u0004 ב\u0003חמשה\u0004 חרמים מעל, \u0003ארבעה\u0004 במלחמות שהיו \u0003בימי משה, ואחד בימי יהושע, שנאמר: \"אנכי חטאתי\u0004 לה' אלהי ישראל \u0003וכזאת וכזאת עשיתי\"\u0004 (הרי ארבעה שעבר מתחילה).","ושואלים: \u0003ועד השתא\u0004 \u0005[עכשיו]\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא איענוש\u0004 \u0005[נענשו\u0006 בשבילו\u0005]\u0006 כבפעם זו? \u0003אמר ר' יוחנן משום ר' אלעזר בר' שמעון: לפי שלא ענש\u0004 הקדוש ברוך הוא \u0003על הנסתרות,\u0004 שיענש אדם בחטא נסתר של חבירו, \u0003עד שעברו ישראל את הירדן.\u0004","ומעירים: ודבר זה הוא \u0003כתנאי\u0004 \u0005[כ\u0006מחלוקת \u0005תנאים\u0006\u0005]\u0006 שכבר נחלקו בכך. נאמר: \u0003\"הנסתרת לה' אלהינו והנגלת לנו ולבנינו עד עולם\u0004 לעשות את כל דברי התורה הזאת\u0003\"\u0004 (דברים כט, כח), וצריך להבין \u0003למה נקוד על \"לנו ולבנינו\" ועל עי\"ן שב\"עד\"?\u0004 — \u0003מלמד\u0004 הניקוד, שהוא כעין מחיקה, להחליש במקצת את הענין, \u0003שלא ענש ה' על הנסתרות עד שעברו ישראל את הירדן,\u0004 אלו \u0003דברי ר' יהודה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' נחמיה: וכי ענש על הנסתרות לעולם?\u0004 שאין זו משמעות הכתוב שיהו ישראל ערבים זה בזה לדברים שבסתר. \u0003והלא כבר נאמר\u0004 שם \u0003\"עד עולם\",\u0004 משמע שדבר זה לא ישתנה! \u0003אלא, כשם שלא ענש על הנסתרות, כך לא ענש על עונשין שבגלוי,\u0004 שלא יהא זה ערב לזה \u0003עד שעברו ישראל את הירדן,\u0004 שרק אז קיבלו על עצמם אחריות הדדית. ושואלים: אם כן שלעולם אין נענשים על הנסתרות, \u0003אלא\u0004"],["\u0003עכן מאי טעמא איענוש\u0004 \u0005[מה טעם נענש]?\u0006 ומשיבים: דבר זה לא היה מן הנסתרות, \u0003משום דהוו ידעי ביה\u0004 \u0005[שהיו יודעים בו]\u0006 \u0003אשתו ובניו.\u0004","נאמר שם: \u0003\"חטא ישראל\"\u0004 (יהושע ז, יא) \u0003אמר ר' אבא בר זבדא:\u0004 מכאן אפשר ללמוד ש\u0003אף על פי שחטא\u0004 — \u0003ישראל הוא. אמר ר' אבא: היינו דאמרי אינשי\u0004 \u0005[זהו שאומרים אנשים]\u0006 כפתגם עממי: \u0003\"אסא דקאי ביני חילפי, אסא שמיה, ואסא קרו ליה\"\u0004 \u0005[הדס הנמצא בין הקוצים, הדס שמו, והדס קוראים לו],\u0006 שאף אם הוא בחברה גרועה אין מהותו משתנה.","עוד נאמר שם: \u0003\"וגם עברו את בריתי אשר צויתי אותם וגם לקחו מן החרם וגם גנבו וגם כחשו וגם שמו בכליהם\"\u0004 (יהושע ז, יא). \u0003אמר ר' אילעא משום\u0004 (בשם) \u0003ר' יהודה בר מספרתא: מלמד שעבר עכן על חמשה חומשי תורה, שנאמר\u0004 בפסוק זה \u0003חמשה\u0004 פעמים מלת \u0003\"גם\".\u0004","\u0003ואמר ר' אילעא משום ר' יהודה בר מספרתא: עכן,\u0004 נוסף לשאר מעשיו הרעים, גם \u0003מושך בערלתו היה,\u0004 שנסה להסתיר את דבר היותו מהול, ורמז לדבר — \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 בענין עכן: \u0003\"וגם עברו את בריתי\", וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 בענין מילה: \u0003\"את בריתי הפר\"\u0004 (בראשית יז, יד).","ושואלים: אם כן \u0003פשיטא\u0004 \u0005[פשוט\u0006 הדבר\u0005]\u0006 שכך עשה, שהרי אמר ר' אילעא שעבר על כל התורה! ומשיבים, \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי \u0003במצוה גופיה\u0004 \u0005[שבגופו]\u0006 \u0003לא פקר\u0004 \u0005[הפקיר\u0006 עצמו\u0005]\u0006 עד כדי כך, על כן \u0003קא משמע לן\u0004 \u0005[השמיע\u0006","\u0005לנו]\u0006 שפקר כן. ועל מה שנאמר שם \u0003\"וכי עשה נבלה בישראל\"\u0004 (יהושע ז, טו), \u0003אמר ר' אבא בר זבדא: מלמד שבעל עכן נערה המאורסה,\u0004 ורמז לדבר — \u0003כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"וכי עשה נבלה\", וכתיב התם\u0004 \u0005[שם]\u0006 בנערה המאורסה שזינתה: \u0003\"כי עשתה נבלה בישראל\u0004 לזנות בית אביה","\u0003\"\u0004(דברים כב, כא). ושואלים: \u0003פשיטא\u0004 \u0005[פשוט\u0006 הדבר\u0005],\u0006 שהרי אמרנו שעבר על כל התורה! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי \u0003כולי האי\u0004 \u0005[כל כך]\u0006 \u0003לא פקר נפשיה\u0004 \u0005[הפקיר עצמו\u0006 בעבירה\u0005],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שלא חשש אף לזה. \u0003רבינא אמר:\u0004 מגזירה שווה זו אנו למדים לא לענין עבירתו, אלא ש\u0003דיניה\u0004 \u0005[דינו]\u0006 של עכן היה \u0003כנערה המאורסה\u0004 — שהוציאוהו למות \u0003בסקילה.\u0004","\u0003אמר ליה ריש גלותא\u0004 \u0005[לו ראש הגולה]\u0006 \u0003לרב הונא, כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ויקח יהושע את עכן בן זרח ואת הכסף ואת האדרת ואת לשון הזהב ואת בניו ואת בנתיו ואת שורו ואת חמרו ואת צאנו ואת אהלו ואת כל אשר לו\"\u0004 (יהושע ז, כד), ויש לתמוה: \u0003אם הוא חטא\u0004 — \u0003בניו ובנותיו מה חטאו,\u0004 ומדוע איפוא סקלום?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 שאתה מבין שענשו גם את משפחתו, \u0003אם הוא חטא\u0004 — \u0003כל ישראל מה חטאו?\u0004 והלא נאמר בסוף הפסוק \u0003\"וכל ישראל עמו\u0004 ויעלו אותם עמק עכור\u0003\"\u0004 (יהושע ז, כד)! \u0003אלא\u0004 יש לומר שהביאו את כל ישראל כדי \u0003לרדותן,\u0004 כלומר, להטיל עליהם אימה על ידי הסקילה, \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 הביאו את בני ביתו של עכן \u0003כדי לרדותן.\u0004","עוד נאמר שם בענין עונשו \u0003\"וישרפו אתם באש ויסקלו אתם באבנים\"\u0004 (יהושע ז, כה). ותוהים: \u0003בתרתי\u0004 \u0005[בשני\u0006 ענשים\u0005]\u0006 הענישו אותו? \u0003אמר רבינא: הראוי לשריפה,\u0004 כגון בגדים וכיוצא בהם הוציאו \u0003לשריפה,\u0004 ואת \u0003הראוי לסקילה\u0004 כגון בהמות הוציאו \u0003לסקילה.\u0004","על מה שנאמר שם \u0003\"וארא בשלל אדרת שנער אחת טובה ומאתים שקלים כסף\"\u0004 (יהושע ז, כא), \u0003רב אמר:\u0004 \"אדרת שנער\" זו היא \u0003איצטלא דמילתא\u0004 \u0005[מעיל של צמר\u0006 מובחר\u0005],\u0006 \u0003ושמואל אמר: סרבלא דצריפא\u0004 \u0005[בגד צבוע\u0006 בצבע \u0005צריף].\u0006","ועל מה שנאמר שם \u0003\"ויציקם לפני ה' \"\u0004(יהושע ז, כג), \u0003אמר רב נחמן: בא\u0004 יהושע \u0003וחבטם לפני המקום\u0004 (השם). \u0003אמר לפניו: רבונו של עולם, על\u0004 דברים קטנים \u0003אלו תיהרג רובה של סנהדרין?! דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ויכו מהם אנשי העי כשלשים וששה איש\"\u0004 (יהושע ז, ה), \u0003ותניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 \u0003שלשים וששה ממש\u0004 נהרגו, אלו \u0003דברי ר' יהודה. אמר לו ר' נחמיה: וכי שלשים וששה היו? והלא לא נאמר אלא כשלשים וששה איש,\u0004 ואין לשון זו נופלת במספר מדוייק! \u0003אלא\u0004 יש לפרש: \u0003זה יאיר בן מנשה\u0004 שנהרג, \u0003ששקול\u0004 בעצמו \u0003כנגד רובה של סנהדרין\u0004 (שהוא שלושים ושישה), ולכן נאמר בלשון זו, שכן יאיר בן מנשה שקול כשלושים ושישה.","\u0003אמר רב נחמן אמר רב: מאי דכתיב\u0004 \u0005[מהו שנאמר\u0006\u0005]:\u0006 \u0003\"תחנונים ידבר רש ועשיר יענה עזות\"\u0004 (משלי יח, כג), \u0003\"תחנונים ידבר רש\"\u0004 — \u0003זה משה\u0004 רבינו שדיבר לפני ה' בלשון תחנונים ופיוס, \u0003\"ועשיר יענה עזות\"\u0004 — \u0003זה יהושע\u0004 שדיבר קשה.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם\u0006\u0005],\u0006 כלומר, מהיכן למדים אנו דבר זה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום דכתיב\u0004 \u0005[שנאמר\u0006\u0005]\u0006 \u0003\"ויציקום לפני ה' \", ואמר רב נחמן\u0004 בביאור הדבר: \u0003בא וחבטן לפני המקום\u0004 מתוך טענתו — \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003פנחס לא עביד הכי\u0004 \u0005[עשה כן\u0006\u0005]?\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר]:\u0006 \u0003\"ויעמד פינחס ויפלל ותעצר המגפה\"\u0004 (תהלים קו, ל), \u0003ואמר ר' אלעזר: \"ויתפלל\" לא נאמר, אלא \"ויפלל\", מלמד שעשה פלילות\u0004 (משפט) \u0003עם קונו.\u0004 כיצד? \u0003בא וחבטן\u0004 את זמרי וכזבי \u0003לפני המקום, אמר לפניו: רבונו של עולם, על אלו יפלו עשרים וארבעה אלף מישראל? דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר]:\u0006 \u0003\"ויהיו המתים במגפה ארבעה ועשרים אלף\"\u0004 (במדבר כה, ט).","\u0003ואלא מהכא\u0004 \u0005[מכאן,\u0006 מפסוק זה \u0005]\u0006 נלמד שאמר יהושע בלשון קשה: \u0003\"למה העברת העביר את העם הזה את הירדן\"\u0004 (יהושע ז, ז), כמתלונן על מדות ה'. ואולם, \u0003משה נמי מימר אמר\u0004 \u0005[גם כן אמר\u0006\u0005]\u0006 כגון זה: \u0003\"למה הרעתה לעם הזה\u0004 למה זה שלחתני\u0003\"\u0004 (שמות ה, כב), \u0003אלא מהכא\u0004 \u0005[מכאן\u0006\u0005]\u0006 מהמשך המקרא נלמד הדבר: \u0003\"ולו הואלנו ונשב בעבר הירדן\"\u0004 (יהושע ז, ז).","את הנאמר \u0003\"ויאמר ה' אל יהושע קם לך\u0004 למה זה אתה נופל על פניך\u0003\"\u0004 (יהושע ז, י) \u0003דריש\u0004 \u0005[דרש\u0006\u0005]\u0006 \u0003ר' שילא, אמר ליה\u0004 \u0005[לו]\u0006 \u0003הקדוש ברוך הוא:\u0004 החטא \u0003שלך קשה משלהם,\u0004 שהרי \u0003אני אמרתי \"והיה בעברכם את הירדן תקימו\u0004 את האבנים האלה\u0003\"\u0004 (דברים כז, ד), \u0003ואתם\u0004 כבר \u0003ריחקתם ששים מיל\u0004 מן הירדן ולא קיימתם עדיין את המצוה.","\u0003בתר דנפק\u0004 \u0005[אחר שיצא\u0006\u0005]\u0006 ר' שילא וסיים את דרשתו, \u0003אוקים\u0004 \u0005[העמיד]\u0006 \u0003רב\u0004 שהיה באותו מקום ושתק \u0003אמורא עליה\u0004 \u0005[מתורגמן עליו,\u0006 לפניו\u0005]\u0006 \u0003ודרש\u0004 ברבים, נאמר: \u0003\"כאשר צוה ה' את משה עבדו כן צוה משה את יהושע וכן עשה יהושע לא הסיר דבר מכל אשר צוה ה' את משה\"\u0004 (יהושע יא, טו), ובוודאי עשה כדברי התורה,","\u0003אם כן מה תלמוד לומר \"קום לך\"\u0004 שמרמז שהדבר תלוי ביהושע — כך יש לפרשו: \u0003אמר ליה\u0004 \u0005[לו]\u0006 ה' ליהושע: \u0003אתה גרמת להם,\u0004 שלולא היית מקדיש (מחרים) את כל רכושה של יריחו לא היה קורה כל אותו מאורע. \u0003והיינו דקאמר ליה\u0004 \u0005[וזהו שאמר לו]\u0006 \u0003בעי:\u0004 \u0003\"ועשית לעי ולמלכה כאשר עשית ליריחו ולמלכה\u0004 רק שללה ובהמתה תבוזו לכם\u0003\"\u0004 (ח, ב).","נאמר: \u0003\"ויהי בהיות יהושע ביריחו וישא עיניו וירא\u0004 והנה איש עומד לנגדו וחרבו שלופה בידו וילך יהושע אליו ויאמר לו הלנו אתה אם לצרינו. \u0003ויאמר לא כי אני שר צבא ה' עתה באתי ויפל יהושע אל פניו ארצה וישתחו\"\u0004 (יהושע יא, ה,יג-יד). ותוהים: \u0003היכי עביד הכי\u0004 \u0005[כיצד עשה כך\u0006\u0005]\u0006 שהשתחוה, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן: אסור לו לאדם שיתן שלום לחבירו\u0004 שאינו מכיר אותו \u0003בלילה,\u0004 וטעם לדבר — \u0003חיישינן\u0004 \u0005[חוששים אנו\u0006\u0005]\u0006 \u0003שמא שד הוא,\u0004 ומדוע אם כן לא חשש יהושע?","ועונים: \u0003שאני התם דקאמר ליה\u0004 \u0005[שונה שם ש\u0006הרי \u0005אמר לו\u0006\u0005]\u0006 \u0003\"אני שר צבא ה' עתה באתי\"\u0004 ושואלים: \u0003ודילמא משקרי\u0004 \u0005[ושמא\u0006 שד הוא ו\u0005משקר\u0006\u0005]?\u0006 ומשיבים: \u0003גמירי דלא מפקי\u0004 \u0005[למודים\u0006 אנו במסורת \u0005שאין\u0006 השדים \u0005מוציאים\u0006\u0005]\u0006 \u0003שם שמים לבטלה,\u0004 וכיון שאמר שם שמים — בוודאי אמת אמר."],["\u0003אמר ליה\u0004 \u0005[לו]\u0006 המלאך: \u0003אמש ביטלתם תמיד של בין הערביים\u0004 מפני המלחמה, \u0003ועכשיו ביטלתם תלמוד תורה.\u0004 שאל אותו יהושע: \u0003על איזה מהן באת.\u0004 כלומר: מה היא העבירה שגרמה לכך? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003עתה באתי,\u0004 על העבירה האחרונה.","כיון שכך \u0003מיד \"וילן יהושע בלילה ההוא בתוך העמק\"\u0004 (יהושע ח, יג), \u0003ואמר ר' יוחנן: מלמד שלן בעומקה של הלכה\u0004 באותו לילה כדי לקיים מצות תלמוד תורה.","\u0003אמר שמואל בר אוניה משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: גדול תלמוד תורה יותר מהקרבת תמידין, שנאמר: \"עתה באתי\",\u0004 הרי שעבירה זו של ביטול תורה חמורה יותר מביטול הקרבת קרבן התמיד.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב דימי: האי קרא במערבא במאי מוקמיתו ליה\u0004 \u0005[מקרא זה בארץ ישראל במה,\u0006 כיצד \u0005אתם מסבירים אותו\u0006\u0005],\u0006 \u0003\"אל תצא לרב מהר פן מה תעשה באחריתה בהכלים אתך רעך. ריבך ריב את רעך וסוד אחר אל תגל\"?\u0004","(משלי כה ח–ט), כך מפרשים: \u0003בשעה שאמר לו הקדוש ברוך הוא ליחזקאל לך אמור להם לישראל \"אביך האמרי ואמך חתית\"\u0004 (יחזקאל טז, ג), \u0003אמרה רוח פסקונית\u0004 (הוא המלאך גבריאל) \u0003לפני הקדוש ברוך הוא: רבונו של עולם, אם יבואו אברהם ושרה\u0004 אבותיהם של ישראל \u0003ויעמדו לפניך, אתה אומר להם\u0004 כך \u0003ומכלים אותם?\u0004 והלא נאמר: \u0003\"ריבך ריב את רעך וסוד אחר אל תגל\".\u0004","ותוהים: \u0003ומי אית ליה רשותא כולי האי\u0004 \u0005[וכי יש לו\u0006 למלאך גבריאל \u0005רשות כל זאת\u0006 עד כדי כך \u0005]\u0006 להטיף מוסר להקדוש ברוך הוא? ומשיבים: \u0003אין\u0004 \u0005[כן\u0006\u0005],\u0006 וכפי ש\u0003אמר ר' יוסי בר' חנינא: שלש שמות יש לו\u0004 למלאך גבריאל: \u0003פיסקון, איטמון, סיגרון. פיסקון\u0004 הוא קרוי — משום שהוא \u0003פוסק דברים\u0004 בחריפות \u0003כלפי מעלה, איטמון\u0004 — \u0003שאוטם\u0004 (מכסה) \u0003עונותיהן של ישראל, סיגרון\u0004 — \u0003כיון שסוגר\u0004 (אוטם) את העוון \u0003שוב אינו פותח.\u0004","על מה שנאמר \u0003\"היערך שועך לא בצר\"\u0004 (איוב לו, יט), \u0003אמר ר' אלעזר: לעולם יקדים אדם תפלה לצרה, שאילמלא לא הקדים אברהם\u0004 אבינו \u0003תפלה לצרה\u0004 שהיתה \u0003בין בית אל ובין העי לא נשתייר משונאיהן של ישראל\u0004 (בלשון נקיה, כלומר, מעם ישראל) \u0003שריד ופליט,\u0004 שהיתה זו מפלה שאין אחריה לכאורה תקומה. \u0003ריש לקיש אמר:\u0004 פירושו של פסוק זה הוא כך: \u0003כל המאמץ עצמו בתפלה מלמטה\u0004 — \u0003אין לו צרים מלמעלה. ר' יוחנן אמר,\u0004 כך יש לומר: \u0003לעולם יבקש אדם רחמים שיהו הכל מאמצין את כחו, ואל יהו לו צרים מלמעלה.\u0004","שנינו במשנה: \u0003מנין שכיפר לו וידויו\u0004 לעכן וכו'. וכן \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]\u0006 \u0003מנין שכיפר לו וידויו\u0004 לעכן — מה \u0003שנאמר: \"ויאמר לו יהושע מה עכרתנו יעכרך ה' היום הזה\"\u0004 (יהושע ז, כה), מלמד: \u0003היום הזה אתה עכור, ואי\u0004 (אין) \u0003אתה עכור לעולם הבא. וכתיב\u0004 \u0005[ונאמר]\u0006 במקום אחר: \u0003\"ובני זרח זמרי ואיתן והימן וכלכל ודרדע כלם חמשה\"\u0004 (דברי הימים א' ב, ו), \u0003מאי\u0004 \u0005[מה\u0006\u0005]\u0006 בא ללמדנו \u0003\"כולם חמשה\"\u0004 — \u0003כולן חמשה הן לעולם הבא,\u0004 שלעולם הבא באים כולם.","\u0003כתיב\u0004 \u0005[נאמר\u0006\u0005]\u0006 \u0003\"זמרי\"\u0004 בין בני זרח בדברי הימים, \u0003וכתיב\u0004 \u0005[ונאמר\u0006\u0005]\u0006 \u0003\"עכן\",\u0004 ואין ברור מה היה שמו האמיתי, ונחלקו בכך \u0003רב ושמואל. חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: עכן\u0004 הוא \u0003שמו\u0004 האמיתי, \u0003ולמה נקרא שמו זמרי\u0004 — \u0003שעשה מעשה זמרי\u0004 שנאף עם המדינית. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: זמרי שמו\u0004 האמיתי, \u0003ולמה נקרא שמו עכן\u0004 — \u0003שעיכן\u0004 (נהג כנחש) ופקד \u0003עונותיהן של ישראל.\u0004","שנינו במשנה ש\u0003אם\u0004 היוצא ליהרג \u0003אינו יודע להתוודות\u0004 — מלמדים אותו, ו\u0003ר' יהודה אומר\u0004 שאדם שיודע שעדים זוממים גרמו לו למות אומר שתהא מיתתו כפרה על כל עוונותיו חוץ מעוון זה. ואמרו חכמים שאין עושים כן כדי שלא יבואו כל אדם \u0003לנקות\u0004 את \u0003עצמן.\u0004 ותוהים: \u0003וינקו עצמן,\u0004 ומה בכך שהנידון רוצה לומר שהוא חף מפשע?! ומשיבים: \u0003כדי שלא להוציא לעז\u0004 על ידי כך \u0003על בתי דינין ועל העדים.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006\u0005]:\u0006 \u0003מעשה באדם אחד שיצא ליהרג\u0004 על פי בית דין, \u0003אמר: אם יש בי עון זה\u0004 — \u0003לא תהא מיתתי כפרה לכל עונותי, ואם אין בי עון זה\u0004 שאני נידון עליו — \u0003תהא מיתתי כפרה לכל עונותי, ובית דין וכל ישראל מנוקין\u0004 מאשמה, \u0003והעדים לא תהא להם מחילה לעולם. וכששמעו חכמים בדבר אמרו: להחזירו אי אפשר, שכבר נגזרה גזירה. אלא יהרג ויהא קולר\u0004 (האשמה) \u0003תלוי בצואר עדים.\u0004","ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן שיהרג\u0005],\u0006 \u0003כל כמיניה\u0004 \u0005[וכי הכל ממנו,\u0006 הכל בכוחו\u0005]?\u0006 וכי משום שאמר שהוא חף מפשע מיד ישנו את דינו? ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 לומר שיהרג אלא במקרה זה \u0003דקא הדרי בהו סהדי\u0004 \u0005[שחזרו בהם העדים\u0006\u0005],\u0006 ואף על פי כן אמרו חכמים שיהרג.","ושואלים: \u0003וכי הדרי בהו מאי הוי\u0004 \u0005[וכאשר חוזרים בהם\u0006 העדים \u0005מה בכך\u0006\u0005]?\u0006 הרי ברור שיש להרגו, שהלא הכלל הוא \u0003כיון שהגיד\u0004 העד \u0003שוב אינו חוזר ומגיד\u0004 עדות אחרת, ואין לחזרתם איפוא כל תוקף! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה\u0006\u0005]\u0006 אלא \u0003דאף על גב דקא יהבי טעמא למילתייהו\u0004 \u0005[אף על פי שהם נותנים טעם לדבריהם\u0006\u0005]\u0006 ומסבירים מדוע שקרו, בכל אופן מוציאים אותו להריגה. \u0003כי ההוא מעשה דבעיא מיכסא\u0004 \u0005[כמו אותו מעשה בבעיא המוכס\u0006\u0005]\u0006 שנתגלגלו הדברים שהאשימו עדים זוממים את בנו של ר' שמעון בן שטח כנקמה על שדן אביו את קרובותיהם למוות.","\u0003היה\u0004 הנידון \u0003רחוק מבית הסקילה ארבע אמות, מפשיטין אותו את בגדיו. האיש מכסין אותו\u0004 משהו את ערוותו \u0003מלפניו, והאשה\u0004 מכסים אותה \u0003מלפניה ומאחריה,\u0004 אלו \u0003דברי ר' יהודה, וחכמים אומרים: האיש נסקל ערום, ואין האשה נסקלת ערומה,\u0004 אלא בבגדיה."],["שנינו במשנה שהאיש נסקל ערום ואין האשה נסקלת ערומה. ועוד בענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003האיש מכסין אותו\u0004 בזמן סקילתו \u0003פרק אחד\u0004 (חתיכה אחת) \u0003מלפניו, ואשה\u0004 מכסין אותה \u0003שני פרקים, בין מלפניה בין מלאחריה, מפני שכולה ערוה\u0004 ואסור להסתכל בה, אלו \u0003דברי ר' יהודה. וחכמים אומרים: האיש נסקל ערום ואין האשה נסקלת ערומה.\u0004","ושואלים: \u0003מאי טעמייהו דרבנן\u0004 \u0005[מה טעמם של חכמים\u0006\u0005]\u0006 שמחלקים בין איש ואשה? ומשיבים, \u0003אמר קרא\u0004 \u0005[הכתוב\u0006\u0005]:\u0006 \u0003\"ורגמו אתו\"\u0004 (ויקרא כד, יד), ודייק: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 ההדגשה \u0003\"אותו\"?\u0004","\u0003אילימא\u0004 \u0005[אם תאמר\u0006\u0005]\u0006 שבא הדבר ללמד שסוקלים רק \u0003אותו,\u0004 את האיש, \u0003ולא אותה,\u0004 את האשה, שאין אשה נסקלת. \u0003והכתיב\u0004 \u0005[והרי נאמר\u0006\u0005]\u0006 במפורש \u0003\"והוצאת את האיש ההוא או את האשה ההוא...\u0004 וסקלתם באבנים ומתו\u0003\"\u0004 (דברים יז, ה), \u0003אלא מאי\u0004 \u0005[מה]\u0006 מלמדת ההדגשה \"\u0003אותו\u0004\" — \u0003אותו\u0004 מוציאים לבדו, \u0003בלא כסותו. הא\u0004 \u0005[הרי\u0006\u0005]\u0006 \u0003אותה\u0004 — מוציאים \u0003בכסותה. ר' יהודה אומר: \"אתו\"\u0004 משמעו להדגיש — אותו עצמו, \u0003בלא כסותו,\u0004 אבל כמו בשאר עונשים שבתורה \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 דין ה\u0003איש,\u0004 \u0003ולא שנא\u0004 \u0005[ואינו שונה\u0006] דין ה\u0003אשה,\u0004 שדין אחד להם.","ושואלים: \u0003למימרא דרבנן חיישי להרהורא\u0004 \u0005[האם לומר\u0006 מכאן \u0005כי חכמים חוששים להרהור\u0006 עבירה\u0005]\u0006 של הרואים \u0003ור' יהודה לא חייש להרהורא\u0004 \u0005[איננו חושש להרהור\u0006 עבירה\u0005]?\u0006 ושניהם נהרגים מכוסים, אם כי באשה יש דין מיוחד כמבואר להלן. \u0003והא איפכא שמענא להו\u0004 \u0005[והרי היפך\u0006 הדברים \u0005שמענו אותם\u0006 אומרים\u0005]\u0006 במקום אחר. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 בדין הסוטה: \u0003הכהן אוחז בבגדיה\u0004 ומושכם, \u0003אם נקרעו\u0004 — \u0003נקרעו, ואם נפרמו\u0004 — \u0003נפרמו, עד שמגלה את לבה, וסותר את שערה\u0004 שהיה קלוע. \u0003ר' יהודה אומר: אם היה לבה נאה\u0004 — \u0003לא היה מגלהו, ואם היה שערה נאה\u0004 — \u0003לא היה סותרו.\u0004 משמע שר' יהודה הוא החושש שהרואים יגיעו לידי הרהור עבירה!","\u0003אמר רבה: התם היינו טעמא\u0004 \u0005[שם\u0006 בסוטה \u0005זהו הטעם\u0006\u0005]\u0006 — \u0003שמא תצא מבית דין זכאה\u0004 בדין, שיתברר שלא חטאה, \u0003ויתגרו בה\u0004 (יתגרה על ידה יצרם) של \u0003פירחי\u0004 (צעירי) \u0003כהונה. הכא הא מקטלא\u0004 \u0005[כאן הלא נהרגת\u0006 היא\u0005]\u0006 ואין מקום ליצר הרע. \u0003וכי תימא אתי לאיתגרויי באחרנייתא\u0004 \u0005[ואם תאמר יבואו להתגרות ב\u0006נשים \u0005אחרות\u0006\u0005]\u0006 מתוך ראייתם את זו? \u0003אמר רבה, גמירי\u0004 \u0005[למודים\u0006 אנו\u0005]:\u0006 \u0003אין יצר הרע שולט אלא במי שעיניו רואות,\u0004 וכיון שאין עיניו רואות אשה אחרת בעירומה — שוב אין הדבר מגרה.","\u0003אמר רבא:\u0004 וכי מדברי \u0003ר' יהודה\u0004 על דברי \u0003ר' יהודה קשיא\u0004 \u0005[קשה]\u0006 ויש סתירה בהם, ואילו \u0003דרבנן אדרבנן לא קשיא\u0004 \u0005[\u0006\u0005מ\u0006דברי \u0005חכמים על\u0006 דברי \u0005חכמים אינו קשה\u0006 ואין סתירה\u0005],\u0006 ומדוע מקשים דווקא מדברי ר' יהודה עצמו בשני המקומות? \u0003אלא\u0004 חייבים אנו ליישב גם את הקושי שבין דברי חכמים כאן ושם, \u0003אמר רבא:\u0004 מדברי \u0003ר' יהודה\u0004 על דברי \u0003ר' יהודה לא קשיא\u0004 \u0005[אינו קשה]\u0006 \u0003כדשנין\u0004 \u0005[כפי שתירצנו].\u0006","\u0003דרבנן אדרבנן נמי לא קשיא\u0004 \u0005[מדברי חכמים על דברי חכמים גם כן אינו קשה],\u0006 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ונוסרו כל הנשים ולא תעשינה כזמתכנה\"\u0004 (יחזקאל כג, מח), וכדי שתשמש דוגמה והזהרה לשאר הנשים מבזים את הסוטה ברבים, \u0003הכא\u0004 \u0005[כאן]\u0006 בדין מיתה \u0003אין לך ייסור גדול מזה,\u0004 מהמיתה עצמה, ואין צורך עוד לבזותה.","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003ליעביד\u0004 \u0005[שיעשו]\u0006 \u0003בה תרתי\u0004 \u0005[שתים],\u0006 גם ימיתוה וגם יבזוה — כבר \u0003אמר רב נחמן אמר רבה בר אבוה:\u0004 \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"ואהבת לרעך כמוך\"\u0004 (ויקרא יט, יח), ופירושו: בכל מקום ובכל זמן, וגם כאשר הוא נדון למיתה \u0003ברור לו מיתה יפה\u0004 ככל האפשר ולא תבזהו.","ושואלים: האם לפי הסבר זה \u0003לימא\u0004 \u0005[האם לומר]\u0006 שדברי \u0003רב נחמן\u0004 כמחלוקת \u0003תנאי\u0004 \u0005[תנאים]\u0006 \u0003היא?\u0004 ודוחים: \u0003לא, דכולי עלמא אית להו\u0004 \u0005[לדעת הכל יש להם,\u0006 מקבלים\u0005]\u0006 את דברי \u0003רב נחמן,\u0004 \u0003והכא בהא קמיפלגי\u0004 \u0005[וכאן בזה נחלקו],\u0006 מה נקרא בענייננו מיתה יפה יותר, \u0003מר סבר בזיוני דאיניש עדיפא ליה טפי מניחא דגופיה\u0004 \u0005[חכם זה,\u0006 חכמים, \u0005סברו\u0006 כי \u0005בזיונו של אדם עדיף לו יותר מנוחיות גופו],\u0006 ונוח לאשה שיארכו יסוריה רגע יותר בגלל הבגד, מאשר שתתבזה בעירומה. \u0003ומר סבר ניחא דגופיה\u0004 \u0005[וחכם זה,\u0006 ר' יהודה, \u0005סבור\u0006 כי \u0005נוחיות גופה]\u0006 \u0003עדיף\u0004 לה \u0003מבזיוני\u0004 \u0005[מבזיון].\u0006","\u0003בית הסקילה היה גובה שתי קומות\u0004 של אדם, ומעמידים בקצהו את הנידון. \u0003אחד מן העדים דוחפו\u0004 למטה \u0003על מתניו\u0004 (וגבו למעלה), אם \u0003נהפך על לבו\u0004 ופניו למעלה — היה העד \u0003הופכו על מתניו. ואם מת בה\u0004 בנפילה זו \u0003—\u0004 \u0003יצא\u0004 ידי חובת סקילה.","\u0003ואם לאו\u0004 \u0005[לא]\u0006 שעדיין לא מת — העד \u0003השני נוטל את האבן\u0004 המוכנה לסקילה \u0003ונותנו\u0004 בזריקה \u0003על לבו, אם מת בה\u0004 בזריקת אבן זו — \u0003יצא, ואם לאו\u0004 \u0005[לא]\u0006 מת אחרי שיד העדים היתה בו — תהא \u0003רגימתו בכל ישראל,\u0004 \u0003שנאמר:\u0004 \u0003\"יד העדים תהיה בו בראשונה להמיתו ויד כל העם באחרנה\"\u0004 (דברים יז, ז).","\u0003תנא\u0004 \u0005[\u0006בתוספתא \u0005שנינו\u0006\u0005]:\u0006 שתי קומות של בית הסקילה \u0003וקומה שלו\u0004 — \u0003הרי כאן שלש\u0004 קומות והוא גובה גדול למדי. ושואלים \u0003ומי בעינן כולי האי\u0004 \u0005[והאם צריכים אנו כל\u0006 גובה \u0005זה\u0006\u0005]\u0006 כדי להמית? \u0003ורמינהו\u0004 \u0005[מראים סתירה\u0006\u0005]\u0006 ממה ששנינו בדיני נזיקין: \u0003מה בור שהוא,\u0004 כלומר, שיש בשיעורו \u0003כדי להמית\u0004 — שהוא עמוק \u0003עשרה טפחים, אף כל כדי להמית\u0004 דיו בגובה \u0003עשרה טפחים.\u0004 וכאן עושים שתי קומות, בערך פי ארבע מעשרה טפחים!","\u0003אמר רב נחמן אמר רבה בר אבוה, אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ואהבת לרעך כמוך\"\u0004 (ויקרא יט, יח), וכוונתו — אף \u0003ברור לו מיתה יפה.\u0004 ולכן אפילו שאפשר שימות בפחות מזה, עושים את בית הסקילה גבוה כדי שתהא מיתתו קלה. ושואלים: \u0003אי הכי ליגבהיה טפי\u0004 \u0005[אם כך שיגביהנו\u0006 עוד \u0005יותר\u0006\u0005]!\u0006 ומשיבים: \u0003משום דמינול\u0004 \u0005[ש\u0006הוא \u0005מתנוול\u0006\u0005],\u0006 שאם יזרק מגובה רב יתפרקו איבריו ושוב אין זו מיתה יפה.","שנינו במשנה ש\u0003אחד מן העדים דוחפו.\u0004 ועוד בענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מניין ש\u0004דין סקילה מתקיים גם \u0003בדחייה\u0004 שזורקים אדם מלמעלה למטה? — \u0003תלמוד לומר\u0004 שנאמר בהר סיני בשעת מתן תורה \"השמרו לכם עלות בהר ונגע בקצהו כל הנגע בהר מות יומת. לא תגע בו יד כי סקול יסקל או \u0003ירה\u0004 יירה\" (שמות יט, יב–יג) ו\" יריה\" — לשון השלכה היא (כמו \"מרכבות פרעה וחילו ירה בים\". \u0005שמות טו, ד\u0006).","\u0003ומנין\u0004 \u0003ש\u0004מיתה זו היא \u0003בסקילה,\u0004 \u0003ו\u0004גם \u0003בדחיה\u0004 — \u0003תלמוד לומר: \"סקול\u0004 יסקל או ירה יירה\". \u0003ומנין שאם מת בדחייה יצא\u0004 ואין צורך גם לסוקלו — \u0003תלמוד לומר: \"או ירה יירה\",\u0004 משמע שאלו שתי אפשרויות, או זו או זו. ו\u0003מניין שאף לדורות כן\u0004 ולא רק במעמד הר סיני,"],["\u0003תלמוד לומר: \"סקול יסקל\",\u0004 והחזרה משמעה — בכל מקום בכל זמן.","שנינו במשנה ש\u0003אם לאו\u0004 \u0005[לא]\u0006 נהרג בדחיפה, \u0003עד השני נוטל את האבן.\u0004 שואלים: \u0003נוטל\u0004 בעצמו? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 ש\u0003ר' שמעון בן אלעזר אומר: אבן היתה שם\u0004 ומשקלה כדי \u0003משוי\u0004 (משא) \u0003שני בני אדם, נוטלה ונותנה על לבו, אם מת בה\u0004 — \u0003יצא.\u0004 משמע שאין אדם יחיד יכול לשאת אבן זו! ומשיבים: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך \u0005]\u0006 שאתה מקשה מכאן \u0003תיקשי\u0004 \u0005[תקשה]\u0006 \u0003לך היא\u0004 הברייתא \u0003גופא\u0004 \u0005[עצמה\u0006\u0005],\u0006 שנאמר בה שהיא כדי \u0003משוי שני בני אדם,\u0004 ונאמר מיד \u0003נוטלה ונותנה על לבו?\u0004 בלשון יחיד!","\u0003אלא\u0004 יש לפרש כך: \u0003דמדלי לה בהדי חבריה\u0004 \u0005[שמרים אותה יחד עם חבירו\u0006\u0005]\u0006 \u0003ושדי לה איהו כי היכי דתיתי מרזיא\u0004 \u0005[וזורק אותה הוא\u0006 לבדו \u0005כדי שתבוא בכוח\u0006\u0005],\u0006 כי שניים יחד לא יכלו לכוון זריקתם בדיוק.","עוד שנינו במשנה: \u0003ואם לאו\u0004 \u0005[לא],\u0006 שלא מת באבן — \u0003רגימתו\u0004 בכל אדם. ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מעולם לא שנה בה אדם,\u0004 שלא הוצרך איש לחזור ולהשליך אבן כדי להורגו, שכן די היה באבן הגדולה הראשונה! ומשיבים: \u0003מי קאמינא דעביד\u0004 \u0005[האם אמרנו שעשו\u0006 כן\u0005]?\u0006 אלא \u0003דאי מיצריך קאמינא\u0004 \u0005[שאם יצטרכו\u0006 לכך, \u0005אמרנו\u0006\u0005],\u0006 שאם לא נהרג בראשונה, כל העם ירגמו אותו.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 במשנה: \u0003\"אבן היתה\u0004 שם \u0003\",\u0004 משמע היתה אבן מיוחדת מתוקנת לכך, ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אחת אבן שנסקל בה, ואחת עץ שנתלה עליו, ואחד סייף שנהרג בו, ואחד סודר שנחנק בו\u0004 — \u0003כולן נקברין עמו,\u0004 ואם כן ודאי שאין זו אותה אבן! ומשיבים: אין הכוונה שהיו רוגמים באותה אבן ממש, אלא \u0003לא צריכא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 אלא \u0003דמתקני ומייתי אחריני חלופייהו\u0004 \u0005[שמתקנים ומביאים\u0006 אבנים \u0005אחרות במקומן\u0006\u0005].\u0006","שנינו בברייתא שאמצעים אלה שנהרג בהם \u0003נקברין עמו,\u0004 ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 אחרת האומרת: \u0003אין נקברין עמו! אמר רב פפא: מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"עמו\"\u0004 — אין נקברים אמצעי הריגתו עמו ממש בקברו, אלא \u0003עמו בתפיסתו\u0004 (במקום קרוב לו).","ועוד בענין זה \u0003אמר שמואל:\u0004 אם \u0003נקטעה יד העדים\u0004 לאחר גמר הדין ואינם יכולים לרגום אותו בעצמם — \u0003פטור,\u0004 ואינו נהרג. \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 — \u0003דבעינא\u0004 \u0005[שצריכים אנו\u0006\u0005]\u0006 לקיים את דברי הכתוב: \u0003\"יד העדים תהיה בו בראשנה\u0004 להמיתו\u0003\"\u0004 (דברים יז, ז), \u0003וליכא\u0004 \u0005[ואין כאן\u0006\u0005]\u0006 אפשרות לעשות זאת.","ומקשים: \u0003אלא מעתה\u0004 שצריך שיעשו זאת העדים עצמם ואחרת אינו נידון, אם היו \u0003עדים גידמין דמעיקרא\u0004 \u0005[מתחילה\u0006\u0005]\u0006 בשעת העדות \u0003הכי נמי דפסילי\u0004 \u0005[כך גם כן\u0006 תאמר \u0005ש\u0006הם \u0005פסולים\u0006\u0005]?!\u0006 ודוחים: \u0003שאני התם\u0004 \u0005[שונה שם\u0006\u0005]\u0006 ש\u0003אמר קרא\u0004 \u0005[הכתוב\u0006\u0005]\u0006 \u0003\"יד העדים\",\u0004 ומשמע: יד \u0003שהיתה כבר\u0004 בשעת העדות ועתה אינה, שנקטעה לאחר שהעידו. אבל אם כבר בשעה שהעידו לא היתה להם יד, אין מקום לקיים פסוק זה ככתוב, ומקיימים אותו באחרים.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006\u0005]\u0006 על כך ממה ששנינו: \u0003כל מקום שיעידוהו שנים ויאמרו: מעידין אנו באיש פלוני שנגמר דינו\u0004 למיתה \u0003בבית דין פלוני, ופלוני ופלוני\u0004 היו \u0003עדיו\u0004 — \u0003הרי זה יהרג,\u0004 ואין צורך לדונו מחדש. משמע שאין מחייבים שיד העדים הראשונים תהיה בו! \u0003תרגמא\u0004 \u0005[הסביר אותה\u0006\u0005]\u0006 \u0003שמואל\u0004 שבמקרה זה מדובר \u0003בהן הן עדיו,\u0004 שעדים אלה המעידים בו עכשיו הם העדים הראשונים שהעידו במשפטו, והם יכולים לקיים בו את פסק הדין.","לגופה של שיטת שמואל מקשים: \u0003ומי בעינן קרא כדכתיב\u0004 \u0005[והאם צריכים אנו\u0006 לקיים את \u0005המקרא כפי ש\u0006הוא \u0005כתוב\u0006\u0005]\u0006 בדיוק, ואין לנו רשות לשנות לפי התנאים? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 ממה שנאמר \u0003\"מות יומת המכה רצח הוא\"\u0004 (במדבר לה, כא), \u0003אין לי אלא\u0004 שממיתו \u0003במיתה הכתובה בו, מנין שאם אי\u0004 (אין) \u0003אתה יכול להמיתו במיתה הכתובה בו,\u0004 וכגון שהוא בורח, \u0003שאתה ממיתו בכל מיתה שאתה יכול להמיתו\u0004 — \u0003תלמוד לומר: \"מות יומת המכה\",\u0004 כוונתו: \u0003מכל מקום,\u0004 בכל מיתה.","ודוחים: \u0003שאני התם\u0004 \u0005[שונה שם\u0006\u0005]\u0006 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בפירוש \u0003\"מות יומת\"\u0004 — לרבות כל מיתה.","ושואלים: \u0003וליגמר מיניה\u0004 \u0005[ושילמדו מכאן\u0006\u0005]\u0006 לגבי שאר מיתות שבתורה! ודוחים: \u0003משום דהוה\u0004 \u0005[שהיה\u0006\u0005]\u0006 דין \u0003רוצח וגואל הדם שני כתובין הבאין כאחד,\u0004 שנאמרה בשניהם אותה הלכה עצמה, וכלל הוא ש\u0003כל שני כתובין הבאין כאחד\u0004 באותה הלכה \u0003אין מלמדין\u0004 להלכות אחרות, אלא רק לעניינן המיוחד.","\u0003רוצח\u0004 — \u0003הא דאמרן\u0004 \u0005[זה שאמרנו\u0006\u0005],\u0006 שהתיר הכתוב להמיתו בכל מיתה שהיא. \u0003גואל הדם מאי היא\u0004 \u0005[מה הוא\u0006\u0005]\u0006 — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 על הנאמר \u0003\"גאל הדם ימית את הרצח\u0004 בפגעו בו\u0003\"\u0004 (במדבר לה, כא): \u0003מצוה\u0004 זו של גאולת דם מרוצח בשגגה היא \u0003בגואל הדם,\u0004 קרובו של הנרצח. \u0003ומניין שאם אין לו\u0004 לנרצח \u0003גואל, שבית דין מעמידין לו גואל\u0004 — \u0003שנאמר: \"בפגעו בו\",\u0004 כוונתו לרבות: \u0003מכל מקום\u0004 יהא מי שימיתנו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003מר קשישא\u0004 \u0005[הזקן\u0006\u0005]\u0006 \u0003בריה\u0004 \u0005[בנו]\u0006 של \u0003רב חסדא לרב אשי:\u0004 \u0003ומי לא בעינן קרא כדכתיב\u0004 \u0005[והאם אין אנו צריכים\u0006 לקיים את \u0005המקרא כמו ש\u0006הוא \u0005כתוב\u0006\u0005]\u0006 בדיוק? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 בדין בן סורר ומורה, שאם \u0003היה אחד מהן\u0004 מהוריו \u0003גידם או אילם או חיגר או סומא או חרש\u0004 — \u0003אינו נעשה בן סורר ומורה.\u0004","\u0003שנאמר\u0004 שם: \"ותפשו בו אביו ואמו והוציאו אותו אל זקני עירו ואל שער מקומו\" (דברים כא, יט), \u0003\"ותפשו בו\"\u0004 — שהם עצמם יכולים לעשות זאת, \u0003ולא\u0004 שהם \u0003גידמין, \"והוציאו אתו\"\u0004 — \u0003ולא\u0004 שהם \u0003חיגרין,\u0004 ונאמר: \"ואמרו אל זקני עירו בננו זה סורר ומורה איננו שומע בקולנו זולל וסובא\" (דברים כא, כ). \u0003\"ואמרו\"\u0004 — \u0003ולא\u0004 שהם \u0003אילמין, \"בננו זה\"\u0004 — שיודעים להורות היכן הוא, משמע שהם \u0003לא סומין, \"איננו שמע בקלנו\"\u0004 — \u0003ולא\u0004 שהם \u0003חרשין.\u0004","\u0003מאי טעמא\u0004 \u0005[מה טעם\u0006\u0005]\u0006 הדבר? \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דבעינן קרא כדכתיב\u0004 \u0005[שאנו צריכים\u0006 לקיים את \u0005המקרא כפי ש\u0006הוא \u0005כתוב\u0006\u0005]\u0006 כדיוקו? ודוחים: \u0003לא, שאני התם\u0004 \u0005[שונה שם\u0006\u0005]\u0006 \u0003דכוליה קרא יתירא\u0004 \u0005[שכל\u0006 אותו \u0005המקרא מיותר]\u0006 \u0003הוא\u0004 לגוף הדברים, ולכן למדים אנו שהוא בא כדי להדגיש שיש לקיימו כצורתו, אבל אין זה כלל לכל התורה.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע\u0006\u0005]\u0006 ראיה לדבר ממה ששנינו בענין עיר הנדחת: ואם \u0003אין לה רחוב\u0004 (כאמור שם \"ואת כל שללה תקבוץ אל תוך רחובה\". דברים יג, יז), \u0003אין\u0004 היא \u0003נעשית עיר הנדחת,\u0004 אלו \u0003דברי ר' ישמעאל. ר' עקיבא אומר:\u0004 אם \u0003אין לה רחוב\u0004 — \u0003עושין לה רחוב.\u0004","ומעתה, \u0003עד כאן לא\u0004 שמענו כי \u0003פליגי\u0004 \u0005[נחלקו\u0006\u0005]\u0006 \u0003אלא\u0004 בפרט זה \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 ר' ישמעאל \u0005סבור]\u0006 כי \u0003רחובה\u0004 של העיר במקרא זה כוונתו \u0003דמעיקרא בעינן\u0004 \u0005[\u0006שהיה \u0005מתחילה, אנו צריכים\u0006\u0005],\u0006 \u0003ומר סבר\u0004 \u0005[וחכם\u0006 זה, ר' עקיבא \u0005סבור]\u0006 כי \u0003רחובה דהשתא נמי כדמעיקרא דמי\u0004 \u0005[של עכשיו גם כן כאילו מתחילה נחשב\u0006\u0005],\u0006 \u0003אבל דכולי עלמא בעינן קרא כדכתיב\u0004 \u0005[אבל לדעת הכל צריכים\u0006 לקיים את \u0005המקרא כפי ש\u0006הוא \u0005כתוב\u0006\u0005],\u0006 ולכאורה יש הוכחה מכאן שיש לקיים את המקרא כדיוקו!","ומשיבים: \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 בשאלה זו. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 בענין טהרת המצורע, שאמרה התורה שבשעת טהרתו יתנו דם ושמן על בוהן ידו, בוהן רגלו, ואזנו הימנית. ואם \u0003אין לו בהן יד\u0004 או \u0003בהן רגל\u0004 או \u0003אזן ימנית\u0004 — \u0003אין לו טהרה עולמית\u0004 (לעולם), שהרי אי אפשר לקיים את המקרא כפי שהוא כתוב, \u0003ר' אליעזר אומר: נותן\u0004 את הדם והשמן שצריך להזותם \u0003על מקומו\u0004 על מקום שהיתה בו הבוהן \u0003ויוצא, ר' שמעון אומר: נותן על שמאלו ויוצא.\u0004 הרי שהתנא הראשון סבור שיש לקיים את המקרא כפי שנכתב, ותנאים אחרים, ר' אליעזר ור' שמעון חולקים על כך, ואם כן אין הכל מודים שיש למלא אחר המקרא כלשונו.","\u0003כל הנסקלין נתלין\u0004 אחר מיתתם, אלו \u0003דברי ר' אליעזר. וחכמים אומרים: אינו נתלה אלא המגדף\u0004 (מקלל את ה') \u0003והעובד עבודה זרה.\u0004","ועוד: \u0003האיש תולין אותו\u0004 כש\u0003פניו כלפי העם, והאשה\u0004 מפני צניעות \u0003פניה כלפי העץ,\u0004 אלו \u0003דברי ר' אליעזר, וחכמים אומרים: האיש נתלה ואין האשה נתלית. אמר להן ר' אליעזר\u0004 לחכמים: \u0003והלא שמעון בן שטח תלה נשים באשקלון,\u0004 והרי שגם האשה נתלית! \u0003אמרו לו:\u0004 מכאן אין ראיה, שהלא \u0003שמונים נשים תלה\u0004 באותו יום, \u0003ו\u0004כלל הוא ש\u0003אין דנין שנים ביום אחד.\u0004 ואם כן ברור שלא לפי דין תורה נהג אז אלא תקנה מיוחדת היתה ואין להביא משם ראיה.","שנינו במשנה שכל הנסקלים נתלים אחר מיתתם. ועוד בענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]\u0006 על הכתוב \"וכי יהיה באיש חטא משפט מוות \u0003והומת ותלית\u0004 אותו על עץ\" (דברים כא, כב): \u0003יכול כל המומתין נתלין\u0004 — \u0003תלמוד לומר: \"\u0004לא תלין נבלתו על העץ... \u0003כי קללת אלהים תלוי\"\u0004 (דברים כא, כג) \u0003מה מקלל\u0004 (את ה') \u0003זה\u0004 שדינו \u0003בסקילה, אף כל\u0004 שנידונים \u0003בסקילה\u0004 — דווקא הם נתלים, אלו \u0003דברי ר' אליעזר.\u0004","\u0003וחכמים אומרים: מה מקלל\u0004 — \u0003זה שכפר בעיקר, אף כל שכפר בעיקר.\u0004","ושואלים: \u0003במאי קא מיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון \u0005הם חלוקים\u0006\u0005]?\u0006 ומסבירים: \u0003רבנן דרשי\u0004 \u0005[חכמים דורשים]\u0006 ולומדים דין זה של תליה במידת \u0003כללי ופרטי\u0004 \u0005[כללים ופרטים]\u0006 שהיא אחת מן המידות שהתורה נדרשת ונלמדת בהן. \u0003ור' אליעזר דריש\u0004 \u0005[דורש]\u0006 בדרך לימוד של \u0003ריבויי ומיעוטי\u0004 \u0005[ריבויים ומיעוטים\u0006\u0005],\u0006 שאף היא אחת מן המידות שבהן דורשים את התורה. כיצד?","\u0003רבנן דרשי כללי ופרטי\u0004 \u0005[חכמים דורשים\u0006 בדרך של \u0005כללים ופרטים]\u0006 כך: מה שנאמר \u0003\"והומת ותלית\"\u0004 — הרי זה \u0003כלל, \"כי קללת\"\u0004 — \u0003פרט, אי הוו מקרבי להדדי\u0004 \u0005[אילו היו\u0006 אלה \u0005קרובים זה לזה]\u0006 בפסוק אחד \u0003אמרינן\u0004 \u0005[היינו אומרים]\u0006 לפי אחת המדות (מדת \"כלל ופרט\") ש\u0003אין בכלל אלא מה שבפרט.\u0004 והיינו אומרים: \u0003הני\u0004 \u0005[אלה]\u0006 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003מידי אחרינא\u0004 \u0005[דבר אחר]\u0006 — \u0003לא,\u0004 והיינו קובעים שרק מי שקילל את ה' דינו בתליה,"],["\u0003השתא דמרחקי מהדדי\u0004 \u0005[עכשיו ש\u0006הם \u0005מרוחקים זה מזה\u0006\u0005],\u0006 \u0003אהני לרבויי\u0004 \u0005[הועיל\u0006 הדבר כדי \u0005לרבות]\u0006 ב\u0003עבודה זרה דדמי ליה\u0004 \u0005[שדומה לו,\u0006 למקלל\u0005]\u0006 \u0003בכל מילי\u0004 \u0005[הדברים\u0006\u0005],\u0006","\u0003ר' אליעזר דריש ריבויי ומיעוטי\u0004 \u0005[דורש\u0006 בדרך של \u0005ריבויים ומיעוטים],\u0006 \u0003\"והומת ותלית\"\u0004 — \u0003רבוי\u0004 הוא, \u0003\"כי קללת\"\u0004 — \u0003מיעוט. אי הוו מקרבי להדדי\u0004 \u0005[אם היו קרובים זה לזה]\u0006 \u0003לא הוו מרבינן\u0004 \u0005[היינו מרבים\u0006\u0005]\u0006 על ידי כך \u0003אלא עבודה זרה דדמי\u0004 \u0005[שדומה]\u0006 \u0003לה,\u0004 לקללה \u0003בכל מילי\u0004 \u0005[הדברים\u0006\u0005],\u0006 \u0003השתא דמרחקי מהדדי אהני לרבויי\u0004 \u0005[עכשיו שרחוקות זו מזו הועיל\u0006 הריבוי \u0005לרבות\u0006\u0005]\u0006 \u0003שאר הנסקלין.\u0004","שנינו במשנה שאת \u0003האיש תולין\u0004 באופן אחד ואת האשה בדרך אחרת, כדברי ר' אליעזר, וחכמים אומרים שאין תולים אשה כלל. ושואלים \u0003מאי טעמא דרבנן\u0004 \u0005[מה הטעם של חכמים\u0006\u0005]?\u0006 ומשיבים, שכן \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"וכי יהיה באיש חטא משפט מות והומת \u0003ותלית אתו\u0004 על עץ\" (דברים כא, כב), להדגיש: \u0003אותו,\u0004 את האיש, תולים, \u0003ולא אותה.\u0004 \u0003ור' אליעזר\u0004 אומר: כך יש לדייק \u0003אותו\u0004 תולין בעצמו \u0003בלא כסותו,\u0004 ולא אותה ללא כסותה.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה עונים הם לטענה זו? ומשיבים: \u0003אין הכי נמי\u0004 \u0005[כן, כך\u0006 הוא \u0005גם כן\u0006\u0005],\u0006 \u0003אלא\u0004 מקור דרשתם הוא ממה ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"וכי יהיה באיש חטא\"\u0004 (דברים כא, כב) — \u0003איש ולא אשה.\u0004","ושואלים: \u0003ור' אליעזר האי\u0004 \u0005[זה\u0006 הכתוב\u0005]\u0006 \u0003\"וכי יהיה באיש\" מאי דריש ביה\u0004 \u0005[מה דורש\u0006 הוא \u0005בו\u0006\u0005]?\u0006 \u0003אמר ריש לקיש:\u0004 הכתוב \u0003ההוא\u0004 בא \u0003למעוטי\u0004 \u0005[למעט\u0006\u0005]\u0006 \u0003בן סורר ומורה,\u0004 שלדעת ר' אליעזר אינו נתלה. ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 במפורש: \u0003בן סורר ומורה נסקל ונתלה,\u0004 אלו \u0003דברי ר' אליעזר. אלא אמר רב נחמן בר יצחק: לרבות בן סורר ומורה\u0004 שאף הוא נתלה. \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 — ש","\u0003אמר קרא\u0004 \u0005[הכתוב\u0006\u0005]\u0006 בענין חובת התלייה: \u0003\"וכי יהיה באיש חטא\",\u0004 ומשמע ב\u0003איש\u0004 דווקא \u0003ולא בן\u0004 — למעט מכאן בן סורר ומורה, ועוד נאמר בו \u0003\"חטא\"\u0004 לומר: \u0003מי שעל חטאו נהרג, יצא בן סורר ומורה שעל שום\u0004 (דברים כא, כב) \u0003סופו נהרג,\u0004 שהרי אינו נענש משום חטאים שעשה, שהרי אין בהם בעצמם כדי לחייב מיתה. ואם כן \u0003הוי\u0004 \u0005[הריהו\u0006\u0005]\u0006 \u0003מיעוט אחר מיעוט\u0004 שממעט הכתוב פעמיים אותו דין, \u0003ו\u0004כלל הוא: \u0003אין מיעוט אחר מיעוט אלא לרבות.\u0004 ועל כן מרבים אנו גם בן סורר ומורה לתליה.","עוד שנינו במשנה ש\u0003אמר להן ר' אליעזר\u0004 לחכמים: \u0003והלא שמעון בן שטח תלה נשים\u0004 באשקלון. ואמרו חכמים שמשם אין להוכיח, שהרי תלה שמונים ביום אחד, ומכאן שהיתה זו הוראת שעה וממנה אין ללמוד איפוא לעיקר הדין. \u0003אמר רב חסדא: לא שנו\u0004 שאין דנים שנים ביום אחד \u0003אלא בשתי מיתות\u0004 שונות, \u0003אבל במיתה אחת\u0004 — \u0003דנין.\u0004 ומקשים: \u0003והא\u0004 \u0005[והרי\u0006\u0005]\u0006 \u0003מעשה\u0004 זה של \u0003שמעון בן שטח\u0004 ש\u0003מיתה אחת הואי\u0004 \u0005[היתה\u0006\u0005]\u0006 \u0003וקא אמרו ליה\u0004 \u0005[ואמרו לו\u0006\u0005]\u0006 חכמים ש\u0003אין דנין!\u0004","\u0003אלא אי איתמר, הכי איתמר\u0004 \u0005[אם נאמר\u0006 בשם רב חסדא, \u0005כך נאמר]:\u0006 \u0003לא שנו אלא במיתה אחת\u0004 שהיא \u0003כעין שתי מיתות, והיכי דמי\u0004 \u0005[וכיצד הוא\u0006 בדיוק\u0005]\u0006 — \u0003כגון\u0004 שדן במיתה אחת על \u0003שתי עבירות\u0004 שונות שיש להן אותו עונש, \u0003אבל במיתה אחת ועבירה אחת\u0004 — \u0003דנין.\u0004","\u0003מתיב\u0004 \u0005[מקשה\u0006\u0005]\u0006 \u0003רב אדא בר אהבה\u0004 ממה ששנינו: \u0003אין דנין שנים ביום אחד ואפילו בנואף ונואפת,\u0004 משמע שאף את הנידונים על עבירה אחת אין דנים יחד! \u0003תרגמא\u0004 \u0005[הסביר אותה\u0006\u0005]\u0006 \u0003רב חסדא\u0004 לשיטתו, שמדובר כאן \u0003בבת כהן\u0004 שזנתה \u0003ובועלה,\u0004 שכיון שבת כהן דינה בשריפה, והבועל אותה דינו בסקילה או בחנק,","\u0003או בבת כהן\u0004 \u0003וזוממי זוממיה,\u0004 שהעידו עדים שזנתה וחייבוה איפוא שריפה ואת בועלה חנק, ולאחר מכן באו אחרים והזימום, וממילא נתחייבו הראשונים חנק כאשר זממו לעשות לאיש (ולא לאשה, שגזירת הכתוב היא \"כאשר זמם לעשות לאחיו\" — ולא לאחותו). ושוב באו עדים אחרים והזימו את המזימים ובכך החזירו למעשה את הדין שנגזר עליה בתחילה על פי עדות הראשונים, ונידונת בשריפה, ודין הזוממים הראשונים בחנק כפי שרצו לחייב את הראשונים.","\u0003תניא\u0004 \u0005[שנוייה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר בן יעקב אומר: שמעתי שבית דין מכין ועונשין שלא מן התורה,\u0004 כלומר, על עבירות ובעונשים שאינם כתובים בתורה, \u0003ולא לעבור על דברי תורה, אלא\u0004 ניתנה להם רשות \u0003כדי לעשות סייג לתורה.\u0004","\u0003ומעשה באחד שרכב על סוס בשבת בימי יונים והביאוהו לבית דין וסקלוהו. לא מפני שראוי לכך,\u0004 שהרי הרוכב על סוס אינו עובר אלא משום שבות, \u0003אלא שהשעה צריכה לכך\u0004 שהיו מזלזלים בשבת והרגוהו כדי לגדור את העם מלחלל שבת. \u0003שוב מעשה באדם אחד שהטיח\u0004 (בעל) \u0003את אשתו תחת התאנה\u0004 (בחוץ, ולא בביתו) \u0003והביאוהו לבית דין והלקוהו, לא מפני שראוי לכך,\u0004 שאין הדבר אסור מן התורה, \u0003אלא שהשעה צריכה לכך,\u0004 שהיו ישראל מזלזלים אז בגדרי צניעות.","\u0003כיצד תולין אותו\u0004 לאחר שנסקל? — \u0003משקעין את הקורה\u0004 מקצתה \u0003בארץ, והעץ יוצא\u0004 מעט מן הקורה, \u0003ומקיף\u0004 (מצרף) את \u0003שתי ידיו\u0004 של הנהרג \u0003זו על גב זו ותולה אותו, ר' יוסי אומר: הקורה מוטה\u0004 באלכסון \u0003על הכותל, ותולה אותו\u0004 עליה \u0003כדרך שהטבחין עושין\u0004 בבשר.","\u0003ומתירין אותו מיד,\u0004 כלומר, התליה היא רק לרגע אחד. \u0003ואם לן\u0004 בתלייתו — \u0003עובר עליו ב\"לא תעשה\", שנאמר: \"לא תלין נבלתו על העץ כי קבור תקברנו\u0004 ביום ההוא \u0003כי קללת אלהים תלוי\"\u0004 (דברים כא, כג), וכך מבארים: \u0003כלומר, מפני מה זה תלוי\u0004 — \u0003מפני שבירך\u0004 (קלל) \u0003את השם, ונמצא שם שמים מתחלל\u0004 אם נשאר אותו אדם תלוי, והכל מזכירים שאדם זה קילל את השם.","\u0003אמר ר' מאיר:\u0004 \"כי קללת אלהים תלוי\" יש לפרשו: \u0003בשעה שאדם מצטער, שכינה מה לשון אומרת?\u0004 — \u0003קלני\u0004 (מצטער אני) על \u0003ראשי, קלני\u0004 על \u0003זרועי.\u0004 ומכאן נלמד: \u0003אם כן\u0004 (כך) \u0003המקום\u0004 (הקדוש ברוך הוא) \u0003מצטער על דמן של רשעים שנשפך\u0004 אף שבחטאם נשפך, \u0003קל וחומר על דמן של צדיקים.\u0004","\u0003ולא זו בלבד אמרו\u0004 שצריך לקברו בו ביום \u0003אלא כל המלין את מתו\u0004 ולא קברו ביומו \u0003עובר ב\"לא תעשה\"\u0004 זה. אבל אם \u0003הלינהו לכבודו\u0004 של המת, או \u0003להביא לו ארון ותכריכים\u0004 — \u0003אינו עובר עליו\u0004 בלאו של \"לא תלין\".","אחר שהורד מעץ התלייה מביאים אותו לקבורה. \u0003ולא היו קוברין אותו\u0004 את הנידון למוות \u0003בקברות אבותיו, אלא שתי בתי קברות היו מתוקנים ל\u0004קבורת הרוגי \u0003בית דין, אחת לנהרגין ולנחנקין, ואחת לנסקלין ולנשרפין.\u0004 לאחר ש\u0003נתעכל\u0004 (נרקב) \u0003הבשר\u0004 של מת זה היו \u0003מלקטין את העצמות וקוברין אותן במקומן,\u0004 בתוך קברי המשפחה. ולאחר המיתה \u0003הקרובים באים ושואלים בשלום הדיינין ובשלום העדים, כלומר,\u0004 כאילו באים הם לומר \u0003שאין בלבנו עליכם שדין אמת דנתם.\u0004"],["\u0003ולא היו מתאבלין\u0004 (נוהגים מנהגי אבילות) על קרוביהם שנהרגו, כדי שתהא מיתתם כפרה להם, \u0003אבל\u0004 רשאים להיות \u0003אוננין\u0004 (מצטערים) עליהם, כיון \u0003שאין אנינות אלא בלב.\u0004","לצורך ביאור דין המשנה העוסקת בתלוי מביאים את מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003אילו נאמר\u0004 בכתוב הלשון \u0003\"חטא ותלית\" הייתי אומר\u0004 כי \u0003תולין אותו ואחר כך ממיתין אותו, כדרך שהמלכות עושה\u0004 שתולה אדם קודם להמתתו, \u0003תלמוד לומר:\u0004 \"וכי יהיה באיש חטא משפט מות \u0003והומת ותלית\u0004 אותו על עץ\" (דברים כא, כב), כלומר, \u0003ממיתין אותו ואחר כך תולין אותו. הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 עושים? \u0003משהין אותו עד סמוך לשקיעת החמה, וגומרין את דינו, וממיתין אותו\u0004 כדינו, \u0003ואחר כך תולין אותו. אחד קושר\u0004 אותו לעץ \u0003ואחד מתיר\u0004 מיד, \u0003כדי לקיים מצות תלייה.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 ממה שנאמר \"ותלית אותו על \u0003עץ\u0004\" \u0003שומע אני בין\u0004 בעץ \u0003תלוש, בין\u0004 בעץ \u0003מחובר\u0004 לקרקע, \u0003תלמוד לומר:\u0004 \"לא תלין נבלתו על העץ \u0003כי קבור\u0004 תקברנו ביום ההוא\" (דברים כא, כג), כוונתו: על עץ \u0003שאינו מחוסר אלא קבורה, יצא זה\u0004 העץ המחובר \u0003שמחוסר קציצה וקבורה.\u0004","\u0003ר' יוסי אומר: מי שאינו מחוסר אלא קבורה, יצא זה שמחוסר תלישה וקבורה,\u0004 שלדעתו אף אין משקעים את העץ בקרקע אלא יש רק להשעינו על הקיר. \u0003ורבנן\u0004 \u0005[וחכמים\u0006\u0005]\u0006 אומרים: \u0003תלישה לאו\u0004 \u0005[לא]\u0006 \u0003כלום היא\u0004 ואינה נחשבת. וחוסר הרמז לתלישה אינו סימן שאין משקעים את העץ בקרקע.","שנינו במשנה: \u0003כלומר, מפני מה זה תלוי\u0004 — \u0003מפני שבירך\u0004 (קילל) את ה'. \u0003תניא\u0004 \u0005[שנויה\u0006 תוספתא\u0005],\u0006 \u0003אומר ר' מאיר: משלו משל למה הדבר דומה, לשני אחים תאומים\u0004 שהיו \u0003בעיר אחת, אחד מינוהו מלך ואחד יצא לליסטיות\u0004 (להיות שודד). \u0003צוה המלך ותלאוהו\u0004 על עוונותיו. \u0003כל הרואה אותו אומר: המלך תלוי. צוה המלך והורידוהו.\u0004 וכן לביאור המצוה בתורה, כיון שהאדם נברא בצלם אלוהים, בזיון הוא לה' כשהאדם תלוי.","שנינו במשנה, \u0003אמר ר' מאיר:\u0004 שכינה אומרת \"קלני מראשי קלני מזרועי\". המלה \"קלני\" לא היתה מובנת, ושאלו: \u0003מאי משמע\u0004 \u0005[מה משמעות\u0006 ופירוש הביטוי\u0005]?\u0006 \u0003אמר אביי, כמאן דאמר\u0004 \u0005[כ\u0006דעת \u0005מי שאומר]:\u0006 \u0003קל לית\u0004 \u0005[אין,\u0006 אין אני קל\u0005],\u0006 כלומר, כבד עלי ראשי, כבדה עלי זרועי כשצריך לעשות דבר מעין זה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: אם כן, \"כבד עלי ראשי\", \"כבד עלי זרועי\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר במפורש\u0005]!\u0006 \u0003אלא אמר רבא\u0004 הרי זה \u0003כמאן דאמר\u0004 \u0005[כמי שאומר]:\u0006 \u0003קיל לי עלמא\u0004 \u0005[קל עלי העולם\u0006\u0005],\u0006 שאומר בלשון נקיה \"קל אני\" במקום לומר כבד, אף שהיא אותה משמעות.","על עצם דברי ר' מאיר מקשים: \u0003האי\u0004 \u0005[\u0006המלה \u0005הזו,\u0006 \"קללת\"\u0005]\u0006 \u0003מיבעי ליה\u0004 \u0005[נצרכה לו]\u0006 \u0003לגופה\u0004 לענין ההלכה שמקלל ה' נידון בתליה, וכיצד דורש אותה לענין זה? ומשיבים: אילו היתה לגופה בלבד, \u0003אם כן, נימא קרא\u0004 \u0005[שיאמר הכתוב\u0006\u0005]\u0006 \u0003\"מקלל\", מאי\u0004 \u0005[מהו]\u0006 הלשון \u0003\"קללת\"\u0004 — בא ללמד כמדרשו של ר' מאיר. \u0003ו\u0004שואלים: אם כן, שאין המלה מכוונת יפה לענין ההלכה, \u0003אימא כוליה להכי\u0004 \u0005[אמור,\u0006 שהפסוק \u0005כולו ל\u0006דבר \u0005זה]\u0006 \u0003הוא דאתא\u0004 \u0005[שבא\u0006\u0005],\u0006 לדין כבוד הנברא בצלם ולא לדין קללה כלל! ומשיבים: \u0003אם כן, נימא קרא\u0004 \u0005[שיאמר הכתוב\u0006\u0005]\u0006 \u0003\"קלת\", מאי\u0004 \u0005[מהו]\u0006 לשון \u0003\"קללת\"\u0004 — \u0003שמע מינה תרתי\u0004 \u0005[למד מכאן שני\u0006 דברים\u0005],\u0006 גם לדינו וגם למדרשו.","שנינו במשנה ש\u0003לא זו בלבד\u0004 שהתלוי חייב קבורה בו ביום, אלא כל אדם צריך לקברו ביום מותו אם אך אפשרי הדבר. \u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' שמעון בן יוחי: מנין למלין את מתו\u0004 (שלא קברו ביומו) \u0003שעובר עליו ב\"לא תעשה\"\u0004 — \u0003תלמוד לומר: \"כי קבור תקברנו\"\u0004 (דברים כא, כג), \u0003מכאן למלין את מתו שעובר ב\"לא תעשה\".\u0004","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים\u0006\u0005]\u0006 בלשון זו, ש\u0003אמר ר' יוחנן משום ר' שמעון בן יוחי: רמז\u0004 למצוות \u0003קבורה מן התורה מניין?\u0004 — \u0003תלמוד לומר: \"כי קבור תקברנו\", מכאן רמז\u0004 שיש מצות \u0003קבורה מן התורה.\u0004","ומסופר: \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שבור מלכא\u0004 \u0005[המלך\u0006\u0005],\u0006 מלך פרס, \u0003לרב חמא:\u0004 מצות \u0003קבורה מן התורה מניין?\u0004 מה ראיה יש בה שחייבים לקבור את המת ואסור לנהוג בדרך אחרת? \u0003אישתיק\u0004 \u0005[שתק]\u0006 \u0003ולא אמר ליה\u0004 \u0005[לו]\u0006 \u0003ולא מידי\u0004 \u0005[דבר\u0006\u0005],\u0006 שלא מצא מקור ראוי לכך. \u0003אמר רב אחא בר יעקב: אימסר עלמא בידא דטפשאי\u0004 \u0005[נמסר העולם ביד הטפשים\u0006\u0005],\u0006 \u0003דאיבעי ליה למימר\u0004 \u0005[שהיה לו לומר\u0006\u0005]\u0006 מקור לדבר מפסוק זה \u0003\"כי קבור\u0004 תקברנו\u0003\"\u0004 (דברים כא, כג)!","ומשיבים: היה שבור מלכא יכול לומר לו כי הכוונה \u0003דליעבד ליה\u0004 \u0005[שיעשו לו]\u0006 \u0003ארון\u0004 בקרקע ולאו דווקא קבורה להניחו בו. ואומרים: עדיין יכול היה להוכיח את הדבר מכפל הלשון \u0003\"\u0004קבור \u0003תקברנו\"!\u0004 ומשיבים: \u0003לא משמע ליה\u0004 \u0005[נשמע לו\u0006\u0005],\u0006 לא מסתבר לו ללמוד ממקרא כפול שנראה הדבר רק כשגרת לשון, ולא שיש בכך ללמד דין מיוחד.","ושואלים: \u0003ונימא מדאיקבור צדיקי\u0004 \u0005[ושיאמר לו\u0006 כמקור לדבר \u0005מ\u0006מה \u0005שנקברו הצדיקים\u0006 אברהם יצחק ויעקב\u0005]!\u0006 ועונים: יכול היה לומר שהדבר \u0003מנהגא בעלמא\u0004 \u0005[מנהג בלבד\u0006\u0005]\u0006 שנהגו אז, אבל לא מצוה לדורות. ושואלים: ושיביא לו ראיה \u0003מדקבריה\u0004 \u0005[מ\u0006מה \u0005שקברו\u0006\u0005]\u0006 \u0003הקדוש ברוך הוא למשה,\u0004 ומזה ראיה שכך ראוי! ומשיבים: היה יכול לומר שעשה כן הקדוש ברוך הוא כדי ש\u0003לא לישתני ממנהגא\u0004 \u0005[ישתנה ממנהג\u0006 כל העולם\u0005],\u0006 אבל אין כל ראיה שחובה היא.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה למצוות הקבורה, ממה שנאמר: \u0003\"וספדו לו כל ישראל וקברו אתו\"\u0004 (מלכים א' יד, יג)! ומשיבים: אף מכאן אין הוכחה אלא, אף שם עשו כן מאותו טעם, ש\u0003לא לישתני ממנהגא\u0004 \u0005[ישתנה ממנהג\u0006 העולם \u0005].\u0006","ועוד מקשים: והרי בקללה נאמר \u0003\"לא יספדו ולא יקברו לדמן על פני האדמה יהיו\"\u0004 (ירמיה טז, ד), ומכאן ראיה שבדרך כלל, שלא באופן של קללה, ראוי לקבור את המת! ומשיבים: אף מכאן אין ראיה שמצוה לקבור את המת, והקללה היתה \u0003דלישתנו ממנהגא\u0004 \u0005[שישתנו ממנהג\u0006 העולם\u0005].\u0006 ומפני קשיים אלה לא הביא רב חמא ראיה מן המקרא למצות קבורה.","אגב דיון זה מביאים את השאלה ש\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 חובת ה\u0003קבורה\u0004 למת, האם \u0003משום בזיונא\u0004 \u0005[בזיון\u0006\u0005]\u0006 \u0003הוא,\u0004 כלומר, שלא יתבזה המת בהיותו מוטל על הארץ, \u0003או משום כפרה הוא\u0004, שמתכפר לו כאשר חוזר לעפרו?","ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מכאן\u0006\u0005]\u0006 למעשה, אם נדע מה הוא הטעם? ומשיבים כגון ש\u0003אמר\u0004 אדם \u0003לא בעינא דליקברוה לההוא גברא\u0004 \u0005[אין אני רוצה שיקברו אותו איש,\u0006 כלומר, אותי\u0005]\u0006 \u0003אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי קבורה \u0003משום בזיונא\u0004 \u0005[בזיון]\u0006 \u0003הוא\u0004 — \u0003לא כל כמיניה\u0004 \u0005[אין זה בכוחו\u0006 למחול על הבזיון\u0005],\u0006 שהרי גם בני המשפחה שותפים בדבר. \u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 שהוא \u0003משום כפרה, הא\u0004 \u0005[הרי]\u0006 \u0003אמר\u0004 \u0003לא בעינא\u0004 \u0005[אין אני רוצה]\u0006 \u0003כפרה,\u0004 ויכול אדם לעשות בעצמו מה שירצה. אם כן \u0003מאי\u0004 \u0005[מה הדין]\u0006?","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר \u0003מדאיקבור צדיקי\u0004 \u0005[שנקברו הצדיקים,\u0006 אברהם יצחק ויעקב \u0005],\u0006 \u0003ואי אמרת\u0004 \u0005[ואם אומר אתה\u0006\u0005]\u0006 שהטעם \u0003משום כפרה,\u0004 וכי \u0003צדיקי\u0004 \u0005[הצדיקים]\u0006 \u0003לכפרה צריכי\u0004 \u0005[\u0006הם \u0005צריכים\u0006\u0005]?\u0006 ועונים: \u0003אין\u0004 \u0005[כן\u0006\u0005],\u0006 ודאי אף הם צריכים, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"\u0004כי \u0003אדם אין צדיק בארץ אשר יעשה טוב ולא יחטא\"\u0004 (קהלת ז, כ), וצריכים הם כפרה על חטאים מעטים שהיו בידם.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע\u0006\u0005]\u0006 ראיה לדבר, ממה שנאמר: \u0003\"וספדו לו כל ישראל וקברו אתו\u0004 כי זה לבדו יבא לירבעם אל קבר\u0003\"\u0004 (מלכים א' יד, יג), \u0003ואי אמרת כי היכי דתיהוי ליה\u0004 \u0005[אם אומר אתה\u0006 שקבורה באה \u0005כדי שתהיה לו]\u0006 \u0003כפרה,\u0004 אם כן \u0003הנך נמי ליקברו, כי היכי דתיהוי להו\u0004 \u0005[אלה גם כן,\u0006 שאר בני ירבעם, \u0005ייקברו, כדי שתהא להם]\u0006 \u0003כפרה!\u0004 ומשיבים: \u0003האי\u0004 \u0005[זה\u0006 הבן] ש\u0003צדיק הוא\u0004 — \u0003תיהוי ליה\u0004 \u0005[תהיה לו]\u0006 \u0003כפרה,\u0004 ואולם \u0003הנך\u0004 \u0005[אלה]\u0006 \u0003לא ליהוי להו\u0004 \u0005[תהיה להם]\u0006 \u0003כפרה\u0004 אף במיתתם.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר, ממה שנאמר \u0003\"לא יספדו ולא יקברו\"\u0004 (ירמיה טז, ד), משמע שאין זה משום כפרה, שהרי צריכים הם כפרה ולכך ראוי שייקברו! ומשיבים: אין זו ראיה, כי ייתכן שכוונת הקללה היא ש\u0003לא תיהוי להו\u0004 \u0005[תהיה להם]\u0006 \u0003כפרה.\u0004 ואם כן, לא נמצא פתרון לשאלה זו.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה דומה: \u0003הספידא, יקרא דחיי הוי או יקרא דשכבי הוי\u0004 \u0005[ההספד,\u0006 האם \u0005כבוד החיים\u0006 האבלים, \u0005הוא, או כבוד המתים הוא]?\u0006 ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא ממנה]\u0006 ממחלוקת זו? ומסבירים: כגון ש\u0003אמר\u0004 הנפטר \u0003לא תספדוה לההוא גברא\u0004 \u0005[אל תספדו לאותו איש,\u0006 כלומר, לי\u0005],\u0006 \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003לאפוקי מיורשין\u0004 \u0005[להוציא\u0006 את הממון \u0005מן היורשים]\u0006 את שכר הספדנים. שאם כבוד המתים הוא אפשר להוציא מהם, ואם ההספד כבוד החיים הוא, יכולים הם לוותר על כבוד זה.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר מכמה מקראות, נאמר \u0003\"ויבא אברהם לספד לשרה ולבכתה\"\u0004 (בראשית כג, ב) שנראה שהמתינו עד שבא מבאר שבע לחברון, \u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 כי ההספד \u0003משום יקרא דחיי הוא\u0004 \u0005[כבוד החיים],\u0006 וכי \u0003משום יקרא\u0004 \u0005[כבוד]\u0006 \u0003אברהם משהו לה\u0004 \u0005[ישהו אותה]\u0006 את \u0003שרה\u0004 ולא יקברוה בשעתה? ומשיבים: \u0003שרה גופה ניחא\u0004 \u0005[עצמה נוח]\u0006 \u0003לה\u0004 בכך \u0003כי היכי דמייקר\u0004 \u0005[כדי שייתכבד]\u0006 \u0003בה אברהם,\u0004 כלומר, יתכן וההספד הוא משום כבוד החיים, אך במקרה זה יש גם כיבוד לשרה, ולפיכך לא התבזתה שרה בציפייתה להספד אברהם, ולא נפתרה איפוא הבעיה.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון אחר לדבר ממה שנאמר: \u0003\"וספדו לו כל ישראל וקברו אתו\"\u0004 (מלכים א' יד, יג), \u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 כי \u0003משום יקרא דחיי\u0004 \u0005[כבוד החיים]\u0006 \u0003הוא,\u0004 וכי \u0003הנך\u0004 \u0005[אלה],\u0006 בני משפחת ירבעם, \u0003בני יקרא נינהו\u0004 \u0005[כבוד,\u0006 ראויים לכבוד \u0005הם]?\u0006 ומשיבים: \u0003ניחא להו לצדיקיא דמייקרי בהו אינשי\u0004 \u0005[נוח להם לצדיקים שמתכבדים בהם בני אדם],\u0006 ומפני שזה רצונם, מספידים אותם, אך ההספד הוא לכבוד הנותרים.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה שנאמר: \u0003\"לא יספדו ולא יקברו\"\u0004 (ירמיה טז, ד), ואם ההספד הוא משום כבוד החיים, אם כן מדוע לא יספדו, והלא בנותרים יש צדיקים הראויים לכבוד זה! ומשיבים: \u0003לא ניחא לצדיקיא\u0004 \u0005[נוח לצדיקים]\u0006 \u0003דמייקרי ברשיעייא\u0004 \u0005[ש\u0006הם \u0005מתכבדים על ידי הרשעים]\u0006 ומוותרים הם על הכבוד שחולקים להם על ידי הספד קרוביהם הרשעים.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה שנאמר: \u0003\"בשלום תמות ובמשרפות אבותיך המלכים הראשונים אשר היו לפניך כן ישרפו לך והוי אדון יספדו לך\"\u0004 (ירמיה לד, ה), \u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 כי \u0003משום יקרא דחיי\u0004 \u0005[כבוד החיים,\u0006 הנשארים\u0005]\u0006 \u0003הוא מאי נפקא ליה מיניה\u0004 \u0005[מה יוצא לו מזה]\u0006 אם יספדו לו? ומשיבים: \u0003הכי קאמר ליה\u0004 \u0005[כך אמר לו],\u0006 \u0003לייקרו ביך\u0004 \u0005[יתכבדו בך]\u0006 \u0003ישראל כי היכי דמתייקרי באבהתך\u0004 \u0005[כפי שהתכבדו באבותיך],\u0006 כלומר, ותדע עד כמה מכבדים הם אותך אף כעת."],["\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע\u0006\u0005]\u0006 ראיה אחרת לדבר, ממה ששנינו על הנאמר \u0003\"נבזה בעיניו נמאס\u0004 ואת יראי ה' יכבד\u0003\"\u0004 (תהלים טו, ד), \u0003זה חזקיהו מלך יהודה שגירר עצמות אביו על מטה של חבלים\u0004 ולא קברו בכבוד מלכים, כדי לבזותו על חטאיו. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003משום יקרא דחיי\u0004 \u0005[כבוד החיים]\u0006 \u0003הוא,\u0004 \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006\u0005]\u0006 עשה כך?","ומשיבים: עשה זאת \u0003כי היכי דתיהוי ליה\u0004 \u0005[כדי שתהיה לו]\u0006 \u0003כפרה לאבוה\u0004 \u0005[לאביו]\u0006 בבזיונו. ושואלים: \u0003ו\u0004כי \u0003משום כפרה דאבוה\u0004 \u0005[של אביו]\u0006 \u0003משהו ליה ליקרא\u0004 \u0005[משהים\u0006 ודוחים \u0005את כבוד]\u0006 \u0003ישראל\u0004 כולם, שמתכבדים על ידי ההספד למלך שמת? ומשיבים: \u0003ישראל גופייהו\u0004 \u0005[עצמם]\u0006 \u0003ניחא להו דמיחלי יקרייהו לגביה\u0004 \u0005[נוח להם ש\u0006הם \u0005מוחלים\u0006 על \u0005כבודם לגביו\u0006\u0005]\u0006 כדי שיתכפרו חטאיו.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע\u0006\u0005]\u0006 ראיה לדבר ממה ששנינו במקום אחר, \u0003אמר להן\u0004 רבי לתלמידיו לפני מותו: \u0003אל תספדוני בעיירות\u0004 קטנות כשמוליכים את ארונו לקבורה, אלא בערים הגדולות בלבד, \u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 שההספד הוא משום \u0003יקרא דחיי\u0004 \u0005[כבוד החיים],\u0006 \u0003מאי נפקא ליה מינה\u0004 \u0005[מה יוצא לו מזה\u0006\u0005]?\u0006 ומשיבים: \u0003קסבר\u0004 \u0005[סבור היה\u0006\u0005]\u0006 כי \u0003ליתייקרו ביה\u0004 \u0005[יתכבדו בו\u0006\u0005]\u0006 בית \u0003ישראל טפי\u0004 \u0005[יותר\u0006\u0005]\u0006 על ידי שיתקבצו יחד למקום אחד.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע\u0006\u0005]\u0006 ראיה לדבר ממה ששנינו במשנתנו: אם \u0003הלינו\u0004 למתו \u0003לכבודו\u0004 ולא קברו בו ביום, או כדי \u0003להביא לו ארון ותכריכין\u0004 — \u0003אינו עובר עליו\u0004 משום \"לא תלין\". \u0003מאי לאו\u0004 \u0005[האם לא\u0006\u0005]\u0006 הכוונה \u0003לכבודו של מת!\u0004 ודוחים: \u0003לא,\u0004 הכוונה \u0003לכבודו של חי,\u0004 של האבל.","ושואלים: \u0003ומשום כבודו של חי מבית ליה\u0004 \u0005[מלין אותו\u0006\u0005]\u0006 \u0003למת?!\u0004 ומשיבים: \u0003אין\u0004 \u0005[כן\u0006\u0005],\u0006 שכן \u0003כי אמר רחמנא\u0004 \u0005[כאשר אמרה התורה]\u0006 \u0003\"לא תלין נבלתו על העץ\u0004 כי קבור תקברנו\u0003\"\u0004 (דברים כא, כג) הרי זה \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003תלוי דאית ביה\u0004 \u0005[שיש בו,\u0006 בתלייתו\u0005]\u0006 משום \u0003בזיון,\u0004 \u0003אבל הכא\u0004 \u0005[כאן]\u0006 \u0003כיון דלית ביה\u0004 \u0005[שאין בו]\u0006 \u0003בזיון\u0004 — \u0003לא,\u0004 ורשאי יהיה להלינו.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע\u0006\u0005]\u0006 ראיה לדבר ממה ששנינו: \u0003הלינו\u0004 את המת \u0003לכבודו,\u0004 או \u0003לשמע\u0004 (לאסוף) \u0003עליו עיירות,\u0004 או כדי \u0003להביא לו מקוננות,\u0004 או כדי \u0003להביא לו ארון ותכריכין\u0004 — \u0003אינו עובר עליו, שכל העושה אינו אלא לכבודו של מת.\u0004 הרי מפורש שכל זה לכבוד המת! ודוחים: \u0003הכי קאמר\u0004 \u0005[כך אמר,\u0006 כך היתה הכוונה\u0005]:\u0006 \u0003כל העושה לכבודו של חי אין בו\u0004 משום \u0003בזיון למת.\u0004","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת לדבר ממה ששנינו ש\u0003ר' נתן אומר: סימן יפה למת שנפרעין ממנו לאחר מיתה,\u0004 שאין קבורתו והספדו בכבוד, שעל ידי כך מתכפרים עוונותיו, ו\u0003מת שלא נספד ולא נקבר או שחיה גוררתו או שהיו גשמים מזלפין\u0004 (יורדים) \u0003על מטתו זהו סימן יפה למת. שמע מינה\u0004 \u0005[למד מכאן\u0006\u0005]\u0006 כי ההספד משום \u0003יקרא דשכבי\u0004 \u0005[כבוד המתים]\u0006 \u0003הוא,\u0004 ומשום שנפגע כבודו — מתכפרים עוונותיו, ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן\u0006\u0005]\u0006 שכך הוא.","שנינו במשנה ש\u0003לא היו קוברין\u0004 את הרוגי בית דין בקברי משפחתם אלא בתי קברות מיוחדים היו. ומבארים: \u0003וכל כך למה\u0004 — \u0003לפי שאין קוברין רשע אצל צדיק.\u0004 ש\u0003אמר ר' אחא בר חנינא: מנין שאין קוברין רשע אצל צדיק\u0004 — \u0003שנאמר: \"ויהי הם קברים איש והנה ראו את הגדוד וישליכו את האיש בקבר אלישע\u0004 וילך \u0003ויגע האיש בעצמות אלישע ויחי ויקם על רגליו\"\u0004 (מלכים ב' יג, כא), שנעשה לו נס זה כדי שלא יהא אותו איש, שלא היה צדיק, קבור ליד אלישע.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא:\u0004 מה הראיה מכאן, \u0003ודילמא לאיקיומא\u0004 \u0005[ושמא\u0006 קם לתחיה כדי \u0005לקיים]\u0006 מה שנאמר באלישע \u0003\"ויהי נא פי שנים ברוחך אלי\"\u0004 (מלכים ב' ב, ט), וכדי שיחייה אלישע שני מתים (בן השונמית וזה), בעוד שאליהו החייה רק אחד? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אי הכי, היינו דתניא\u0004 \u0005[אם כך, זהו\u0006 מה \u0005ש\u0006\u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003על רגליו\u0004 — \u0003עמד, ו\u0004אולם \u0003לביתו לא הלך,\u0004 הרי שלא היה נס זה של תחיית המתים בשל גדולת אלישע, אלא כדי למנוע ממנו בזיון.","ושואלים: \u0003אלא \"ויהי נא פי שנים\", היכי משכחת לה דאחייא\u0004 \u0005[איך מוצא אתה אותה אם כן שהחייה]\u0006 שני מתים? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוחנן: שריפא צרעת נעמן שהיא שקולה,\u0004 כלומר, הלוקה בה חשוב \u0003כמת,\u0004 כפי שנאמר בענין צרעת מרים \u0003\"אל נא תהי כמת\"\u0004 (במדבר יב, יב).","שנינו: \u0003כשם שאין קוברין רשע אצל צדיק כך אין קוברין רשע\u0004 שעשה פשע \u0003חמור אצל רשע\u0004 שעשה פשע \u0003קל,\u0004 ולכן מתקנים קברות נפרדים לנסקלים ולנהרגים. ושואלים: \u0003וליתקון\u0004 \u0005[ושיתקינו]\u0006 \u0003ארבע קברות\u0004 כנגד ארבע הדרגות במיתות בית דין! ומשיבים: \u0003שני קברות גמרא גמירי לה\u0004 \u0005[במסורת למודים היו אותה]\u0006 שיש שנים, ולא יותר.","\u0003אמר עולא אמר ר' יוחנן:\u0004 מי ש\u0003אכל חלב\u0004 בשגגה \u0003והפריש קרבן ו\u0004לפני הקרבתו \u0003השתמד\u0004 (המיר דת) \u0003ו\u0004אחר זמן \u0003חזר בו\u0004 מהמרת הדת — \u0003הואיל ונדחה\u0004 מהקרבן בזמן המרת הדת, לפי שאין המשומדים רשאים להביא קרבנות — \u0003ידחה\u0004 קרבן זה ואינו ראוי לעולם.","\u0003איתמר נמי\u0004 \u0005[נאמר גם כן\u0006\u0005]\u0006 בדומה לזה, ש\u0003אמר ר' ירמיה אמר ר' אבהו אמר ר' יוחנן:\u0004 מי ש\u0003אכל חלב\u0004 בשגגה \u0003והפריש קרבן, ונשתטה\u0004 והשוטה אינו מביא קרבן ואין קרבנו ראוי, \u0003וחזר\u0004 לאחר \u0003מכן\u0004 \u0003ונשתפה\u0004 (חזר לשפיות דעת) — \u0003הואיל ונדחה\u0004 הקרבן בזמן שטותו — \u0003ידחה.\u0004","ומעירים: \u0003וצריכא\u0004 \u0005[ונצרכו\u0006 להיאמר שני הדברים\u0005]\u0006 שאמר ר' יוחנן למרות הדמיון ביניהם. \u0003דאי אשמעינן קמייתא\u0004 \u0005[שאם היה משמיע לנו\u0006 רק הלכה \u0005ראשונה]\u0006 במשומד בלבד, היינו אומרים: שכן הדין \u0003משום דאיהו\u0004 \u0005[שהוא\u0006\u0005]\u0006 \u0003דחה נפשיה\u0004 \u0005[עצמו\u0006\u0005]\u0006 \u0003בידים\u0004 על ידי השמד. \u0003אבל האי\u0004 \u0005[זה]\u0006 השוטה ש\u0003ממילא קא דחי\u0004 \u0005[הוא נדחה\u0006\u0005]\u0006 ולא מרצונו, \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003כישן דמי\u0004 \u0005[\u0006הוא \u0005נחשב\u0006\u0005],\u0006 והישן אינו נדחה.","\u0003ו\u0004להיפך: \u0003אי אשמעינן הכא\u0004 \u0005[אם היה משמיע לנו כאן]\u0006 בנשתטה בלבד, היינו אומרים שנדחה \u0003משום\u0004 ש\u0003אין בידו לחזור,\u0004 שהרי אין ביד השוטה להחליט להתרפא, \u0003אבל התם\u0004 במשומד ש\u0003בידו לחזור\u0004 — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 ייחשב כדחוי, על כן \u0003צריכא\u0004 \u0005[נצרכו\u0006\u0005]\u0006 להיאמר שני הדברים.","\u0003אמר רב יוסף: אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו\u0006\u0005]\u0006 מעין זה, ששנינו: אם \u0003היו בה\u0004 בעיר הנדחת \u0003קדשים,\u0004 אם היו אלה \u0003קדשי מזבח\u0004 — \u0003ימותו,\u0004 אם \u0003קדשי בדק הבית\u0004 — \u0003יפדו, והוינן\u0004 \u0005[ועסקנו,\u0006 ושאלנו\u0005]\u0006 \u0003בה\u0004 בשאלה זו: \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003ימותו\u0004 אותם הקדשים? \u0003כיון דאיקטול\u0004 \u0005[שמתו]\u0006 רשעים בצער — \u0003הויא להו\u0004 \u0005[יש להם]\u0006 \u0003כפרה\u0004 במותם, \u0003וליסקו\u0004 \u0005[ויעלו]\u0006 הקרבנות \u0003לגבוה\u0004 ונוכל מעתה להקריבם! \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דאמרינן\u0004 \u0005[שאנו אומרים\u0006\u0005]:\u0006 \u0003הואיל ונדחו\u0004 — \u0003ידחו,\u0004 שבאותה שעה שהיו עובדים עבודה זרה נדחו קרבנותיהם ושוב אינם חוזרים להיות ראויים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: מי סברת\u0004 \u0005[האם סבור אתה\u0006\u0005]\u0006 שמי ש\u0003מת מתוך רשעו הויא ליה\u0004 \u0005[יש לו]\u0006 \u0003כפרה?\u0004 הדין אינו כן, אלא מי ש\u0003מת מתוך רשעו לא הויא ליה\u0004 \u0005[אין לו]\u0006 \u0003כפרה, דתני\u0004 \u0005[ש\u0006כן \u0005שנה]\u0006 \u0003רב שמעיה: יכול אפילו פירשו אבותיו מדרכי ציבור\u0004 והשתמדו, \u0003יטמא\u0004 להם הבן הכהן, וכפי שנאמר: \"לנפש לא יטמא בעמיו. כי אם לשארו הקרוב אליו לאמו ולאביו וגו' \" (ויקרא כא, א–ב) — \u0003תלמוד לומר: \"בעמיו\",\u0004 וכוונתו — \u0003בעושה מעשה עמיו,\u0004 כשנוהג כישראל, הרי שאף לאחר שמת אביו הרשע עדיין נחשב הוא רשע!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: מי קא מדמית\u0004 \u0005[האם אתה יכול להשוות\u0006\u0005]\u0006 מי ש\u0003נהרג מתוך רשעו\u0004 למי ש\u0003מת מתוך רשעו?!\u0004 מי ש\u0003מת מתוך רשעו, כיון דכי אורחיה קמיית\u0004 \u0005[שכדרכו הוא מת]\u0006 — \u0003לא הויא ליה\u0004 \u0005[אין לו]\u0006 \u0003כפרה,\u0004 שלא היה מעשה שיגרום לו להתכפר. ואולם מי ש\u0003נהרג מתוך רשעו, כיון דלאו כי אורחיה מיית\u0004 \u0005[שלא כדרכו מת]\u0006 — \u0003הויא ליה\u0004 \u0005[יש לו]\u0006 \u0003כפרה.\u0004","\u0003תדע\u0004 שכן הוא, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"מזמור לאסף אלהים באו גוים בנחלתך טמאו את היכל קדשך\u0004 שמו את ירושלים לעיים. \u0003נתנו את נבלת עבדיך מאכל לעוף השמים בשר חסידיך לחיתו ארץ\"\u0004 (תהלים עט, א–ב), וצריך להבין \u0003מאי\u0004 \u0005[מה\u0006 משמעות\u0005]\u0006 המלה \u0003\"עבדיך\" ומאי\u0004 \u0005[ומה\u0006 משמעות\u0005]\u0006 המלה \u0003\"חסידיך\"? לאו\u0004 \u0005[האם לא\u0006\u0005]\u0006 תפרש כך: \u0003\"חסידיך\"\u0004 הם \u0003חסידיך ממש\u0004, שהם יראי ה' תמיד, ו\u0003\"עבדיך\"\u0004 הם \u0003הנך\u0004 \u0005[אלה\u0006\u0005]\u0006 \u0003דמחייבי דינא דמעיקרא\u0004 \u0005[שהיו חייבים בדין מתחילה\u0006\u0005]\u0006 משום חטאותיהם, \u0003וכיון דאיקטול\u0004 \u0005[שנהרגו]\u0006 — \u0003קרי להו\u0004 \u0005[\u0006הריהו \u0005קורא להם\u0006\u0005]\u0006 \u0003\"עבדיך\",\u0004 משמע שמתוך שנהרגו נתכפרו להם עוונותיהם.","\u0003אמר\u0004 \u0003ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 ודחה את דבריו: \u0003מי קא מדמית\u0004 \u0005[האם אתה\u0006 יכול \u0005להשוות]\u0006"],["\u0003הרוגי מלכות להרוגי בית דין? הרוגי מלכות, כיון\u0004 \u0003ש\u0004הרי \u0003לא בדין קא מיקטלי\u0004 \u0005[הם נהרגים]\u0006 אלא מתוך רשעת המלכויות, \u0003הויא להו\u0004 \u0005[יש להם]\u0006 \u0003כפרה\u0004 במותם ואולם \u0003הרוגי בית דין, כיון\u0004 ש\u0003בדין קא מיקטלי\u0004 \u0005[הם נהרגים]\u0006 על חטאותיהם — \u0003לא הוי להו\u0004 \u0005[אין להם]\u0006 \u0003כפרה.\u0004","ו\u0003תדע\u0004 שכן הוא, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003לא היו קוברין אותו,\u0004 את הנידון, \u0003בקברות אבותיו. ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006 לומר\u0005]\u0006 כי \u0003כיון דאיקטול, הויא להו\u0004 \u0005[שנהרגו, יש להם]\u0006 \u0003כפרה, ליקברו\u0004 \u0005[שיקברו]\u0006 אם כן בקברות אבותיהם! ודוחים: משם אין ראיה, שכן לא די במיתה לכפרה אלא \u0003מיתה וקבורה בעינן\u0004 \u0005[צריכים אנו],\u0006 ולאחר שנקבר בקברות הרשעים נתכפר לו לגמרי.","\u0003מותיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב אדא בר אהבה\u0004 ממה ששנינו: \u0003לא היו\u0004 קרוביהם של ההרוגים \u0003מתאבלין\u0004 עליהם \u0003אלא אוננין\u0004 (מצטערים) עליהם, כיון \u0003שאין אנינות אלא בלב. ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר כי \u0003כיון דאיקבור הויא להו\u0004 \u0005[שנקברו יש להם]\u0006 \u0003כפרה,\u0004 אם כן \u0003ליאבלו\u0004 \u0005[ שיתאבלו]\u0006 גם כן, שהרי נתכפרו אותם נידונים!","ודוחים: \u0003בעינן נמי\u0004 \u0005[צריכים אנו]\u0006 שיהיה גם \u0003עיכול בשר\u0004 של הרשעים על מנת שתהא להם כפרה. ומעירים: \u0003דיקא נמי\u0004 \u0005[מדויק גם כן]\u0006 שזה הוא ההסבר הנכון, \u0003דקתני\u0004 \u0005[ש\u0006כך \u0005שנינו]:\u0006 \u0003נתעכל הבשר\u0004 — \u0003מלקטין את העצמות וקוברין אותן במקומן,\u0004 משמע שלאחר עיכול הבשר נתכפר להם, ורשאים להיקבר עם משפחתם. ואומרים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן\u0006\u0005]\u0006 שכן הוא.","\u0003רב אשי אמר\u0004 באופן אחר: \u0003אבילות מאימתי קא מתחלת\u0004 \u0005[היא מתחילה]\u0006 — \u0003מ\u0004זמן \u0003סתימת הגולל\u0004 (אבן שמכסים בה את הקבר), \u0003כפרה מאימתי קא הויא\u0004 \u0005[היא]\u0006 — \u0003מכי חזו צערא דקברא פורתא\u0004 \u0005[מזמן\u0006 שהם \u0005רואים\u0006 את \u0005צער הקבר מעט]\u0006 \u0003הלכך \u0004 \u0005[ולכן]\u0006 \u0003הואיל ואידחו\u0004 \u0005[שנדחו]\u0006 מרגע ראשון של אבלות — \u0003ידחו,\u0004 ואולם אין להוכיח שלא נתכפר למת.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שעל ידי היותם זמן מה בקבר מתכפר להם \u0003למה לי עיכול בשר?\u0004 יוציאוהו מיד לאחר קבורתו! ומשיבים: \u0003משום דלא\u0004 \u0005[שאי]\u0006 \u0003אפשר\u0004 \u0005[משום שאי אפשר]\u0006 לעשות כן, שיש בזיון למת שמטלטלים את גופתו ממקום למקום ולכן מחכים עד שיתעכל הבשר.","מסופר: \u0003קבריה\u0004 \u0005[קברו]\u0006 של \u0003רב הוו שקלי מיניה עפרא לאישתא בת יומא\u0004 \u0005[היו לוקחים ממנו\u0006 הבריות \u0005עפר\u0006 כרפואה \u0005לקדחת בת יום].\u0006 \u0003אתו\u0004 \u0005[באו]\u0006 ו\u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003לשמואל\u0004 שכך נוהגים ומשתמשים בקברו של רב. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003יאות עבדין\u0004 \u0005[יפה\u0006 הם \u0005עושים],\u0006 כלומר, מותר להם לעשות כן. כי הקבר \u0003קרקע עולם הוא, וקרקע עולם אינה נאסרת\u0004 מכל דבר, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"\u0004ויוצא את האשרה מבית ה'... וידק לעפר \u0003וישלך את עפרה על קבר בני העם\"\u0004 (מלכים ב' כג, ו), \u0003מקיש\u0004 \u0005[משווה]\u0006 הפסוק את \u0003\"קבר בני העם\" לעבודה זרה,\u0004","\u0003מה עבודה זרה\u0004 כשהיא \u0003במחובר\u0004 לקרקע \u0003לא מיתסרא\u0004 \u0005[אינה נאסרת]\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \"אבד תאבדון את כל המקומות אשר עבדו שם הגוים \u0003אשר אתם ירשים אתם את אלהיהם על ההרים הרמים\u0004 ועל הגבעות ותחת כל עץ רענן. ונתצתם את מזבחתם ושברתם את מצבתם וגו' \" (דברים יב, ב–ג), משמע שהחובה היא להשמיד את האלילים שעל ההרים, כאמור: \u0003\"על ההרים אלהיהם\"\u0004 — \u0003ולא\u0004 את \u0003ההרים\u0004 כשהם עצמם \u0003אלהיהם,\u0004 שאם עבדו את ההר עצמו כעבודה זרה אין צורך להשמיד אותו, כי כל המחובר לקרקע אינו נאסר, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 נלמד מכאן לענין קברות המת ש\u0003במחובר לא מיתסר\u0004 \u0005[אינו נאסר]\u0006.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו: \u0003החוצב קבר\u0004 עבור \u0003אביו\u0004 במקום אחד, \u0003והלך וקברו\u0004 לבסוף \u0003במקום אחר\u0004 — \u0003הרי זה לא יקבר בו\u0004 הבן \u0003עולמית,\u0004 שאסור להשתמש בקבר שהכינו כבר עבור מת מסויים, ומשמע שגם המחובר לקרקע (חצוב בה) עשוי להיאסר! ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003בקבר בנין,\u0004 שאין המדובר בחציבה בתוך הסלע, אלא שבנה אותו מאבני מחצב, וכל אבן ואבן שבו נאסרה, שהרי היתה תלושה.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת לדבר, ממה ששנינו: \u0003קבר חדש\u0004 שלא הכינוהו למת מסויים — \u0003מותר בהנאה.\u0004 אבל אם \u0003הטיל בו\u0004 אפילו \u0003נפל\u0004 — \u0003אסור בהנאה.\u0004 משמע שעל ידי קבורה נאסר הקבר שבאדמה עצמו! ומשיבים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003בקבר בנין\u0004 ולא בקבר מחובר לקרקע.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו במקום אחר: \u0003נמצא אתה אומר שלש קברות הן\u0004 לענין פינוי, \u0003קבר הנמצא, קבר הידוע, קבר המזיק את הרבים.\u0004 כיצד? — \u0003קבר הנמצא,\u0004 שמצאו קבר במקום ולא ידעו כלל שהיה שם קבור אדם — \u0003מותר לפנותו\u0004 ממקומו, ולאחר ש\u0003פינהו\u0004 — \u0003מקומו טהור\u0004 מטומאת המת, \u0003ו\u0004גם \u0003מותר בהנאה.\u0004","\u0003קבר הידוע,\u0004 שברשות נקבר אדם שם — \u0003אסור לפנותו,\u0004 ואם בכל זאת \u0003פינהו\u0004 — \u0003מקומו טמא, ואסור\u0004 הקבר \u0003בהנאה.\u0004","\u0003קבר המזיק את הרבים,\u0004 כגון שקברו אדם במקום שמהלכים בו רבים והם נטמאים בגללו — \u0003מותר לפנותו, פינהו\u0004 — \u0003מקומו טהור ואסור בהנאה\u0004 ומדוגמאות אלה משמע לכאורה שאף קבר רגיל החצוב בקרקע עשוי להיות טמא אף אחר פינויו! ומשיבים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003בקבר בנין.\u0004","אגב הבאת הלכה זו שואלים: \u0003וקבר הנמצא מותר לפנותו,\u0004 משום שמניחים שנקבר שלא מדעת ושלא ברשות? ואולם \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003מת מצוה הוא\u0004 זה, שהיה זה אדם ערירי שמת פתאם שם ולפי הדין \u0003מת מצוה קנה מקומו\u0004 שמת בו, ואין רשות לפנותו! ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003מת מצוה דקלא אית ליה\u0004 \u0005[שקול יש לו]\u0006 שלא יתכן שאירע דבר כזה ולא נתפרסם בין הבריות, ואם אינו ידוע הרי ברור שאין זה מת מצוה.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בשאלה זו: \u0003האורג בגד למת, אביי אמר:\u0004 הבגד \u0003אסור\u0004 בהנאה ככל הדברים השייכים למת, \u0003ורבא אמר:\u0004 הבגד \u0003מותר\u0004 בהנאה.","ומסבירים את שיטותיהם: \u0003אביי אמר\u0004 שהבגד \u0003אסור,\u0004 כי לדעתו \u0003הזמנה\u0004 (הועדה למשהו) \u0003מילתא\u0004 \u0005[דבר]\u0006 \u0003היא,\u0004 כלומר, עצם ההכנה לצורך מסויים יש לה משמעות הלכתית, כאילו היה הדבר בפועל, ומה שזימנו למת הרי זה כאילו השתמשו בו עבור המת. \u0003ורבא אמר\u0004 שהבגד \u0003מותר,\u0004 כי לדעתו \u0003הזמנה לאו מילתא\u0004 \u0005[לא דבר]\u0006 \u0003היא\u0004 לענין זה.","ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003אביי\u0004 — \u0003גמר\u0004 \u0005[למד]\u0006 בגזירה שווה \u0003\"שם\" \"שם\" מעגלה ערופה,\u0004 שבקבר המת נאמר: \"ותמת שם מרים ותקבר שם\" (במדבר כ, א), ונאמר בעגלה ערופה \"והורידו זקני העיר ההוא את העגלה אל נחל איתן אשר לא יעבד בו ולא יזרע וערפו שם את העגלה בנחל\" (דברים כא, ד), \u0003מה עגלה ערופה בהזמנה\u0004 בלבד \u0003מיתסרא\u0004 \u0005[\u0006היא \u0005נאסרת],\u0006 \u0003האי נמי\u0004 \u0005[זה גם כן]\u0006 דברי המת והשייך לו — \u0003בהזמנה\u0004 בלבד נאסרה.","\u0003ורבא גמר\u0004 \u0005[למד]\u0006 בצורה אחרת: \u0003\"שם\" \"שם\" מעבודה זרה,\u0004 שנאמר אף בעבודה זרה \"אשר עבדו שם הגוים... את אלוהיהם\" (דברים יב, ב), \u0003מה עבודה זרה בהזמנה לא\u0004 נאסרה, אלא דווקא בפולחן ממש, \u0003אף הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003בהזמנה\u0004 בלבד אינה נאסרת.","ושואלים: \u0003ורבא\u0004 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא גמר\u0004 \u0005[למד]\u0006 \u0003מעגלה ערופה? אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך\u0004 כי"],["\u0003משמשין\u0004 של מת \u0003ממשמשין\u0004 של עבודה זרה \u0003גמרינן\u0004 \u0005[לומדים אנו],\u0006 \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003עגלה ערופה\u0004 ש\u0003היא גופה\u0004 \u0005[עצמה]\u0006 \u0003קדושה,\u0004 שיש לה קדושה מסויימת.","ושואלים: \u0003ואביי מאי טעמא\u0004 \u0005[מה הטעם]\u0006 \u0003לא גמר\u0004 \u0005[למד]\u0006 \u0003מעבודה זרה? אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך\u0004 כי \u0003מידי דאורחיה ממידי דאורחיה גמרינן\u0004 \u0005[דבר ש\u0006הוא \u0005דרכו, מדבר ש\u0006הוא \u0005דרכו אנו לומדים],\u0006 ששתי מצוות אלה הן מצוות התורה, \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003עבודה זרה דלאו אורחא\u0004 \u0005[שאינה דרך\u0006 לעשותה\u0005].\u0006","ומכאן מתחילים להביא ראיות לשתי השיטות ממקורות שונים, ו\u0003סימן\u0004 להם: \u0003כפה, נפשיה, דחציבא, נכיסא, דאומנא.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו: \u0003כפה\u0004 (כיסוי ראש) \u0003שהוא טמא מדרס\u0004 משום שיש חשש שנגע או השתמש בו הזב, \u0003ונתנתו\u0004 האשה \u0003לספר\u0004 תורה במתנה — \u0003טהור מן המדרס\u0004 משום ששוב אינו שייך עוד לבעליו וכל כגון זה שוב אינו טמא במדרס הזב, \u0003אבל\u0004 הוא \u0003טמא\u0004 עדיין טומאת \u0003מגע מדרס.\u0004 משמע שהכנה בלבד יש לה משמעות ותוקף בהלכה! ודוחים: \u0003אימא\u0004 \u0005[אמור]\u0006 ותקן כך: \u0003נתנתו וכרכתו\u0004 לספר התורה, שלא היתה רק הזמנה בלבד אלא אף מעשה.","ושואלים: אם מעשה היה כאן \u0003למה לי נתנתו וכרכתו?\u0004 שאין צורך בנתינה ודי בכריכה בלבד ומסבירים: הרי זה \u0003כ\u0004שיטת \u0003רב חסדא,\u0004 ש\u0003אמר רב חסדא: האי סודרא\u0004 \u0005[סודר זה]\u0006 \u0003דאזמניה למיצר ביה\u0004 \u0005[שזימנו\u0006 כדי \u0005לצרור בו]\u0006 \u0003תפילין, וצר ביה\u0004 \u0005[ו\u0006אכן \u0005צרר בו]\u0006 \u0003תפילין\u0004 — \u0003אסור למיצר ביה פשיטי\u0004 \u0005[לצרור בו\u0006 עוד \u0005מעות],\u0006 מכיון שנתייחד לתשמישי קדושה. ואולם אם \u0003אזמניה\u0004 \u0005[זימנו]\u0006 כדי לצרור בו תפילין, \u0003ו\u0004לבסוף \u0003לא צר ביה\u0004 \u0005[צרר בו],\u0006 או ש\u0003צר ביה\u0004 \u0005[צרר בו]\u0006 \u0003ולא אזמניה\u0004 \u0005[זימנו]\u0006 לכך באופן קבוע — \u0003שרי למיצר ביה פשיטי\u0004 \u0005[מותר לצרור בו מעות],\u0006 ולפיכך בכפה הנזכרת היה צורך להזמינה לכך ואף לכרוך בה.","\u0003ול\u0004שיטת \u0003אביי\u0004 ש\u0003אמר הזמנה מילתא\u0004 \u0005[דבר]\u0006 \u0003היא,\u0004 אם \u0003אזמניה אף על גב\u0004 \u0005[זימנו אף על פי]\u0006 ש\u0003לא צר ביה\u0004 \u0005[צרר בו]\u0006 — נאסר בשימוש אחר. ואם \u0003צר ביה\u0004 \u0005[צרר בו],\u0006 \u0003אי אזמניה\u0004 \u0005[אם זימנו]\u0006 לכך — \u0003אין\u0004 \u0005[כן],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא אזמניה\u0004 \u0005[זימנו]\u0006 — \u0003לא.\u0004","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת לדבר ממה ששנינו: \u0003נפש,\u0004 כלומר, בנין מצבה שבונים לכבודו וזכרונו של אדם, אם \u0003בנאו לשם חי,\u0004 כלומר, בעוד אותו האיש חי — \u0003מותר בהנאה,\u0004 שהרי כשאר בנין הוא, ואולם אם \u0003הוסיף בו דימוס\u0004 (נדבך) \u0003אחד לשם מת,\u0004 לאחר שמת אותו אדם — \u0003אסור\u0004 הוא \u0003בהנאה.\u0004 ולכאורה מכאן הוכחה שהזמנה יש בה תוקף! ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003דרמא ביה\u0004 \u0005[שהשליך,\u0006 קבר \u0005בו]\u0006 את ה\u0003מת\u0004 ולא בהכנה בלבד.","ומקשים: \u0003אי הכי מאי איריא\u0004 \u0005[אם כך\u0006 \u0003מה שייך,\u0004 מדוע דווקא\u0005]\u0006 \u0003הוסיף,\u0004 \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003לא הוסיף נמי\u0004 \u0005[גם כן]\u0006 יהיה אסור, שהרי נעשה בו שימוש למת! ומסבירים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה ש\u0003אף על גב דפנייה\u0004 \u0005[אף על פי שפינהו]\u0006 את המת משם, לאחר כך, מכל מקום, כיון שזימנו לכך — נאסר.","\u0003אמר רפרם בר פפא אמר רב חסדא: אם היה מכירו\u0004 ומבחין באותו נדבך יתר שנעשה לכבוד המת ולצורכו, ועכשיו אין מת במקום — \u0003חולצו,\u0004 עוקר נדבך זה, \u0003ומותר\u0004 שאר הבנין.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת לענייננו ממה ששנינו: \u0003החוצב קבר לאביו, והלך וקברו\u0004 לבסוף \u0003בקבר אחר\u0004 — \u0003הרי זה לא יקבר בו\u0004 הוא עצמו \u0003עולמית,\u0004 משמע שהזמנה אוסרת! ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 הטעם \u0003משום כבוד אביו,\u0004 ולא משום איסור השימוש בחפציו של מת.","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לומר, \u0003דקתני סיפא\u0004 \u0005[ששנינו\u0006 ב\u0005סופה\u0006 של אותה ברייתא\u0005],\u0006 \u0003רבן שמעון בן גמליאל אומר: אף החוצב אבנים לאביו, והלך וקברו במקום אחר\u0004 — \u0003הרי זה לא יקבר\u0004 הוא \u0003בהן\u0004 \u0003עולמית.\u0004","\u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 שהטעם הוא \u0003משום כבוד אביו\u0004 — \u0003שפיר\u0004 \u0005[יפה],\u0006 \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שהטעם הוא \u0003משום הזמנה,\u0004 וכי במקרה של חוט ה\u0003טווי לאריגה\u0004 כדי לעשות ממנו תכריכים למת, בזה \u0003מי איכא למאן דאמר\u0004 \u0005[האם יש מי שאומר]\u0006 שעל ידי כך יחול עליו איסור? וודאי בכיוצא בזה לא חל ולא שייך איסור, וכן אבנים אלה, הרי הן כטווי לאריגה ואינן נאסרות מצד עצמן, אלא משום כבוד אביו.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת לדבר ממה ששנינו: \u0003קבר חדש מותר בהנאה,\u0004 ואולם אם \u0003הטיל בו\u0004 מת, ואפילו \u0003נפל\u0004 — \u0003אסור בהנאה.\u0004 ונדייק: \u0003הטיל\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 אסור בהנאה, אבל \u0003לא הטיל\u0004 — \u0003לא,\u0004 משמע שהזמנה בלבד אינה אוסרתו!","ודוחים: \u0003הוא הדין דאף על גב\u0004 \u0005[שאף על פי]\u0006 ש\u0003לא הטיל\u0004 בו נפל גם כן אסור בהנאה, ומדוע אמרנו שהטיל — \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004שיטת \u0003רבן שמעון בן גמליאל,\u0004 ש\u0003אמר: אין לנפלים תפיסת הקבר\u0004 ואף כשקוברים אותם במקום, אין הוא נחשב כקבר, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין מקבלים שיטה זו, והנפל דינו כשאר המתים.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת לדבר ממה ששנינו: \u0003מותר המתים,\u0004 כלומר, מה שנשאר מן הממון שגבו לצורך קבורת המתים — הריהו \u0003למתים,\u0004 עבור קבורת מתים אחרים, \u0003מותר ה\u0004דברים שגבו ל\u0003מת\u0004 מסויים — \u0003ליורשיו.\u0004 משמע שמה שגבו עבור מת וזימנו עבורו, אינו נאסר ומותר שישתמשו בו יורשיו! ודוחים: מכאן אין להוכיח, כי \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003שגבו מחיים,\u0004 שידעו שאותו אדם עומד למות ועשו מגבית לצורך קבורתו בעודו חי, וכיון שהכסף לא נתפס באיסור הנאה הרי הוא ניתן ליורשיו.","ומקשים: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לא תני הכי\u0004 \u0005[כך שנינו],\u0006 ששנינו: \u0003מותר המתים\u0004 — \u0003למתים, מותר המת\u0004 — \u0003ליורשיו. ותני עלה\u0004 \u0005[ושנויה עליה\u0006 תוספתא\u0005]:\u0006 \u0003כיצד?\u0004 \u0003גבו\u0004 עבור \u0003מתים סתם\u0004 — \u0003זהו\u0004 המקרה לגביו אמרו ש\u0003מותר המתים למתים, גבו למת זה\u0004 — \u0003זהו\u0004 לגביו אמרו ש\u0003מותר המת ליורשיו.\u0004 משמע שגבו למת ממש!","ומשיבים: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך \u0005]\u0006 \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סוף\u0006 אותה ברייתא\u0005],\u0006 \u0003ר' מאיר אומר: לא יגע בהן\u0004 במעות אלה עד \u0003שיבא אליהו\u0004 וייפתר הספק אם יש לחשוש לאיסור, \u0003ר' נתן אומר: יעשנו,\u0004 במותר, עוד \u0003דימוס\u0004 \u0005[נדבך\u0006\u0005]\u0006 \u0003על קברו\u0004 של המת \u0003או זילוף\u0004 של יין לריח טוב \u0003לפני מטתו.\u0004 הרי שיש תנאים הסבורים שהזמנה לצורך המת דבר הוא!","\u0003אלא, אביי מתרץ\u0004 \u0005[מיישב]\u0006 את המשנה \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 \u0003ורבא מתרץ\u0004 \u0005[מיישב]\u0006 את המשנה \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 והם מתאימים את לשונה לשיטתם. \u0003אביי מתרץ\u0004 \u0005[מיישב]\u0006 את המשנה \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 כך: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003הזמנה\u0004 לצורך \u0003מילתא\u0004 \u0005[דבר\u0006\u0005]\u0006 \u0003היא,\u0004 וה\u0003תנא קמא סבר\u0004 \u0005[הראשון\u0006 בראש המשנה \u0005סבור]\u0006 כי מה \u0003דחזי ליה\u0004 \u0005[שראוי לו]\u0006 למת — \u0003תפיס\u0004 \u0005[תופס\u0006 האיסור\u0005],\u0006 ומה ש\u0003לא חזי ליה\u0004 \u0005[ראוי לו]\u0006 — \u0003לא תפיס\u0004 \u0005[תופס\u0006\u0005],\u0006 ולכן, אם נשאר דבר — הרי הוא שייך ליורשים, שלא נתפס בו האיסור.","\u0003ור' מאיר מספקא ליה אי תפיס\u0004 \u0005[ספק לו אם תופס]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא תפיס\u0004 \u0005[תופס\u0006\u0005],\u0006 \u0003הלכך\u0004 \u0005[על כן\u0006\u0005]\u0006 \u0003לא יגע בהן עד שיבא אליהו. ור' נתן פשיטא ליה\u0004 \u0005[פשוט לו\u0006\u0005]\u0006 ש\u0003ודאי תפיס\u0004 \u0005[תופס\u0006\u0005]\u0006 הכל גם מה שאין ראוי לו, \u0003הלכך\u0004 \u0005[על כן\u0006\u0005]\u0006 \u0003יעשה דימוס\u0004 \u0005[נדבך]\u0006 \u0003על קברו.\u0004","\u0003ורבא מתרץ\u0004 \u0005[מיישב]\u0006 את המשנה \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]:\u0006 \u0003לכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003הזמנה לאו מילתא\u0004 \u0005[אינה דבר\u0006\u0005],\u0006 \u0003היא\u0004 והכסף שגבו אינו נאסר כלל. אלא השאלה היא אחרת \u0003תנא קמא סבר\u0004 \u0005[הראשון סבור]:\u0006 \u0003כי בזו ליה\u0004 \u0005[כאשר ביזו אותו\u0006\u0005]\u0006 בעצם הצורך לגבות כספים לקבורתו, \u0003אחולי מחיל זילותיה\u0004 \u0005[הריהו מוחל\u0006 את \u0005זלזולו\u0006\u0005]\u0006 ל\u0003גבי יורשים,\u0004 ולכן מותר להם לקחת את ירושתו.","\u0003ור' מאיר מספקא ליה אי מחיל אי\u0004 \u0005[ספק לו אם מוחל\u0006 הוא \u0005או]\u0006 \u0003לא מחיל\u0004 \u0005[מוחל\u0006\u0005],\u0006 \u0003הלכך\u0004 \u0005[על כן]\u0006 \u0003לא יגע בהן. ור' נתן פשיטא ליה דלא מחיל\u0004 \u0005[פשוט לו שאינו מוחל\u0006\u0005]\u0006 \u0003הלכך\u0004 \u0005[על כן\u0006\u0005]\u0006 \u0003יעשה דימוס\u0004 \u0005[נדבך]\u0006 \u0003על קברו או זילוף לפני מטתו.\u0004 וכך הסביר רבא את כל הדעות בברייתא בצורה שאינה סותרת את דעתו שהזמנה אין בה תוקף לאסור את השימוש בחפץ.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע\u0006\u0005]\u0006 ראיה אחרת לדבר ממה ששנינו: \u0003היו אביו ואמו\u0004 של הנפטר \u0003מזרקין בו כלים\u0004 על מטת הבן, כדי שהכלים יקברו עמו — \u0003מצוה על האחרים להצילן\u0004 וליטול את הכלים. משמע שהזמנה בלבד אינה מועילה. שאם לא כן, הרי לאחר זריקה שוב אי אפשר היה להשתמש בהם!"],["ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 \u0003משום מררייהו\u0004 \u0005[מרירותם\u0006\u0005]\u0006 הם זורקים את הבגדים, אבל אין לראות בכך כוונה ממשית לזימון הבגדים למת. ומקשים: \u0003אי הכי היינו דקתני עלה\u0004 \u0005[אם כך,\u0006 וכי \u0005זהו ששנינו עליה\u0006 על משנה זו\u0005],\u0006 \u0003אמר רבן שמעון בן גמליאל: במה דברים אמורים\u0004 — \u0003שלא נגעו\u0004 החפצים \u0003במטה\u0004 לפני שהצילו אותם, \u0003אבל\u0004 אם כבר \u0003נגעו במטה\u0004 — \u0003אסורין.\u0004 ואם אין חשיבות למה שעושים מתוך מרירותם, מדוע ייאסרו כלים שנגעו במיטה?","\u0003תרגמה\u0004 \u0005[הסביר אותה]\u0006 \u0003עולא:\u0004 שזרקו \u0003במטה הנקברת עמו. דמחלפי\u0004 \u0005[שמתחלפים\u0006\u0005]\u0006 אותם בגדים לבריות \u0003בתכריכי המת,\u0004 וכיון שנפלו על מטת המת — אסרום. שלא יראה כאילו נוטלים מתכריכי המת ומשתמשים לצרכם. אבל אין זו הוכחה שזימון רגיל אוסר עולמית את השימוש בחפץ.","ומציעים עוד ראיה, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע\u0006\u0005],\u0006 ששנינו: \u0003כיס שעשאו להניח בו תפילין\u0004 — \u0003אסור להניח בו מעות.\u0004 אם \u0003הניח בו תפילין\u0004 אך לא הכינו מתחילה לצורך זה — \u0003יניח בו מעות.\u0004 משמע שהכנה וזימון קובעות! ומסבירים: \u0003אימא\u0004 \u0005[אמור,\u0006 תקן כך\u0005]:\u0006 \u0003עשאו\u0004 להניח בו תפילין \u0003ו\u0004אכן \u0003הניח בו תפילין\u0004 — \u0003אסור להניח בו מעות, כ\u0004שיטת \u0003רב חסדא\u0004 הנזכרת לעיל (סנהדרין מח, א) שאין להשתמש בסודר שזימנוהו לצורך תפילין, ואף שצררו בו את התפילין.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע\u0006\u0005]\u0006 ראיה שהכנה בלבד אינה מועלת, ממה ששנינו: \u0003אמר לאומן \"עשה לי תיק של ספר\u0004 תורה \u0003\",\u0004 \u0003או\u0004 שאמר לו \"עשה לי \u0003נרתיק של תפילין\", עד שלא נשתמש בהן\u0004 לתשמיש של \u0003קודש\u0004 — \u0003מותר להשתמש בהן\u0004 לתשמיש \u0003חול.\u0004 ואולם אם \u0003נשתמש בהן\u0004 כבר לתשמיש \u0003קודש\u0004 — \u0003אסור להשתמש בהן\u0004 לתשמיש \u0003חול.\u0004 משמע שהכנה לצורך דבר המקודש אינו מועילה, אלא צריך אף שימוש של ממש!","ומסבירים: \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים\u0006\u0005]\u0006 \u0003היא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 לענין תפילין: \u0003ציפן זהב או שטלה עליהן\u0004 (עשה עליהן טלאי) מ\u0003עור של בהמה טמאה\u0004 — \u0003פסולות\u0004 שתפילין נעשות רק מעור בהמה טהורה ולא מכל חומר אחר, ואם תפר עליהם \u0003עור בהמה טהורה\u0004 — \u0003כשירות, אף על פי שלא עיבדן\u0004 את העורות הללו \u0003לשמן,\u0004 כלומר, לצורך המצוה. \u0003רבן שמעון בן גמליאל אומר: אף\u0004 אם תפר עליהן \u0003עור בהמה טהורה\u0004 — \u0003פסולות, עד שיעבדו לשמן.\u0004 ומחלוקת זו האם יש צורך בעיבוד העור לשם מצוה קשורה למחלוקת בענין הזמנה אם יש צורך ויש חשיבות בהכנה מראש או די במעשה בלבד. ומן המחלוקת לענין עיבוד יש סיוע לשתי הדעות הנוגדות בענין הזמנה.","אגב הדברים, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרבא: מי איכא דוכתא דרמו ביה\u0004 \u0005[האם יש מקום ש\u0006קודם \u0005מטילים]\u0006 את ה\u0003מת\u0004 על המטה, ורק אז מתחילים \u0003וארגי\u0004 \u0005[לארוג]\u0006 \u0003בגד למת\u0004 כפי שנראה מאחד התירוצים שהזכרנו?! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן\u0006\u0005],\u0006 \u0003כגון שכבי\u0004 \u0005[המתים]\u0006 שב\u0003הרפניא\u0004 שמפני עניותם לא היו מספיקים להכין להם תכריכים קודם מותם.","\u0003דרש מרימר: הלכתא כוותיה\u0004 \u0005[הלכה כשיטת]\u0006 \u0003אביי\u0004 שהזמנה יש בה ממש, \u0003ורבנן אמרי\u0004 \u0005[וחכמים אומרים\u0006\u0005]:\u0006 \u0003הלכתא כוותיה\u0004 \u0005[הלכה כשיטת]\u0006 \u0003רבא,\u0004 ומסכמים לבסוף: \u0003הלכתא כוותיה\u0004 \u0005[הלכה כשיטת]\u0006 \u0003רבא\u0004 לכל דיני הכנה והזמנה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בתוספתא\u0005]:\u0006 \u0003הרוגי מלכות\u0004 שהרגם המלך בבית דינו מפני שחטאו לו — \u0003נכסיהן\u0004 שייכים \u0003למלך,\u0004 ואילו \u0003הרוגי בית דין\u0004 — \u0003נכסיהן\u0004 שייכים \u0003ליורשין. ר' יהודה אומר: אף הרוגי מלכות נכסיהן ליורשין. אמרו ליה\u0004 \u0005[לו]\u0006 \u0003לר' יהודה: והלא כבר נאמר\u0004 לאליהו: \u0003\"\u0004קום רד לקראת אחאב מלך ישראל אשר בשומרון \u0003הנה בכרם נבות אשר ירד שם לרשתו\"\u0004 (מלכים א' כא, יח), ומלשון הכתוב משמע שעל פי דין ירד אחאב לשם, ולא כגזלן. והרי זו ראיה שרכוש הרוגי המלכות שייך למלך על פי דין!","\u0003אמר להן: בן אחי אביו\u0004 של נבות \u0003היה\u0004 אחאב, \u0003וראוי ליורשו היה,\u0004 ומה שנכנס לנכסיו, מכוח ירושה נכנס ולא כמלך. אמרו לו: \u0003והלא הרבה בנים היו לו\u0004 לנבות, ומדוע לא ירשוהו הם?! \u0003אמר להן\u0004 ר' יהודה: \u0003אותו ואת בניו הרג\u0004 אחאב, \u0003שנאמר:\u0004 \u0003\"אם לא את דמי נבות ואת דמי בניו ראיתי\"\u0004 (מלכים א' ב' ט, כו). \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 מה עונים הם על הוכחה נצחת זו? לדעתם אין הכוונה שהרג את בניו, אלא \u0003ההוא בנים הראויין לצאת ממנו\u0004 שעדיין יכלו להוולד לו, ולכן דמו ודמי אותם בנים תלוים בצווארו.","ומקשים: \u0003בשלמא\u0004 \u0005[נניח\u0006\u0005]\u0006 \u0003למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר\u0006\u0005]\u0006 כי הרוגי מלכות \u0003נכסיהן\u0004 \u0003למלך, היינו דכתיב\u0004 \u0005[זהו שנאמר\u0006\u0005]\u0006 שהעידו עליו בהוראת איזבל עדות שקר כי \u0003\"ברך\u0004 (כלומר, קילל) \u0003נבות אלהים ומלך\"\u0004 (מלכים א' כא, יג), \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר\u0006\u0005]\u0006 כי \u0003נכסיהן ליורשין\u0004 — \u0003למה לי\u0004 לומר שקילל את ה\u0003מלך,\u0004 די היה אם היו מעידים שקילל את ה', ודינו מיתה!","ועונים: \u0003ולטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 שדקדקו בנוסח, על מנת לציין את חטאו נגד המלך מכיון שהמלכות היא היורשת, שקילל את ה\u0003אלהים למה לי?\u0004 והלא לצרכו די היה להעיד עליו שקילל את המלך וממילא נכסיו למלך, \u0003אלא\u0004 ודאי כוונתם היתה \u0003לאפושי ריתחא\u0004 \u0005[להוסיף כעס\u0006 בין הדיינים\u0005]\u0006 כשמאשימים אותו באשמה נוספת. \u0003הכי נמי לאפושי ריתחא\u0004 \u0005[כך גם כן\u0006 לשיטתי הכוונה בפירוט חטאיו היא \u0005להוסיף כעס],\u0006 אך מצד הדין הנכסים ליורשים, ואין מכאן ראיה.","ומקשים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר\u0006\u0005]\u0006 כי \u0003נכסיהן למלך, היינו דכתיב\u0004 \u0005[זהו שנאמר\u0006\u0005]\u0006 אחר שנודע כי יואב נוטה אחר אדוניה \u0003\"וינס יואב אל אהל ה' ויחזק בקרנות המזבח\"\u0004 (מלכים א' ב, כח), \u0003וכתיב\u0004 \u0005[ונאמר\u0006\u0005]\u0006 עוד: \u0003\"ויאמר לא (אצא) כי פה אמות\"\u0004 (מלכים א' ב, ל), שלא רצה למות בידי המלכות, כדי שלא יופקעו נכסיו. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר\u0006\u0005]\u0006 כי \u0003נכסיהן ליורשין, מאי נפקא ליה מינה\u0004 \u0005[מה יוצא לו מזה\u0006\u0005],\u0006 והלא בין כה וכה לא ירוויח דבר! ומשיבים: \u0003לחיי שעה,\u0004 כדי לחיות עוד זמן קצר נמלט לבית המקדש ואין איפוא הוכחה לשום צד במחלוקת.","כיון שהבאנו מעשה זה ביואב, ממשיכים לדון בו. אחר שנמלט יואב ונאחז בקרנות המזבח שלח שלמה המלך את בניהו בן יהוידע לפגוע בו, ואמר ליואב במצות המלך שיצא משם, ויואב סירב ואמר לו \"לא כי פה אמות\", נאמר: \u0003\"וישב בניהו את המלך דבר לאמר כה דבר יואב וכה ענני\"\u0004 (מלכים א' ב, ל), ומבארים את הענין: \u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]\u0006 יואב, \u0003זיל אימא ליה\u0004 \u0005[לך אמור לו]\u0006 לשלמה: \u0003תרתי לא תעביד בהאי גברא\u0004 \u0005[שני\u0006 דברים \u0005אל תעשה באותו אדם],\u0006 כלומר, בי, יואב, \u0003אי קטלית ליה\u0004 \u0005[אם הורג אתה אותו],\u0006 כלומר, אותי — \u0003קבול לטותיה דלטייה אבוך\u0004 \u0005[קבל\u0006 את \u0005קללתו שקללני אביך],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003שבקיה דליקו בלטותיה דלטייה אבוך\u0004 \u0005[הניחני שאקום בקללה שקללני אביך\u0006\u0005].\u0006 \u0003\"ויאמר לו המלך: עשה כאשר דבר ופגע בו וקברתו\"\u0004 (מלכים א' ב, לא), וקיבל על עצמו את הקללות.","\u0003אמר רב יהודה אמר רב: כל\u0004 ה\u0003קללות שקילל דוד את יואב\u0004 אכן \u0003נתקיימו בזרעו של דוד,\u0004 בבני שלמה, מפני הקללה שקיבל שלמה עליו, שנאמר: \u0003\"\u0004ו\u0003אל יכרת מבית יואב זב ומצרע ומחזיק בפלך ונפל בחרב וחסר לחם\"\u0004 (שמואל ב' ג, כט),","\u0003זב\u0004 בבני שלמה — \u0003מרחבעם, דכתיב\u0004 \u0005[שנאמר\u0006\u0005]:\u0006 \u0003\"והמלך רחבעם התאמץ לעלות במרכבה לנוס ירושל ם\"\u0004 (מלכים א' יב, יח), \u0003וכתיב \"וכל המרכב אשר ירכב עליו הזב יטמא\"\u0004 (ויקרא טו, ט) ולמדים מכאן ברמז (\"מרכב\" — \"מרכבה\") שרחבעם היה זב.","\u0003מצורע\u0004 בבני שלמה — \u0003מעוזיהו, דכתיב\u0004 \u0005[שנאמר\u0006\u0005]:\u0006 \u0003\"ובחזקתו גבה לבו עד להשחית וימעל בה' אלהיו ויבא אל היכל ה' להקטיר על מזבח הקטרת\"\u0004 (דברי הימים ב' כו, טז), \u0003וכתיב\u0004 \u0005[נאמר\u0006\u0005]:\u0006 \u0003\"והצרעת זרחה במצחו\"\u0004 (דברי הימים ב' כו, יט).","\u0003מחזיק בפלך\u0004 בבני שלמה — \u0003מאסא,\u0004 שנאמר: \u0003\"רק לעת זקנתו חלה את רגליו\"\u0004 (מלכים א' טו כג), \u0003ואמר ר' יהודה אמר רב: שאחזו\u0004 (חלה ב)מחלה הקרויה \u0003פודגרא. אמר ליה\u0004 \u0005[לו]\u0006 \u0003מר זוטרא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נחמן\u0004 \u0003לרב נחמן: היכי דמי\u0004 \u0005[כיצד היא\u0006\u0005],\u0006 מה יסוריה של מחלה זו? — \u0003אמר ליה\u0004 \u0005[לו]:\u0006 יסוריה הם \u0003כמחט\u0004 הדוקרת \u0003בבשר החי.\u0004 ושואלים: \u0003מנא\u0004 \u0005[מנין]\u0006 \u0003ידע\u0004 רב נחמן? ומשיבים: \u0003אי בעית אימא מיחש הוה חייש ביה\u0004 \u0005[אם תרצה אמור\u0006 כי בעצמו \u0005היה חש\u0006 וסובל, \u0005ממנה].\u0006 \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 כי \u0003מרביה הוה גמיר לה\u0004 \u0005[מרבו היה למוד זאת\u0006\u0005].\u0006 \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור\u0006\u0005],\u0006 כאמור: \u0003\"סוד ה' ליראיו ובריתו להודיעם\"\u0004 (תהלים כה, יד), שיראי ה' לומדים הרבה סודות מסודות הבריאה אף על פי שהם בעצמם לא התנסו בכך.","\u0003נופל בחרב\u0004 בבני שלמה — \u0003מיאשיהו, דכתיב\u0004 \u0005[שנאמר\u0006\u0005]:\u0006 \u0003\"וירו המורים למלך יאשיהו\"\u0004 (דברי הימים ב' לה, כג), \u0003ואמר רב יהודה אמר רב\u0004 בביאור הדבר: \u0003שעשו כל גופו ככברה.\u0004","\u0003וחסר לחם\u0004 בבני שלמה — \u0003מיכניה, דכתיב\u0004 \u0005[שנאמר\u0006\u0005]:\u0006 \u0003\"וארחתו ארחת תמיד נתנה לו\u0004 מאת המלך דבר יום ביומו כל ימי חייו\u0003\"\u0004 (מלכים ב' כה, ל). \u0003אמר רב יהודה אמר רב: היינו דאמרי אינשי\u0004 \u0005[זהו שאומרים אנשים\u0006\u0005]\u0006 בפתגם המקובל:"],["\u0003\"תהא לוטא ולא תהא לאטה\"\u0004 \u0005[תהיה מקולל ואל תהא מקלל\u0006\u0005],\u0006 שבסוף דבר חוזרות הקללות וחלות על המקלל.","\u0003אתיוה\u0004 \u0005[הביאוהו]\u0006 \u0003ליואב\u0004 לפני שלמה, \u0003דייניה\u0004 \u0005[\u0006ו\u0005דנו\u0006\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי טעמא קטלתיה\u0004 \u0005[מה טעם הרגתו]\u0006 את \u0003אבנר?\u0004 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003גואל הדם\u0004 של \u0003עשאל הואי\u0004 \u0005[הייתי\u0006\u0005],\u0006 ומאחר שהרג אבנר את עשהאל הרגתי את הרוצח, כחובת גואל הדם. ענה לו: \u0003עשאל רודף הוה\u0004 \u0005[היה\u0006\u0005],\u0006 שהרי נאמר שעשהאל רדף אחרי אבנר להורגו, ובדין הרגו אבנר בשעת הגנה על עצמו! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003היה לו להצילו\u0004 על ידי שיפגע בו \u0003באחד מאבריו\u0004 ולא יוסיף לרדוף אחריו, ולחנם הרגו. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא יכיל ליה\u0004 \u0005[יכול\u0006 היה \u0005לו],\u0006 שהיה ממהר לרוץ ולא יכול לכוון עד כדי כך. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003בדופן חמישית\u0004 בדיוק \u0003כיון ליה, דכתיב\u0004 \u0005[שנאמר\u0006\u0005]:\u0006 \u0003\"ויכהו אבנר באחרי החנית אל החמש\"\u0004 (שמואל ב' ב, כג), \u0003ואמר ר' יוחנן בדופן\u0004 (צלע) \u0003חמישית,\u0004 והוא \u0003במקום שמרה וכבד תלויין בו,\u0004 ואם עד כדי כך יכול היה לכוון — \u0003באחד מאיבריו לא יכיל ליה\u0004 \u0005[יכול\u0006 היה \u0005לו\u0006\u0005]?!\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ניזיל\u0004 \u0005[ילך]\u0006 \u0003אבנר,\u0004 שהרי מצאת לך טעם להצטדק ואין אתה חייב על הריגתו. \u0003מאי טעמא קטלתיה\u0004 \u0005[מה טעם הרגת אותו\u0006\u0005]\u0006 את \u0003עמשא? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003עמשא מורד במלכות הוה\u0004 \u0005[היה\u0006\u0005],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר\u0006\u0005]:\u0006 \u0003\"ויאמר המלך לעמשא הזעק לי את איש יהודה שלשת ימים\u0004 ואתה פה עמד. \u0003וילך עמשא להזעיק את יהודה ויוחר\u0004 מן המועד אשר יעדו\u0003\"\u0004 (שמואל ב' כ, ד–ה), וכעונש על כך הרגו יואב. \u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]\u0006 שלמה: \u0003עמשא, \"אכין\" ו\"רקין\" דרש,\u0004 כלומר, דרש מילים אלה בפסוקי המקרא לגבי משמעת למלך.","","","","כיצד — \u0003אשכחינהו דפתיח להו במסכתא\u0004 \u0005[מצא אותם,\u0006 את בני יהודה, \u0005שמתחילים ב\u0006לימוד \u0005מסכת\u0006\u0005],\u0006 \u0003אמר:\u0004 אמנם \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"כל איש אשר ימרה את פיך ולא ישמע את דבריך לכל אשר תצונו יומת\"\u0004 (יהושע א, יח), ומשמע שזהו כוחו של מלך בישראל. \u0003יכול אפילו לדברי תורה\u0004 להיבטל מהם בפקודת המלך — \u0003תלמוד לומר: \"רק חזק ואמץ\"\u0004 (יהושע א, יח), ומלשון \"רק\" שהיא לשון צמצום והגבלה למדנו שבדברים מסויימים כוחו של המלך מוגבל, ולפיכך לא הזעיק במועד את בני יהודה. ואם כן נהג עמשא כדין.","\u0003אלא\u0004 להיפך, \u0003ההוא גברא\u0004 \u0005[אותו אדם,\u0006 אתה\u0005],\u0006 \u0003מורד במלכות הוה\u0004 \u0005[היית\u0006\u0005]\u0006 \u0003דכתיב\u0004 \u0005[שנאמר\u0006\u0005]:\u0006 \u0003\"והשמעה באה עד יואב כי יואב נטה אחרי אדניה ואחרי אבשלום לא נטה\u0004 וינס יואב אל אוהל ה' ויחזק בקרנות המזבח\u0003\"\u0004 (מלכים א' ב, כח).","ואגב הדברים שואלים \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 שאחרי אבשלום \u0003\"לא נטה\"? אמר רב יהודה: שביקש\u0004 אמנם \u0003לנטות ולא נטה\u0004 בפועל. \u0003ומאי טעמא\u0004 \u0005[ומה טעם\u0006\u0005]\u0006 באמת \u0003\"\u0004אחרי אבשלום \u0003לא נטה\"? אמר ר' אלעזר: עדיין ליחלוחית של דוד קיימת,\u0004 שהיה עדיין כוחו עמו וחשש יואב מפניו. \u0003ר' יוסי בר' חנינא אמר: עדיין איצטגניני\u0004 (כוחו ומזלו) \u0003של\u0004 בית \u0003דוד קיימין,\u0004 ש\u0003אמר רב יהודה אמר רב: ארבע מאות ילדים\u0004 (בחורים צעירים) \u0003היו לו לדוד, כולן בני יפת תואר היו, ומגדלי בלורית היו, ומהלכין בראשי הגייסות היו, והן הן בעלי אגרופין של דוד,\u0004 וכיון שהם היו עם דוד חשש יואב מפני צבא זה.","","ומעירים: \u0003ופליגא\u0004 \u0005[וחלוקה\u0006\u0005]\u0006 גישה זו שרואה את גנותו של יואב, על דבריו של \u0003ר' אבא בר כהנא.\u0004 ש\u0003אמר ר' אבא בר כהנא: אילמלא דוד\u0004 שהיה עוסק בתורה \u0003לא עשה יואב מלחמה\u0004 ומצליח בה, \u0003ואילמלא יואב\u0004 שנלחם \u0003לא עסק דוד בתורה,\u0004 שנאמר: \u0003\"ויהי דוד עשה משפט וצדקה לכל עמו. ויואב בן צרויה על הצבא\"\u0004 (שמואל ב' ח, טו–טז) \u0003מה טעם דוד \"עשה משפט וצדקה לכל עמו\"\u0004 — \u0003משום\u0004 ש\u0003\"יואב\u0004 בן צרויה \u0003על הצבא\",\u0004 ועוזר לו ועושה מלחמותיו. \u0003ומה טעם \"יואב\u0004 בן צרויה \u0003על הצבא\"\u0004 — \u0003משום\u0004 ש\u0003\"דוד עשה משפט וצדקה לכל עמו\".\u0004","נאמר: \u0003\"ויצא יואב מעם דוד וישלח מלאכים אחרי אבנר וישבו אתו מבור הסרה\"\u0004 (שמואל ב' ג, כו) ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"בור הסירה\"? אמר ר' אבא בר כהנא: בור וסירה גרמו לו לאבנר שיהרג.\u0004 שסייע לשאול המלך ברדיפתו אחר דוד (כמבואר ברש\"י).","נאמר \u0003\"ויטהו יואב אל תוך השער לדבר אתו בשלי\"\u0004 (שמואל ב' ג, כז) \u0003אמר ר' יוחנן: שדנו דין סנהדרי,\u0004 כלומר, הביאו אל השער שהוא מקום הסנהדרין ושם דן אותו. כיצד? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי טעמא קטלתיה\u0004 \u0005[מה טעם הרגת אותו]\u0006 את \u0003עשאל?\u0004 אמר לו: \u0003עשאל רודף היה\u0004 ומותר היה לי להרגו כהגנה עצמית. אמר לו: \u0003היה לך להצילו באחד מאיבריו!\u0004 ענה לו: \u0003לא יכילי ליה\u0004 \u0005[יכולתי לו\u0006\u0005].\u0006 אמר לו יואב: \u0003השתא\u0004 \u0005[עכשיו]\u0006 \u0003בדופן חמישית כוונת ליה\u0004 \u0005[לו\u0006\u0005],\u0006 \u0003באחד מאיבריו לא יכלת\u0004 לכוון \u0003ליה\u0004 \u0005[לו\u0006\u0005]?!\u0006 ושואלים מה משמעות \u0003\"לדבר אתו בשלי\" אמר רב יהודה אמר רב: על עיסקי שלו\u0004 \u0005[מרמה]\u0006 ומה שנאמר שם: \u0003\"ויכהו שם (אל) החמש\"\u0004 (שמואל ב' ג, כז), \u0003אמר ר' יוחנן: בדופן\u0004 (צלע) \u0003חמישית. מקום שמרה וכבד תלויין בו.\u0004","","נאמר שאמר שלמה לבניהו בן יהוידע אודות יואב: \u0003\"והשיב ה' את דמו על ראשו אשר פגע בשני אנשים צדקים וטבים ממנו\"\u0004 (מלכים א' ב, לב) ומסבירים: \u0003\"טובים\"\u0004 — \u0003שהיו דורשין \"אכין\" ו\"רקין\", והוא לא דרש\u0004 הרי שהם גדולים ממנו בתורה. \u0003\"צדקים\"\u0004 — \u0003שהן\u0004 שניהם היו מעבדי שאול, וצוה להם שאול \u0003בפה\u0004 להרוג את אנשי נוב עיר הכהנים \u0003ולא עשו. והוא באיגרת\u0004 שקיבל להרוג את אוריה — \u0003עשה.\u0004","נאמר: \u0003\"ועמשא לא נשמר בחרב אשר ביד יואב\"\u0004 (שמואל ב' כ, י), \u0003אמר רב:\u0004 עמשא לא נשמר מפני \u0003שלא חשדו\u0004 ליואב שהוא מסוגל לרוצחו.","נאמר ביואב: \u0003\"ויקבר בביתו במדבר\"\u0004 (מלכים א' ב, לד), ושואלים: \u0003אטו\u0004 \u0005[וכי\u0006\u0005]\u0006 \u0003ביתו מדבר הוא? אמר רב יהודה אמר רב:\u0004 ביתו היה \u0003כמדבר, מה מדבר\u0004 מהותו שהוא \u0003מופקר לכל, אף ביתו של יואב\u0004 — \u0003מופקר לכל,\u0004 שהיה מכניס עניים ביד רחבה עד שהיו כבני ביתו. ועוד \u0003דבר אחר: כמדבר, מה מדבר מנוקה מגזל ועריות\u0004 (לפי שאין שם אדם), \u0003אף ביתו של יואב מנוקה\u0004 היה \u0003מגזל ועריות\u0004 מפני צדקתו. ועל הנאמר: \u0003\"ויואב יחיה את שאר העיר\"\u0004 (דברי הימים א' יא, ח), \u0003אמר רב יהודה:\u0004 לא רק שהיה דואג לעניי העיר, אלא \u0003אפילו מוניני וצחנתא טעים פריס להו\u0004",""],["\u0003ארבע מיתות נמסרו לבית דין\u0004 שבהן דנים עוברי עבירות שונים, ואלה הן: \u0003סקילה, שריפה, הרג\u0004 (בסייף) \u0003וחנק. ר' שמעון אומר,\u0004 הסדר לפי החומרה הוא: \u0003שריפה, סקילה, חנק והרג. זו מצות הנסקלין,\u0004 שבה דובר בפרק הקודם.","\u0003אמר רבא אמר רב סחורא אמר רב הונא: כל מקום ששנו חכמים דרך מניין,\u0004 שעשו רשימה של דברים שונים, \u0003אין מוקדם ומאוחר\u0004 במניינם, \u0003חוץ מ\u0004המשנה העוסקת ב\u0003שבעה סמנין\u0004 שבהם הדברים מנויים לפי סדר.","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003שבעה סמנין מעבירין על הכתם\u0004 שנמצא בבגד של אשה, לדעת אם זה דם, והוא מטמא כדם נידה, או שהכתם של צבע הוא — וטהור. והם: \u0003רוק תפל\u0004 (רוק של אדם לפני שאכל בבוקר), \u0003ומי גריסין\u0004 (רוק של אדם שלעס גריסי פולים), \u0003ומי רגלים, ונתר, ובורית, קמוליא, ואשלך\u0004 (אשלג), ואם נעלם הכתם בידוע שדם הוא.","\u0003וקתני סיפא\u0004 \u0005[ושנינו בסופה\u0006 של אותה משנה\u0005]\u0006 שסדר מניית הסממנים הוא בדווקא, ד\u0003אם העבירן\u0004 לאותן סממנים \u0003שלא כסידרן\u0004 שנימנה כאן, \u0003או שהעבירן שבעתן כאחד\u0004 — \u0003לא עשה ולא כלום.\u0004","\u0003רב פפא סבא\u0004 (הזקן), להבדילו מרב פפא סתם תלמידו של רבא, \u0003משמיה\u0004 \u0005[משמו\u0006\u0005]\u0006 של \u0003רב אמר: אף ארבע מיתות\u0004 כסדרן נשנו. \u0003מדקא מפליג\u0004 \u0005[כיון שחולק\u0006\u0005]\u0006 \u0003ר' שמעון\u0004 על הסדר, \u0003שמע מינה דוקא קתני\u0004 \u0005[למד מכאן\u0006 שבאופן \u0005מדוייק שנינו].\u0006 ומסבירים: \u0003ואידך\u0004 \u0005[והאחר\u0006\u0005],\u0006 רב הונא שלא מנה משנה זו בין הדברים המנויים כסדר, טעמו היה כי \u0003בפלוגתא\u0004 \u0005[ב\u0006מקום \u0005מחלוקת]\u0006 \u0003לא קא מיירי\u0004 \u0005[עסק\u0006\u0005],\u0006 ולא ציין מקום שהסדר אינו מקובל על הכל.","\u0003רב פפא אמר: אף סדר\u0004 עבודה של \u0003יומא\u0004 \u0005[יום\u0006 הכיפורים\u0005]\u0006 כסידורו הראוי נשנה, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003כל מעשה יום הכפורים האמורים\u0004 — \u0003על סדר\u0004 הם, ו\u0003אם הקדים מעשה לחבירו\u0004 — \u0003לא עשה ולא כלום.\u0004","\u0003ואידך\u0004 \u0005[והאחר\u0006\u0005]\u0006 שלא מנה זאת, מה טעמו? — \u0003ההוא חומרא בעלמא\u0004 \u0005[חומרה בלבד\u0006 היא\u0005],\u0006 שאמנם אם שינה הרי הוא מקלקל, אבל אין בסדר זה כדי לומר איזה מן העבודות מעולה יותר ואיזו פחות, אלא קביעה לסדר העבודה בלבד.","\u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע אמר:\u0004 \u0003אף סדר\u0004 קרבן \u0003תמיד\u0004 שבמשנה מדוקדק בסידורו. \u0003דקתני עלה\u0004 \u0005[ששנינו על כך\u0006\u0005]\u0006 בסופו: \u0003\"זהו סדר תמיד\",\u0004 משמע שכך בדיוק יש לעשות. \u0003ואידך\u0004 \u0005[והאחר\u0006\u0005]\u0006 שלא שנה זאת, לדעתו \u0003ההוא למצוה בעלמא\u0004 \u0005[בלבד\u0006\u0005]\u0006 אבל אינו מעכב אם אינו עושה כך.","ומעירים: והלכה זו שאמר רבא בשם רב סחורא \u0003לאפוקי\u0004 \u0005[להוציא\u0006\u0005]\u0006 \u0003ממצות חליצה\u0004 ולומר שהדברים המנויים שם אינם מחייבים שלא לשנות מסדר זה, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה \u0005],\u0006 \u0003מצות חליצה\u0004 כך היא: לאחר ש\u0003בא הוא ויבמתו לפני בית דין, היו נותנין לו\u0004 הדיינים \u0003עצה ההוגנת לו\u0004 אם ראוי לו לחלוץ או ליבם, \u0003שנאמר: \"וקראו לו זקני עירו ודברו אליו\"\u0004 (דברים כה, ח).","ואם החליט לחלוץ — \u0003היא אומרת: \"מאן יבמי\u0004 להקים לאחיו שם בישראל לא אבה יבמי\u0003\"\u0004 (דברים כה, ז), \u0003והוא אומר: \"לא חפצתי לקחתה\"\u0004 (דברים כה, ח). \u0003ובלשון הקדש היו אומרים\u0004 דברים אלה.","\u0003\"ונגשה יבמתו אליו לעיני הזקנים וחלצה נעלו\u0004 מעל רגלו \u0003וירקה בפניו\"\u0004 (דברים כה, ט), ויריקה זו צריכה להיות באופן שיהא \u0003רוק הנראה לדיינין. \"וענתה ואמרה ככה יעשה לאיש\u0004 אשר לא יבנה את בית אחיו. \u0003ונקרא שמו בישראל\u0004 בית חלוץ הנעל","\u0003\"\u0004(דברים כה, ט –י). \u0003ואמר רב יהודה: מצות חליצה\u0004 זה סדרה: \u0003קוראה\u0004 היא, \u0003וקורא\u0004 הוא את הדברים שצריכים לומר, כאמור. \u0003חולצת\u0004 נעלו, \u0003ורוקקת, וקוראה.\u0004","\u0003והוינן\u0004 \u0005[והיינו\u0006 דנים\u0005]\u0006 \u0003בה\u0004 בשאלה: \u0003מאי קא משמע לן?\u0004 \u0005[מה השמיע לנו]\u0006 בדברים אלה? והלא \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 המפורשת \u0003היא!\u0004 ומסבירים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]\u0006 — כי ה\u0003מצוה הכי\u0004 \u0005[כך\u0006\u0005]\u0006 היא, \u0003ואי אפיך\u0004 \u0005[ו\u0006אולם \u0005אם הפך\u0006 ושינה את הסדר\u0005]\u0006 — \u0003לית לן\u0004 \u0005[\u0006\u0005אין לנו]\u0006 \u0003בה\u0004 פגם, אלא החליצה חלה ותקפה גם כך. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כך\u0006\u0005]:\u0006 \u0003בין שהקדים חליצה לרקיקה, או רקיקה לחליצה\u0004 — \u0003מה שעשה עשוי,\u0004 והרי שאף שיש סדר מסויים במשנה אינו מעכב.","\u0003ולאפוקי\u0004 \u0005[ולהוציא\u0006\u0005]\u0006 \u0003מהא דתנן\u0004 \u0005[מזו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003כהן גדול משמש\u0004 בעבודת המקדש \u0003בשמונה כלים\u0004 (בגדים), \u0003והדיוט בארבעה.\u0004 ואלו הם הבגדים בהם משמש כהן הדיוט: \u0003בכתונת, במכנסים, במצנפת, ואבנט. מוסיף עליהן כהן גדול\u0004 ללבוש בשעת עבודה \u0003חושן, ואפוד, ומעיל, וציץ.\u0004 ולפי סדר זה משמע שהכתונת ראשונה היא.","\u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]\u0006 \u0003מנין שלא יהא דבר קודם למכנסים\u0004 — \u0003שנאמר:\u0004 \"כתונת בד קודש ילבש \u0003ומכנסי בד יהיו על בשרו\"\u0004 (ויקרא טז, ד), משמע שמכנסיים ראשונים הם, שכן לובשם ממש על בשרו. הרי שהמנין במשנה אינו כסדר הלבישה.","ושואלים: אם כן \u0003ו\u0004ה\u0003תנא מאי טעמא אקדמיה\u0004 \u0005[מה טעם הקדים]\u0006 את ה\u0003כתונת?\u0004 ועונים: \u0003משום דאקדמיה קרא\u0004 \u0005[שהקדים אותה הכתוב\u0006\u0005].\u0006 ושואלים: \u0003וקרא מאי טעמא אקדמיה\u0004 \u0005[והכתוב מה טעם הקדים אותה\u0006\u0005]?\u0006 ומסבירים: \u0003משום דמכסיא כולה גופיה\u0004 \u0005[שמכסה\u0006 את \u0005כל גופו\u0006\u0005]\u0006 — \u0003עדיפא ליה\u0004 \u0005[עדיפה\u0006 היא \u0005לו\u0006\u0005]\u0006 למקרא להקדימה.","שנינו במשנה את סדר המיתות \u0003סקילה, שריפה,\u0004 הרג, וחנק. ומסבירים על סמך מה קבעו חכמים סדר זה: כי מיתת \u0003סקילה חמורה משריפה,\u0004 וראיה לדבר — \u0003שכן ניתנה\u0004 הסקילה \u0003למגדף\u0004 (מקלל את ה') \u0003ולעובד עבודה זרה.\u0004 ו\u0003מאי חומרא\u0004 \u0005[מה החומרה\u0006\u0005]\u0006 שיש באלה יותר מבאחרים — \u0003שכן פושט ידו בעיקר\u0004 האמונה בה'.","ומקשים: \u0003אדרבה\u0004 (להיפך), נאמר ש\u0003שריפה חמורה, שכן ניתנה\u0004 כעונש \u0003לבת כהן שזינתה, ומאי חומרא\u0004 \u0005[ומה חומרה]\u0006 שיש בה — \u0003שכן מחללת\u0004 לא רק את עצמה אלא גם \u0003את אביה\u0004 על ידי עבירתה שלה."]]};
